#[repr(C)]
pub struct glsl_shader_prog_link {
    pub program_lookup_entry: wine_rb_entry,
    pub vs: glsl_vs_program,
    pub hs: glsl_hs_program,
    pub ds: glsl_ds_program,
    pub gs: glsl_gs_program,
    pub ps: glsl_ps_program,
    pub cs: glsl_cs_program,
    pub id: GLuint,
    pub constant_update_mask: DWORD,
    pub constant_version: u32,
    // C bitfields: shader_controlled_clip_distances:1, clip_distance_mask:8 (WINED3D_MAX_CLIP_DISTANCES), padding:23
    // Packed into a single DWORD to preserve layout; bit access must be done by masks/shifts.
    pub bitfields: DWORD,
}
// C bitfield accessors (bindgen's names: `x()` / `set_x(v)`), unsigned, LSB-first.
impl glsl_shader_prog_link {
    #[inline] pub fn shader_controlled_clip_distances(&self) -> u32 { (self.bitfields as u32 >> 0) & 0x1 }
    #[inline] pub fn set_shader_controlled_clip_distances(&mut self, v: u32) { self.bitfields = ((self.bitfields as u32 & !(0x1 << 0)) | ((v & 0x1) << 0)) as _; }
    #[inline] pub fn clip_distance_mask(&self) -> u32 { (self.bitfields as u32 >> 1) & 0xff }
    #[inline] pub fn set_clip_distance_mask(&mut self, v: u32) { self.bitfields = ((self.bitfields as u32 & !(0xff << 1)) | ((v & 0xff) << 1)) as _; }
}

