unsafe extern "C" fn debug_gl_shader_type(type_0: GLenum) -> *const i8 {
    match type_0 {
        GL_VERTEX_SHADER => return b"GL_VERTEX_SHADER\0".as_ptr() as *const i8,
        GL_TESS_CONTROL_SHADER => return b"GL_TESS_CONTROL_SHADER\0".as_ptr() as *const i8,
        GL_TESS_EVALUATION_SHADER => return b"GL_TESS_EVALUATION_SHADER\0".as_ptr() as *const i8,
        GL_GEOMETRY_SHADER => return b"GL_GEOMETRY_SHADER\0".as_ptr() as *const i8,
        GL_FRAGMENT_SHADER => return b"GL_FRAGMENT_SHADER\0".as_ptr() as *const i8,
        GL_COMPUTE_SHADER => return b"GL_COMPUTE_SHADER\0".as_ptr() as *const i8,
        _ => {
            return wine_dbg_sprintf(
                b"UNKNOWN(%#x)\0".as_ptr() as *const i8,
                type_0,
            );
        }
    }
}

unsafe extern "C" fn shader_glsl_get_prefix(mut type_0: wined3d_shader_type) -> *const i8 {
    match type_0 as u32 {
        WINED3D_SHADER_TYPE_VERTEX => {
            return b"vs\0".as_ptr() as *const i8;
        }
        WINED3D_SHADER_TYPE_HULL => {
            return b"hs\0".as_ptr() as *const i8;
        }
        WINED3D_SHADER_TYPE_DOMAIN => {
            return b"ds\0".as_ptr() as *const i8;
        }
        WINED3D_SHADER_TYPE_GEOMETRY => {
            return b"gs\0".as_ptr() as *const i8;
        }
        WINED3D_SHADER_TYPE_PIXEL => {
            return b"ps\0".as_ptr() as *const i8;
        }
        WINED3D_SHADER_TYPE_COMPUTE => {
            return b"cs\0".as_ptr() as *const i8;
        }
        _ => {
            FIXME!("Unhandled shader type %#x.\n", type_0);
            return b"unknown\0".as_ptr() as *const i8;
        }
    }
}

unsafe extern "C" fn shader_glsl_get_version(gl_info: *const wined3d_gl_info) -> core::ffi::c_uint {
    if (*gl_info).glsl_version >= MAKEDWORD_VERSION!(4, 40) {
        return 440;
    } else if (*gl_info).glsl_version >= MAKEDWORD_VERSION!(1, 50) {
        return 150;
    } else if (*gl_info).glsl_version >= MAKEDWORD_VERSION!(1, 30) {
        return 130;
    } else {
        return 120;
    }
}

unsafe extern "C" fn shader_glsl_add_version_declaration(
    buffer: *mut wined3d_string_buffer,
    gl_info: *const wined3d_gl_info,
) {
    shader_addline(buffer, b"#version %u\n\0".as_ptr() as *const i8, shader_glsl_get_version(gl_info));
}

unsafe extern "C" fn shader_glsl_full_ffp_varyings(
    gl_info: *const wined3d_gl_info,
) -> ::core::ffi::c_uint {
    return ((*gl_info).limits.glsl_varyings
        >= (if (*gl_info).supported[WINED3D_GL_LEGACY_CONTEXT as usize] != 0 {
            WINED3D_MAX_FFP_TEXTURES * 4
        } else {
            (WINED3D_MAX_FFP_TEXTURES + 2) * 4
                + 1
        }) as ::core::ffi::c_uint) as ::core::ffi::c_int as ::core::ffi::c_uint;
}

unsafe extern "C" fn shader_glsl_append_imm_vec(
    mut buffer: *mut wined3d_string_buffer,
    mut values: *const ::core::ffi::c_float,
    mut size: ::core::ffi::c_uint,
    mut gl_info: *const wined3d_gl_info,
) {
    let mut int_values: *const ::core::ffi::c_int = values as *const ::core::ffi::c_int;
    let mut i: ::core::ffi::c_uint = 0;
    let mut str: [::core::ffi::c_char; 17] = [0; 17];
    if (*gl_info).supported[ARB_SHADER_BIT_ENCODING as usize] == 0 {
        if size > 1 {
            shader_addline(
                buffer,
                b"vec%u(\0" as *const u8 as *const ::core::ffi::c_char,
                size,
            );
        }
        i = 0;
        while i < size {
            wined3d_ftoa(
                *values.add(i as usize),
                &raw mut str as *mut ::core::ffi::c_char,
            );
            shader_addline(
                buffer,
                if i != 0 {
                    b", %s\0" as *const u8 as *const ::core::ffi::c_char
                } else {
                    b"%s\0" as *const u8 as *const ::core::ffi::c_char
                },
                &raw mut str as *mut ::core::ffi::c_char,
            );
            i = i.wrapping_add(1);
        }
        if size > 1 {
            shader_addline(buffer, b")\0" as *const u8 as *const ::core::ffi::c_char);
        }
        return;
    }
    shader_addline(
        buffer,
        b"intBitsToFloat(\0" as *const u8 as *const ::core::ffi::c_char,
    );
    if size > 1 {
        shader_addline(
            buffer,
            b"ivec%u(\0" as *const u8 as *const ::core::ffi::c_char,
            size,
        );
    }
    i = 0;
    while i < size {
        wined3d_ftoa(
            *values.add(i as usize),
            &raw mut str as *mut ::core::ffi::c_char,
        );
        shader_addline(
            buffer,
            if i != 0 {
                b", %#x /* %s */\0" as *const u8 as *const ::core::ffi::c_char
            } else {
                b"%#x /* %s */\0" as *const u8 as *const ::core::ffi::c_char
            },
            *int_values.add(i as usize),
            &raw mut str as *mut ::core::ffi::c_char,
        );
        i = i.wrapping_add(1);
    }
    if size > 1 {
        shader_addline(buffer, b")\0" as *const u8 as *const ::core::ffi::c_char);
    }
    shader_addline(buffer, b")\0" as *const u8 as *const ::core::ffi::c_char);
}

unsafe extern "C" fn shader_glsl_append_imm_ivec(
    mut buffer: *mut wined3d_string_buffer,
    mut values: *const ::core::ffi::c_int,
    mut size: ::core::ffi::c_uint,
) {
    let mut i: ::core::ffi::c_int = 0;
    if size == 0 || size > 4 {
        ERR!("Invalid vector size %u.\n", size);
        return;
    }
    if size > 1 {
        shader_addline(
            buffer,
            b"ivec%u(\0" as *const u8 as *const ::core::ffi::c_char,
            size,
        );
    }
    i = 0;
    while (i as ::core::ffi::c_uint) < size {
        shader_addline(
            buffer,
            if i != 0 {
                b", %#x\0" as *const u8 as *const ::core::ffi::c_char
            } else {
                b"%#x\0" as *const u8 as *const ::core::ffi::c_char
            },
            *values.offset(i as isize),
        );
        i += 1;
    }
    if size > 1 {
        shader_addline(buffer, b")\0" as *const u8 as *const ::core::ffi::c_char);
    }
}
#[no_mangle]
pub unsafe extern "C" fn print_glsl_info_log(gl_info: *const wined3d_gl_info, id: GLuint, program: BOOL) {
    let mut length: core::ffi::c_int = 0;
    let mut log: *mut core::ffi::c_char;

    if !(WARN_ON!(__wine_dbch_d3d_shader) != 0) && !(FIXME_ON!(__wine_dbch_d3d_shader) != 0) {
        return;
    }

    if program != 0 {
        ((*gl_info).gl_ops.ext.p_glGetProgramiv.unwrap_unchecked())(id, GL_INFO_LOG_LENGTH, core::ptr::addr_of_mut!(length));
    } else {
        ((*gl_info).gl_ops.ext.p_glGetShaderiv.unwrap_unchecked())(id, GL_INFO_LOG_LENGTH, core::ptr::addr_of_mut!(length));
    }

    /* A size of 1 is just a null-terminated string, so the log should be bigger than
     * that if there are errors. */
    if length > 1 {
        let mut ptr: *const core::ffi::c_char = core::ptr::null();
        let mut end: *const core::ffi::c_char = core::ptr::null();
        let mut line: *const core::ffi::c_char = core::ptr::null();

        log = malloc(length as usize) as *mut core::ffi::c_char;
        if program != 0 {
            ((*gl_info).gl_ops.ext.p_glGetProgramInfoLog.unwrap_unchecked())(id, length as GLsizei, core::ptr::null_mut::<GLsizei>(), log as *mut GLchar);
        } else {
            ((*gl_info).gl_ops.ext.p_glGetShaderInfoLog.unwrap_unchecked())(id, length as GLsizei, core::ptr::null_mut::<GLsizei>(), log as *mut GLchar);
        }

        ptr = log;
        /* The info log is supposed to be zero-terminated. Note that at least
         * some versions of fglrx don't terminate the string properly. The
         * reported length does include the supposed terminator though, so we
         * don't care here. */
        end = ptr.offset((length - 1) as isize) as *const core::ffi::c_char;
        if ((*gl_info).quirks & WINED3D_QUIRK_INFO_LOG_SPAM) != 0 {
            WARN!("Info log received from GLSL shader #%u:\n", id);
            loop {
                line = wined3d_get_line(core::ptr::addr_of_mut!(ptr), end);
                if line.is_null() {
                    break;
                }
                WARN!("    %.*s", (ptr.offset_from(line)) as core::ffi::c_int, line);
            }
        } else {
            loop {
                line = wined3d_get_line(core::ptr::addr_of_mut!(ptr), end);
                if line.is_null() {
                    break;
                }
            }
        }
        free(log as *mut core::ffi::c_void);
    }
}

unsafe extern "C" fn shader_glsl_compile(gl_info: *const wined3d_gl_info, shader: GLuint, mut src: *const core::ffi::c_char) {
    let mut ptr: *const core::ffi::c_char = core::ptr::null();
    let mut end: *const core::ffi::c_char = core::ptr::null();
    let mut line: *const core::ffi::c_char = core::ptr::null();

    if ((TRACE_ON!(__wine_dbch_d3d_shader)) != 0) {
        ptr = src;
        end = ptr.offset(strlen(ptr) as isize);
        loop {
            line = wined3d_get_line(&raw mut ptr, end);
            if line.is_null() {
                break;
            }
            WINE_TRACE_!(__wine_dbch_d3d_shader,
                b"    %.*s\0".as_ptr() as *const core::ffi::c_char,
                ptr.offset_from(line) as core::ffi::c_int,
                line,
            );
        }
    }

    ((*gl_info).gl_ops.ext.p_glShaderSource.unwrap_unchecked())(
        shader,
        1,
        &raw mut src as *const *const GLchar,
        core::ptr::null::<GLint>(),
    );
    checkGLcall!(gl_info, b"glShaderSource\0".as_ptr() as *const core::ffi::c_char);
    ((*gl_info).gl_ops.ext.p_glCompileShader.unwrap_unchecked())(shader);
    checkGLcall!(gl_info, b"glCompileShader\0".as_ptr() as *const core::ffi::c_char);
    print_glsl_info_log(gl_info, shader, (FALSE) as BOOL);
}

unsafe extern "C" fn shader_glsl_dump_program_source(gl_info: *const wined3d_gl_info, program: GLuint) {
    let mut i: GLint = 0;
    let mut shader_count: GLint = 0;
    let mut source_size: GLint = -1;
    let mut shaders: *mut GLuint = core::ptr::null_mut::<GLuint>();
    let mut source: *mut core::ffi::c_char = core::ptr::null_mut::<core::ffi::c_char>();
    (*gl_info)
        .gl_ops
        .ext
        .p_glGetProgramiv
        .unwrap_unchecked()(
        program,
        GL_ATTACHED_SHADERS as GLenum,
        core::ptr::addr_of_mut!(shader_count),
    );
    shaders = calloc(
        (shader_count as size_t) as _,
        (core::mem::size_of::<GLuint>() as size_t) as _,
    ) as *mut GLuint;
    if shaders.is_null() {
        ERR!("Failed to allocate shader array memory.\n");
        return;
    }
    (*gl_info)
        .gl_ops
        .ext
        .p_glGetAttachedShaders
        .unwrap_unchecked()(
        program,
        shader_count as GLsizei,
        core::ptr::null_mut::<GLsizei>(),
        shaders,
    );
    i = 0;
    while i < shader_count {
        let mut ptr: *const core::ffi::c_char = core::ptr::null::<core::ffi::c_char>();
        let mut end: *const core::ffi::c_char = core::ptr::null::<core::ffi::c_char>();
        let mut line: *const core::ffi::c_char = core::ptr::null::<core::ffi::c_char>();
        let mut tmp: GLint = 0;
        (*gl_info)
            .gl_ops
            .ext
            .p_glGetShaderiv
            .unwrap_unchecked()(
            *shaders.offset(i as isize),
            GL_SHADER_SOURCE_LENGTH as GLenum,
            core::ptr::addr_of_mut!(tmp),
        );
        if source_size < tmp {
            free(source as *mut core::ffi::c_void);
            source = malloc(tmp as size_t) as *mut core::ffi::c_char;
            if source.is_null() {
                ERR!("Failed to allocate %d bytes for shader source.\n", tmp);
                free(shaders as *mut core::ffi::c_void);
                return;
            }
            source_size = tmp;
        }
        (*gl_info)
            .gl_ops
            .ext
            .p_glGetShaderSource
            .unwrap_unchecked()(
            *shaders.offset(i as isize),
            source_size as GLsizei,
            core::ptr::null_mut::<GLsizei>(),
            source as *mut GLchar,
        );
        ptr = source;
        end = ptr.offset((tmp - 1) as isize) as *const core::ffi::c_char;
        FIXME!("Shader %u:\n", *shaders.offset(i as isize));
        (*gl_info)
            .gl_ops
            .ext
            .p_glGetShaderiv
            .unwrap_unchecked()(
            *shaders.offset(i as isize),
            GL_SHADER_TYPE as GLenum,
            core::ptr::addr_of_mut!(tmp),
        );
        FIXME!("    GL_SHADER_TYPE: %s.\n", debug_gl_shader_type(tmp as GLenum));
        (*gl_info)
            .gl_ops
            .ext
            .p_glGetShaderiv
            .unwrap_unchecked()(
            *shaders.offset(i as isize),
            GL_COMPILE_STATUS as GLenum,
            core::ptr::addr_of_mut!(tmp),
        );
        FIXME!("    GL_COMPILE_STATUS: %d.\n", tmp);
        FIXME!("\n");
        loop {
            line = wined3d_get_line(core::ptr::addr_of_mut!(ptr), end);
            if line.is_null() {
                break;
            }
            FIXME!("    %.*s\n", ptr.offset_from(line) as core::ffi::c_longlong as core::ffi::c_int, line);
        }
        FIXME!("\n");
        i += 1;
    }
    free(source as *mut core::ffi::c_void);
    free(shaders as *mut core::ffi::c_void);
}
#[no_mangle]
pub unsafe extern "C" fn shader_glsl_validate_link(gl_info: *const wined3d_gl_info, program: GLuint) {
    let mut tmp: GLint = 0;

    if ((TRACE_ON!(__wine_dbch_d3d_shader)) == 0) && ((FIXME_ON!(__wine_dbch_d3d_shader)) == 0) {
        return;
    }

    (*gl_info)
        .gl_ops
        .ext
        .p_glGetProgramiv
        .unwrap_unchecked()(
        program,
        GL_LINK_STATUS as GLenum,
        core::ptr::addr_of_mut!(tmp),
    );
    if tmp == 0 {
        if ((FIXME_ON!(__wine_dbch_d3d_shader)) != 0) {
            FIXME!("Program %u link status invalid.\n", program);
        }
        shader_glsl_dump_program_source(gl_info, program);
    }

    print_glsl_info_log(gl_info, program, (TRUE) as BOOL);
}

unsafe extern "C" fn create_resource_bindings(
    gl_info: *const wined3d_gl_info,
    shader_type: wined3d_shader_type,
    count: *mut ::core::ffi::c_uint,
) -> *mut vkd3d_shader_resource_binding {
    let mut bindings: *mut vkd3d_shader_resource_binding = core::ptr::null_mut();
    let mut visibility: vkd3d_shader_visibility;
    let mut base: ::core::ffi::c_uint = 0;
    let mut i: ::core::ffi::c_uint = 0;

    wined3d_gl_limits_get_uniform_block_range(
        core::ptr::addr_of!((*gl_info).limits),
        shader_type,
        core::ptr::addr_of_mut!(base),
        count,
    );
    bindings = calloc(
        (*count as usize) as _,
        (core::mem::size_of::<vkd3d_shader_resource_binding>()) as _,
    ) as *mut vkd3d_shader_resource_binding;
    if bindings.is_null() {
        return core::ptr::null_mut();
    }

    visibility = vkd3d_shader_visibility_from_wined3d(shader_type);
    i = 0 as ::core::ffi::c_uint;
    while i < *count {
        (*bindings.offset(i as isize)).type_ = VKD3D_SHADER_DESCRIPTOR_TYPE_CBV;
        (*bindings.offset(i as isize)).register_space = 0 as ::core::ffi::c_uint;
        (*bindings.offset(i as isize)).register_index = i;
        (*bindings.offset(i as isize)).shader_visibility = visibility;
        (*bindings.offset(i as isize)).flags = VKD3D_SHADER_BINDING_FLAG_BUFFER as ::core::ffi::c_uint;
        (*bindings.offset(i as isize)).binding.set = 0 as ::core::ffi::c_uint;
        (*bindings.offset(i as isize)).binding.binding = base.wrapping_add(i);
        (*bindings.offset(i as isize)).binding.count = 1 as ::core::ffi::c_uint;
        i = i.wrapping_add(1);
    }

    return bindings;
}

unsafe extern "C" fn create_combined_resource_sampler_bindings(
    mut context_gl: *const wined3d_context_gl,
    mut shader: *const wined3d_shader,
    mut count: *mut ::core::ffi::c_uint,
) -> *mut vkd3d_shader_combined_resource_sampler {
    let mut bindings: *mut vkd3d_shader_combined_resource_sampler =
        ::core::ptr::null_mut::<vkd3d_shader_combined_resource_sampler>();
    let mut bind_idx: ::core::ffi::c_uint = 0;
    let mut shader_sampler_count: ::core::ffi::c_uint = 0;
    let mut base: ::core::ffi::c_uint = 0;
    let mut i: ::core::ffi::c_uint = 0;
    let mut entry: *mut wined3d_shader_sampler_map_entry =
        ::core::ptr::null_mut::<wined3d_shader_sampler_map_entry>();
    let mut visibility: vkd3d_shader_visibility = VKD3D_SHADER_VISIBILITY_ALL;
    let mut tex_unit_map: *const ::core::ffi::c_uint = ::core::ptr::null::<::core::ffi::c_uint>();
    tex_unit_map = wined3d_context_gl_get_tex_unit_mapping(
        context_gl,
        &raw const (*shader).reg_maps.shader_version,
        &raw mut base,
        count,
    );
    shader_sampler_count = (*shader).reg_maps.sampler_map.count as ::core::ffi::c_uint;
    if shader_sampler_count > *count {
        WINE_FIXME!("Shader %p needs %u samplers, but only %u are supported.\n", shader, shader_sampler_count, *count);
        return ::core::ptr::null_mut::<vkd3d_shader_combined_resource_sampler>();
    }
    *count = min!(shader_sampler_count, *count);

    bindings = calloc(
        (*count as usize) as _,
        (::core::mem::size_of::<vkd3d_shader_combined_resource_sampler>() as usize) as _,
    ) as *mut vkd3d_shader_combined_resource_sampler;
    if bindings.is_null() {
        return ::core::ptr::null_mut::<vkd3d_shader_combined_resource_sampler>();
    }
    visibility = vkd3d_shader_visibility_from_wined3d((*shader).reg_maps.shader_version.type_);
    i = 0 as ::core::ffi::c_uint;
    while i < *count {
        entry = (*shader).reg_maps.sampler_map.entries.offset(i as isize)
            as *mut wined3d_shader_sampler_map_entry;
        bind_idx = base.wrapping_add((*entry).bind_idx);
        if !tex_unit_map.is_null() {
            bind_idx = *tex_unit_map.offset(bind_idx as isize);
        }
        (*bindings.offset(i as isize)).resource_space = 0 as ::core::ffi::c_uint;
        (*bindings.offset(i as isize)).resource_index = (*entry).resource_idx;
        (*bindings.offset(i as isize)).sampler_space = 0 as ::core::ffi::c_uint;
        (*bindings.offset(i as isize)).sampler_index = (*entry).sampler_idx;
        (*bindings.offset(i as isize)).shader_visibility = visibility;
        (*bindings.offset(i as isize)).flags = VKD3D_SHADER_BINDING_FLAG_IMAGE as ::core::ffi::c_uint;
        (*bindings.offset(i as isize)).binding.set = 0 as ::core::ffi::c_uint;
        (*bindings.offset(i as isize)).binding.binding = bind_idx;
        (*bindings.offset(i as isize)).binding.count = 1 as ::core::ffi::c_uint;
        i = i.wrapping_add(1);
    }
    return bindings;
}

unsafe extern "C" fn shader_glsl_generate_vkd3d_shader(
    context_gl: *const wined3d_context_gl,
    priv_0: *mut shader_glsl_priv,
    shader: *const wined3d_shader,
    gl_shader_type: GLenum,
) -> GLuint {
    let version: *const wined3d_shader_version = core::ptr::addr_of!((*shader).reg_maps.shader_version);
    let mut combined_samplers: *mut vkd3d_shader_combined_resource_sampler = core::ptr::null_mut();
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut xfb_info: vkd3d_shader_transform_feedback_info = core::mem::zeroed();
    let mut binding_count: u32 = 0;
    let mut combined_sampler_count: u32 = 0;
    let mut interface_info: vkd3d_shader_interface_info = core::mem::zeroed();
    let mut so_desc: *const wined3d_stream_output_desc = core::ptr::null();
    let mut bindings: *mut vkd3d_shader_resource_binding = core::ptr::null_mut();
    let mut info: vkd3d_shader_compile_info = core::mem::zeroed();
    let mut glsl: vkd3d_shader_code = core::mem::zeroed();
    let mut shader_id: GLuint = 0;
    let mut messages: *mut core::ffi::c_char = core::ptr::null_mut();
    let mut ret: i32 = 0;
    let compile_options: [vkd3d_shader_compile_option; 1] = [vkd3d_shader_compile_option {
        name: VKD3D_SHADER_COMPILE_OPTION_API_VERSION,
        value: VKD3D_SHADER_API_VERSION_1_6 as u32,
    }];

    if (*version).type_ as u32 == WINED3D_SHADER_TYPE_GEOMETRY as u32 && {
        so_desc = (*shader).u.gs.so_desc;
        !so_desc.is_null()
    } {
        xfb_info.type_ = VKD3D_SHADER_STRUCTURE_TYPE_TRANSFORM_FEEDBACK_INFO;
        xfb_info.next = core::ptr::null();
        xfb_info.elements = (*so_desc).elements as *const vkd3d_shader_transform_feedback_element;
        xfb_info.element_count = (*so_desc).element_count;
        xfb_info.buffer_strides = core::ptr::addr_of!((*so_desc).buffer_strides) as *const u32;
        xfb_info.buffer_stride_count = (*so_desc).buffer_stride_count;

        interface_info.next = core::ptr::addr_of_mut!(xfb_info) as *const core::ffi::c_void;
    } else {
        interface_info.next = core::ptr::null();
    }

    bindings = create_resource_bindings(gl_info, (*version).type_, core::ptr::addr_of_mut!(binding_count));
    if bindings.is_null() {
        ERR!("Failed to create resource bindings.\n");
        return 0;
    }

    combined_samplers = create_combined_resource_sampler_bindings(context_gl, shader, core::ptr::addr_of_mut!(combined_sampler_count));
    if combined_samplers.is_null() {
        ERR!("Failed to create combined sampler bindings.\n");
        free(bindings as *mut core::ffi::c_void);
        return 0;
    }

    interface_info.type_ = VKD3D_SHADER_STRUCTURE_TYPE_INTERFACE_INFO;
    interface_info.bindings = bindings;
    interface_info.binding_count = binding_count;
    interface_info.push_constant_buffers = core::ptr::null();
    interface_info.push_constant_buffer_count = 0;
    interface_info.combined_samplers = combined_samplers;
    interface_info.combined_sampler_count = combined_sampler_count;
    interface_info.uav_counters = core::ptr::null();
    interface_info.uav_counter_count = 0;

    info.type_ = VKD3D_SHADER_STRUCTURE_TYPE_COMPILE_INFO;
    info.next = core::ptr::addr_of_mut!(interface_info) as *const core::ffi::c_void;
    if (*shader).source_type as u32 == VKD3D_SHADER_SOURCE_D3D_BYTECODE as u32 {
        info.source.code = (*shader).function as *const core::ffi::c_void;
        info.source.size = (*shader).functionLength as usize;
    } else {
        info.source.code = (*shader).byte_code;
        info.source.size = (*shader).byte_code_size as usize;
    }
    info.source_type = (*shader).source_type;
    info.target_type = VKD3D_SHADER_TARGET_GLSL;
    info.options = core::ptr::addr_of!(compile_options) as *const vkd3d_shader_compile_option;
    info.option_count = ARRAY_SIZE!(compile_options) as u32;
    info.log_level = VKD3D_SHADER_LOG_WARNING;
    info.source_name = core::ptr::null();

    ret = vkd3d_shader_compile(
        core::ptr::addr_of_mut!(info),
        core::ptr::addr_of_mut!(glsl),
        core::ptr::addr_of_mut!(messages),
    );
    if !messages.is_null() && *messages as i32 != 0 && ((FIXME_ON!(__wine_dbch_d3d_shader)) != 0) {
        let mut ptr: *const core::ffi::c_char = core::ptr::null();
        let mut end: *const core::ffi::c_char = core::ptr::null();
        let mut line: *const core::ffi::c_char = core::ptr::null();

        FIXME!("Shader log:\n");
        ptr = messages;
        end = ptr.offset(strlen(ptr) as isize);
        loop {
            line = wined3d_get_line(core::ptr::addr_of_mut!(ptr), end);
            if line.is_null() {
                break;
            }
            FIXME!(
                "    %.*s\n",
                ptr.offset_from(line) as i32,
                line,
            );
        }
        FIXME!("\n");
    }
    vkd3d_shader_free_messages(messages);
    free(combined_samplers as *mut core::ffi::c_void);
    free(bindings as *mut core::ffi::c_void);

    if ret < 0 {
        ERR!("Failed to compile shader, ret %d.\n", ret);
        return 0;
    }

    shader_id = ((*gl_info).gl_ops.ext.p_glCreateShader.unwrap_unchecked())(gl_shader_type);
    if shader_id == 0 {
        ERR!("Failed to create shader.\n");
        vkd3d_shader_free_shader_code(core::ptr::addr_of_mut!(glsl));
        return 0;
    }

    TRACE!("Compiling shader object %u.\n", shader_id);

    ((*gl_info).gl_ops.ext.p_glShaderSource.unwrap_unchecked())(
        shader_id,
        1,
        core::ptr::addr_of_mut!(glsl.code) as *const *const GLchar,
        core::ptr::addr_of!(glsl.size) as *const GLint,
    );
    checkGLcall!(gl_info, "glShaderSource");
    ((*gl_info).gl_ops.ext.p_glCompileShader.unwrap_unchecked())(shader_id);
    checkGLcall!(gl_info, "glCompileShader");
    print_glsl_info_log(gl_info, shader_id, (FALSE) as BOOL);

    vkd3d_shader_free_shader_code(core::ptr::addr_of_mut!(glsl));

    return shader_id;
}

unsafe extern "C" fn shader_glsl_use_layout_qualifier(gl_info: *const wined3d_gl_info) -> BOOL {
    return (shader_glsl_get_version(gl_info) >= 140) as BOOL;
}

unsafe extern "C" fn shader_glsl_use_layout_binding_qualifier(gl_info: *const wined3d_gl_info) -> BOOL {
    return ((*gl_info).supported[ARB_SHADING_LANGUAGE_420PACK as usize] != 0
        && shader_glsl_use_layout_qualifier(gl_info) != 0) as BOOL;
}

unsafe extern "C" fn shader_glsl_init_uniform_block_bindings(
    gl_info: *const wined3d_gl_info,
    priv_: *mut shader_glsl_priv,
    program_id: GLuint,
    reg_maps: *const wined3d_shader_reg_maps,
) {
    let prefix: *const ::core::ffi::c_char = shader_glsl_get_prefix((*reg_maps).shader_version.type_);
    let mut name: *mut wined3d_string_buffer = core::ptr::null_mut();
    let mut i: ::core::ffi::c_uint = 0;
    let mut base: ::core::ffi::c_uint = 0;
    let mut count: ::core::ffi::c_uint = 0;
    let mut block_idx: GLuint = 0;

    if shader_glsl_use_layout_binding_qualifier(gl_info) != 0 {
        return;
    }

    name = string_buffer_get(core::ptr::addr_of_mut!((*priv_).string_buffers));
    wined3d_gl_limits_get_uniform_block_range(
        core::ptr::addr_of!((*gl_info).limits),
        (*reg_maps).shader_version.type_,
        core::ptr::addr_of_mut!(base),
        core::ptr::addr_of_mut!(count),
    );
    i = 0;
    while i < count {
        if !((*reg_maps).cb_sizes[i as usize] == 0) {
            string_buffer_sprintf(
                name,
                b"block_%s_cb%u\0".as_ptr() as *const ::core::ffi::c_char,
                prefix,
                i,
            );
            block_idx = ((*gl_info).gl_ops.ext.p_glGetUniformBlockIndex.unwrap_unchecked())(program_id, (*name).buffer);
            ((*gl_info).gl_ops.ext.p_glUniformBlockBinding.unwrap_unchecked())(
                program_id,
                block_idx,
                (base as GLuint).wrapping_add(i as GLuint),
            );
        }
        i = i.wrapping_add(1);
    }
    checkGLcall!(gl_info, b"glUniformBlockBinding\0".as_ptr() as *const ::core::ffi::c_char);
    string_buffer_release(core::ptr::addr_of_mut!((*priv_).string_buffers), name);
}

unsafe extern "C" fn shader_glsl_load_samplers_range(gl_info: *const wined3d_gl_info, priv_: *mut shader_glsl_priv, program_id: GLuint, prefix: *const ::core::ffi::c_char, base: ::core::ffi::c_uint, count: ::core::ffi::c_uint, tex_unit_map: *const ::core::ffi::c_uint) {
    let sampler_name: *mut wined3d_string_buffer = string_buffer_get(core::ptr::addr_of_mut!((*priv_).string_buffers));
    let mut i: ::core::ffi::c_uint;
    let mut mapped_unit: ::core::ffi::c_uint;
    let mut name_loc: GLint;

    i = 0;
    while i < count {
        'body: {
            string_buffer_sprintf(sampler_name, b"%s_sampler%u\0".as_ptr() as *const ::core::ffi::c_char, prefix, i);
            name_loc = ((*gl_info).gl_ops.ext.p_glGetUniformLocation.unwrap_unchecked())(program_id, (*sampler_name).buffer);
            if name_loc == -1 {
                break 'body;
            }

            mapped_unit = if !tex_unit_map.is_null() {
                *tex_unit_map.add(base.wrapping_add(i) as usize)
            } else {
                base.wrapping_add(i)
            };
            if mapped_unit == (WINED3D_UNMAPPED_STAGE) as u32 || mapped_unit >= (*gl_info).limits.combined_samplers {
                ERR!("Trying to load sampler %s on unsupported unit %u.\n", (*sampler_name).buffer, mapped_unit);
            } else {
                TRACE!("Loading sampler %s on unit %u.\n", (*sampler_name).buffer, mapped_unit);
                ((*gl_info).gl_ops.ext.p_glUniform1i.unwrap_unchecked())(name_loc, mapped_unit as GLint);
            }
        }
        i = i.wrapping_add(1);
    }
    checkGLcall!(gl_info, "Load sampler bindings");
    string_buffer_release(core::ptr::addr_of_mut!((*priv_).string_buffers), sampler_name);
}

unsafe extern "C" fn shader_glsl_map_tex_unit(
    context: *const wined3d_context,
    shader_version: *const wined3d_shader_version,
    sampler_idx: ::core::ffi::c_uint,
) -> ::core::ffi::c_uint {
    let context_gl: *const wined3d_context_gl = wined3d_context_gl_const(context);
    let mut tex_unit_map: *const ::core::ffi::c_uint = ::core::ptr::null::<::core::ffi::c_uint>();
    let mut base: ::core::ffi::c_uint = 0;
    let mut count: ::core::ffi::c_uint = 0;
    tex_unit_map = wined3d_context_gl_get_tex_unit_mapping(
        context_gl,
        shader_version,
        core::ptr::addr_of_mut!(base),
        core::ptr::addr_of_mut!(count),
    );
    if sampler_idx >= count {
        return (WINED3D_UNMAPPED_STAGE) as u32;
    }
    if tex_unit_map.is_null() {
        return base.wrapping_add(sampler_idx);
    }
    return *tex_unit_map.offset(base.wrapping_add(sampler_idx) as isize);
}

unsafe extern "C" fn shader_glsl_append_sampler_binding_qualifier(
    buffer: *mut wined3d_string_buffer,
    context: *const wined3d_context,
    shader_version: *const wined3d_shader_version,
    sampler_idx: core::ffi::c_uint,
) {
    let mapped_unit: core::ffi::c_uint = shader_glsl_map_tex_unit(context, shader_version, sampler_idx);
    if mapped_unit != (WINED3D_UNMAPPED_STAGE) as u32 {
        shader_addline(
            buffer,
            b"layout(binding = %u)\n\0".as_ptr() as *const core::ffi::c_char,
            mapped_unit,
        );
    } else {
        ERR!("Unmapped sampler %u.\n", sampler_idx);
    }
}

unsafe extern "C" fn shader_glsl_load_samplers(
    context: *const wined3d_context,
    priv_: *mut shader_glsl_priv,
    program_id: GLuint,
    reg_maps: *const wined3d_shader_reg_maps,
) {
    let context_gl: *const wined3d_context_gl = wined3d_context_gl_const(context);
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut shader_version: *const wined3d_shader_version = core::ptr::null();
    let mut tex_unit_map: *const u32 = core::ptr::null();
    let mut base: u32 = 0;
    let mut count: u32 = 0;
    let mut prefix: *const i8 = core::ptr::null();

    if shader_glsl_use_layout_binding_qualifier(gl_info) != 0 {
        return;
    }

    shader_version = if !reg_maps.is_null() {
        core::ptr::addr_of!((*reg_maps).shader_version)
    } else {
        core::ptr::null()
    };
    prefix = shader_glsl_get_prefix(
        (if !shader_version.is_null() {
            (*shader_version).type_ as u32
        } else {
            WINED3D_SHADER_TYPE_PIXEL as u32
        }) as wined3d_shader_type,
    );
    tex_unit_map = wined3d_context_gl_get_tex_unit_mapping(context_gl, shader_version, core::ptr::addr_of_mut!(base), core::ptr::addr_of_mut!(count));
    shader_glsl_load_samplers_range(gl_info, priv_, program_id, prefix, base, count, tex_unit_map);
}

unsafe extern "C" fn shader_glsl_load_icb(
    gl_info: *const wined3d_gl_info,
    priv_: *mut shader_glsl_priv,
    program_id: GLuint,
    reg_maps: *const wined3d_shader_reg_maps,
) {
    let icb: *const wined3d_shader_immediate_constant_buffer = (*reg_maps).icb;

    if !icb.is_null() {
        let icb_name: *mut wined3d_string_buffer =
            string_buffer_get(core::ptr::addr_of_mut!((*priv_).string_buffers));
        let prefix: *const core::ffi::c_char =
            shader_glsl_get_prefix((*reg_maps).shader_version.type_);
        let icb_location: GLint;

        string_buffer_sprintf(
            icb_name,
            b"%s_icb\0".as_ptr() as *const core::ffi::c_char,
            prefix,
        );
        icb_location = ((*gl_info).gl_ops.ext.p_glGetUniformLocation.unwrap_unchecked())(program_id, (*icb_name).buffer);
        ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
            icb_location,
            (*icb).vec4_count as GLsizei,
            core::ptr::addr_of!((*icb).data) as *const GLfloat,
        );
        checkGLcall!(gl_info, b"Load immediate constant buffer\0".as_ptr() as *const core::ffi::c_char);

        string_buffer_release(core::ptr::addr_of_mut!((*priv_).string_buffers), icb_name);
    }
}

unsafe extern "C" fn shader_glsl_load_images(gl_info: *const wined3d_gl_info, priv_: *mut shader_glsl_priv, program_id: GLuint, reg_maps: *const wined3d_shader_reg_maps) {
    let prefix: *const i8 = shader_glsl_get_prefix((*reg_maps).shader_version.type_);
    let mut name: *mut wined3d_string_buffer = core::ptr::null_mut();
    let mut location: GLint = 0;
    let mut i: u32 = 0;

    if shader_glsl_use_layout_binding_qualifier(gl_info) != 0 {
        return;
    }

    name = string_buffer_get(core::ptr::addr_of_mut!((*priv_).string_buffers));
    i = 0;
    while i < MAX_UNORDERED_ACCESS_VIEWS {
        if !((*reg_maps).uav_resource_info[i as usize].type_ as u64 == 0) {
            string_buffer_sprintf(
                name,
                b"%s_image%u\0".as_ptr() as *const i8,
                prefix,
                i,
            );
            location = ((*gl_info).gl_ops.ext.p_glGetUniformLocation.unwrap_unchecked())(program_id, (*name).buffer);
            if !(location == -1) {
                ((*gl_info).gl_ops.ext.p_glUniform1i.unwrap_unchecked())(location, i as GLint);
            }
        }
        i = i.wrapping_add(1);
    }
    checkGLcall!(gl_info, b"Load image bindings\0".as_ptr() as *const i8);
    string_buffer_release(core::ptr::addr_of_mut!((*priv_).string_buffers), name);
}

unsafe extern "C" fn shader_glsl_load_program_resources(
    context_gl: *const wined3d_context_gl,
    priv_: *mut shader_glsl_priv,
    program_id: GLuint,
    shader: *const wined3d_shader,
) {
    let reg_maps: *const wined3d_shader_reg_maps = core::ptr::addr_of!((*shader).reg_maps);

    shader_glsl_init_uniform_block_bindings((*context_gl).gl_info, priv_, program_id, reg_maps);
    shader_glsl_load_icb((*context_gl).gl_info, priv_, program_id, reg_maps);
    /* Texture unit mapping is set up to be the same each time the shader
     * program is used so we can hardcode the sampler uniform values. */
    shader_glsl_load_samplers(core::ptr::addr_of!((*context_gl).c), priv_, program_id, reg_maps);
}

unsafe extern "C" fn append_transform_feedback_varying(varyings: *mut *const i8, varying_count: *mut u32, strings: *mut *mut i8, strings_length: *mut u32, buffer: *mut wined3d_string_buffer) {
    if !varyings.is_null() && !(*strings).is_null() {
        let mut ptr: *mut i8 = *strings;

        *varyings.add(*varying_count as usize) = ptr;

        memcpy(ptr as *mut core::ffi::c_void, (*buffer).buffer as *const core::ffi::c_void, ((*buffer).content_size + 1) as usize);
        ptr = ptr.add(((*buffer).content_size + 1) as usize);

        *strings = ptr;
    }

    *strings_length += (*buffer).content_size + 1;
    *varying_count += 1;
}

unsafe extern "C" fn append_transform_feedback_skip_components(
    varyings: *mut *const core::ffi::c_char,
    varying_count: *mut core::ffi::c_uint,
    strings: *mut *mut core::ffi::c_char,
    strings_length: *mut core::ffi::c_uint,
    buffer: *mut wined3d_string_buffer,
    component_count: core::ffi::c_uint,
) {
    let mut j: core::ffi::c_uint;
    j = 0 as core::ffi::c_uint;
    while j < component_count / 4 as core::ffi::c_uint {
        string_buffer_sprintf(
            buffer,
            b"gl_SkipComponents4\0".as_ptr() as *const core::ffi::c_char,
        );
        append_transform_feedback_varying(varyings, varying_count, strings, strings_length, buffer);
        j = j.wrapping_add(1);
    }
    if component_count % 4 as core::ffi::c_uint != 0 {
        string_buffer_sprintf(
            buffer,
            b"gl_SkipComponents%u\0".as_ptr() as *const core::ffi::c_char,
            component_count % 4 as core::ffi::c_uint,
        );
        append_transform_feedback_varying(varyings, varying_count, strings, strings_length, buffer);
    }
}

unsafe extern "C" fn shader_glsl_generate_transform_feedback_varyings(
    mut buffer: *mut wined3d_string_buffer,
    mut varyings: *mut *const ::core::ffi::c_char,
    mut varying_count: *mut ::core::ffi::c_uint,
    mut strings: *mut ::core::ffi::c_char,
    mut strings_length: *mut ::core::ffi::c_uint,
    mut buffer_mode: GLenum,
    mut shader: *mut wined3d_shader,
) -> BOOL {
    let mut so_desc: *const wined3d_stream_output_desc = (*shader).u.gs.so_desc;
    let mut buffer_idx: ::core::ffi::c_uint = 0;
    let mut count: ::core::ffi::c_uint = 0;
    let mut length: ::core::ffi::c_uint = 0;
    let mut highest_output_slot: ::core::ffi::c_uint = 0;
    let mut stride: ::core::ffi::c_uint = 0;
    let mut i: ::core::ffi::c_uint = 0;
    let mut register_idx: ::core::ffi::c_uint = 0;
    let mut component_idx: ::core::ffi::c_uint = 0;
    let mut have_varyings_to_record: BOOL = (FALSE as i32);
    length = 0;
    count = length;
    highest_output_slot = 0;
    buffer_idx = 0;
    while buffer_idx < WINED3D_MAX_STREAM_OUTPUT_BUFFERS {
        stride = 0;
        let mut current_block_24: u64;
        i = 0;
        while i < (*so_desc).element_count {
            let mut e: *const wined3d_stream_output_element =
                (*so_desc).elements.offset(i as isize) as *const wined3d_stream_output_element;
            highest_output_slot = max!(highest_output_slot, (*e).output_slot as ::core::ffi::c_uint);
            if !((*e).output_slot as ::core::ffi::c_uint != buffer_idx) {
                if (*e).stream_idx != 0 {
                    WINE_FIXME!("Unhandled stream %u.\n", (*e).stream_idx);
                } else {
                    stride = stride.wrapping_add((*e).component_count as ::core::ffi::c_uint);
                    if (*e).semantic_name.is_null() {
                        append_transform_feedback_skip_components(
                            varyings,
                            &raw mut count,
                            &raw mut strings,
                            &raw mut length,
                            buffer,
                            (*e).component_count as ::core::ffi::c_uint,
                        );
                    } else if !(shader_get_stream_output_register_info(
                        shader,
                        e,
                        &raw mut register_idx,
                        &raw mut component_idx,
                    ) == 0)
                    {
                        if component_idx != 0
                            || (*e).component_count as ::core::ffi::c_int
                                != 4
                        {
                            if (*so_desc).rasterizer_stream_idx != WINED3D_NO_RASTERIZER_STREAM {
                                WINE_FIXME!("Unsupported component range %u-%u.\n", component_idx, (*e).component_count as ::core::ffi::c_int);
                                append_transform_feedback_skip_components(
                                    varyings,
                                    &raw mut count,
                                    &raw mut strings,
                                    &raw mut length,
                                    buffer,
                                    (*e).component_count as ::core::ffi::c_uint,
                                );
                                current_block_24 = 6873731126896040597;
                            } else {
                                string_buffer_sprintf(
                                    buffer,
                                    b"shader_in_out.reg%u_%u_%u\0" as *const u8
                                        as *const ::core::ffi::c_char,
                                    register_idx,
                                    component_idx,
                                    component_idx
                                        .wrapping_add((*e).component_count as ::core::ffi::c_uint)
                                        .wrapping_sub(1 as ::core::ffi::c_uint),
                                );
                                append_transform_feedback_varying(
                                    varyings,
                                    &raw mut count,
                                    &raw mut strings,
                                    &raw mut length,
                                    buffer,
                                );
                                current_block_24 = 11636175345244025579;
                            }
                        } else {
                            string_buffer_sprintf(
                                buffer,
                                b"shader_in_out.reg%u\0" as *const u8 as *const ::core::ffi::c_char,
                                register_idx,
                            );
                            append_transform_feedback_varying(
                                varyings,
                                &raw mut count,
                                &raw mut strings,
                                &raw mut length,
                                buffer,
                            );
                            current_block_24 = 11636175345244025579;
                        }
                        match current_block_24 {
                            6873731126896040597 => {}
                            _ => {
                                have_varyings_to_record = TRUE as BOOL;
                            }
                        }
                    }
                }
            }
            i = i.wrapping_add(1);
        }
        if buffer_idx < (*so_desc).buffer_stride_count
            && stride
                < (*so_desc).buffer_strides[buffer_idx as usize]
                    .wrapping_div(4 as ::core::ffi::c_uint)
        {
            let mut component_count: ::core::ffi::c_uint = (*so_desc).buffer_strides
                [buffer_idx as usize]
                .wrapping_div(4 as ::core::ffi::c_uint)
                .wrapping_sub(stride);
            append_transform_feedback_skip_components(
                varyings,
                &raw mut count,
                &raw mut strings,
                &raw mut length,
                buffer,
                component_count,
            );
        }
        if highest_output_slot <= buffer_idx {
            break;
        }
        if buffer_mode == GL_INTERLEAVED_ATTRIBS as GLenum {
            string_buffer_sprintf(
                buffer,
                b"gl_NextBuffer\0" as *const u8 as *const ::core::ffi::c_char,
            );
            append_transform_feedback_varying(
                varyings,
                &raw mut count,
                &raw mut strings,
                &raw mut length,
                buffer,
            );
        }
        buffer_idx = buffer_idx.wrapping_add(1);
    }
    if !varying_count.is_null() {
        *varying_count = count;
    }
    if !strings_length.is_null() {
        *strings_length = length;
    }
    return have_varyings_to_record;
}

unsafe extern "C" fn shader_glsl_init_transform_feedback(
    context_gl: *const wined3d_context_gl,
    priv_: *mut shader_glsl_priv,
    program_id: GLuint,
    shader: *mut wined3d_shader,
) {
    let so_desc: *const wined3d_stream_output_desc = (*shader).u.gs.so_desc;
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut buffer: *mut wined3d_string_buffer = core::ptr::null_mut();
    let mut i: u32 = 0;
    let mut count: u32 = 0;
    let mut length: u32 = 0;
    let mut varyings: *mut *const i8 = core::ptr::null_mut();
    let mut strings: *mut i8 = core::ptr::null_mut();
    let mut mode: GLenum = 0;

    if so_desc.is_null() {
        return;
    }

    if (*gl_info).supported[ARB_TRANSFORM_FEEDBACK3 as usize] != 0 {
        mode = GL_INTERLEAVED_ATTRIBS as GLenum;
    } else {
        let mut element_count: [u32; (WINED3D_MAX_STREAM_OUTPUT_BUFFERS as _)] = [0; (WINED3D_MAX_STREAM_OUTPUT_BUFFERS as _)];

        i = 0 as u32;
        while i < (*so_desc).element_count {
            if (*(*so_desc).elements.offset(i as isize)).semantic_name.is_null() {
                FIXME!("ARB_transform_feedback3 is needed for stream output gaps.\n");
                return;
            }
            element_count[(*(*so_desc).elements.offset(i as isize)).output_slot as usize] =
                element_count[(*(*so_desc).elements.offset(i as isize)).output_slot as usize]
                    .wrapping_add(1);
            i = i.wrapping_add(1);
        }

        if element_count[0 as usize] == (*so_desc).element_count {
            mode = GL_INTERLEAVED_ATTRIBS as GLenum;
        } else {
            mode = GL_SEPARATE_ATTRIBS as GLenum;
            i = 0 as u32;
            while (i as usize) < ARRAY_SIZE!(element_count) as usize {
                if element_count[i as usize] != 1 {
                    break;
                }
                i = i.wrapping_add(1);
            }
            while (i as usize) < ARRAY_SIZE!(element_count) as usize {
                if element_count[i as usize] != 0 {
                    FIXME!("Only single element per buffer is allowed in separate mode.\n");
                    return;
                }
                i = i.wrapping_add(1);
            }
        }
    }

    buffer = string_buffer_get(core::ptr::addr_of_mut!((*priv_).string_buffers));

    if shader_glsl_generate_transform_feedback_varyings(
        buffer,
        core::ptr::null_mut(),
        core::ptr::addr_of_mut!(count),
        core::ptr::null_mut(),
        core::ptr::addr_of_mut!(length),
        mode,
        shader,
    ) == 0
    {
        FIXME!("No varyings to record, disabling transform feedback.\n");
        (*shader).u.gs.so_desc = core::ptr::null::<wined3d_stream_output_desc>();
        string_buffer_release(core::ptr::addr_of_mut!((*priv_).string_buffers), buffer);
        return;
    }

    varyings = calloc(
        (count as usize) as _,
        (core::mem::size_of::<*const i8>() as usize) as _,
    ) as *mut *const i8;
    if varyings.is_null() {
        ERR!("Out of memory.\n");
        string_buffer_release(core::ptr::addr_of_mut!((*priv_).string_buffers), buffer);
        return;
    }
    strings = calloc(
        (length as usize) as _,
        (core::mem::size_of::<i8>() as usize) as _,
    ) as *mut i8;
    if strings.is_null() {
        ERR!("Out of memory.\n");
        free(varyings as *mut core::ffi::c_void);
        string_buffer_release(core::ptr::addr_of_mut!((*priv_).string_buffers), buffer);
        return;
    }

    shader_glsl_generate_transform_feedback_varyings(
        buffer,
        varyings,
        core::ptr::null_mut(),
        strings,
        core::ptr::null_mut(),
        mode,
        shader,
    );
    ((*gl_info).gl_ops.ext.p_glTransformFeedbackVaryings.unwrap_unchecked())(
        program_id,
        count as GLsizei,
        varyings as *const *const GLchar,
        mode,
    );
    checkGLcall!(gl_info, b"glTransformFeedbackVaryings\0".as_ptr() as *const i8);

    free(varyings as *mut core::ffi::c_void);
    free(strings as *mut core::ffi::c_void);
    string_buffer_release(core::ptr::addr_of_mut!((*priv_).string_buffers), buffer);
}

unsafe extern "C" fn walk_constant_heap(
    gl_info: *const wined3d_gl_info,
    constants: *const wined3d_vec4,
    constant_locations: *const GLint,
    heap: *const constant_heap,
    stack: *mut ::core::ffi::c_uchar,
    version: DWORD,
) {
    let mut start: ::core::ffi::c_uint = !0;
    let mut end: ::core::ffi::c_uint = 0;
    let mut stack_idx: ::core::ffi::c_int = 0;
    let mut heap_idx: ::core::ffi::c_uint = 1;
    let mut idx: ::core::ffi::c_uint = 0;

    if (*(*heap).entries.offset(heap_idx as isize)).version <= version {
        return;
    }

    idx = (*(*heap).entries.offset(heap_idx as isize)).idx;
    if *constant_locations.offset(idx as isize) != -1 {
        start = idx;
        end = idx;
    }
    *stack.offset(stack_idx as isize) = HEAP_NODE_TRAVERSE_LEFT as ::core::ffi::c_uchar;

    while stack_idx >= 0 {
        /* Note that we fall through to the next case statement. */
        let sw: ::core::ffi::c_int = *stack.offset(stack_idx as isize) as ::core::ffi::c_int;
        'sw: {
            if sw == HEAP_NODE_TRAVERSE_LEFT {
                let left_idx: ::core::ffi::c_uint = heap_idx << 1;
                if left_idx < (*heap).size
                    && (*(*heap).entries.offset(left_idx as isize)).version > version
                {
                    heap_idx = left_idx;
                    idx = (*(*heap).entries.offset(heap_idx as isize)).idx;
                    if *constant_locations.offset(idx as isize) != -1 {
                        if start > idx {
                            start = idx;
                        }
                        if end < idx {
                            end = idx;
                        }
                    }

                    let fresh_a = stack_idx;
                    stack_idx += 1;
                    *stack.offset(fresh_a as isize) = HEAP_NODE_TRAVERSE_RIGHT as ::core::ffi::c_uchar;
                    *stack.offset(stack_idx as isize) = HEAP_NODE_TRAVERSE_LEFT as ::core::ffi::c_uchar;
                    break 'sw;
                }
            }

            if sw == HEAP_NODE_TRAVERSE_LEFT || sw == HEAP_NODE_TRAVERSE_RIGHT {
                let right_idx: ::core::ffi::c_uint =
                    (heap_idx << 1).wrapping_add(1 as ::core::ffi::c_uint);
                if right_idx < (*heap).size
                    && (*(*heap).entries.offset(right_idx as isize)).version > version
                {
                    heap_idx = right_idx;
                    idx = (*(*heap).entries.offset(heap_idx as isize)).idx;
                    if *constant_locations.offset(idx as isize) != -1 {
                        if start > idx {
                            start = idx;
                        }
                        if end < idx {
                            end = idx;
                        }
                    }

                    let fresh_b = stack_idx;
                    stack_idx += 1;
                    *stack.offset(fresh_b as isize) = HEAP_NODE_POP as ::core::ffi::c_uchar;
                    *stack.offset(stack_idx as isize) = HEAP_NODE_TRAVERSE_LEFT as ::core::ffi::c_uchar;
                    break 'sw;
                }
            }

            if sw == HEAP_NODE_TRAVERSE_LEFT
                || sw == HEAP_NODE_TRAVERSE_RIGHT
                || sw == HEAP_NODE_POP
            {
                heap_idx >>= 1;
                stack_idx -= 1;
            }
        }
    }

    if start <= end {
        ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
            *constant_locations.offset(start as isize),
            end.wrapping_sub(start).wrapping_add(1 as ::core::ffi::c_uint) as GLsizei,
            core::ptr::addr_of!((*constants.offset(start as isize)).x),
        );
    }
    checkGLcall!(gl_info, b"walk_constant_heap()\0".as_ptr() as *const ::core::ffi::c_char);
}

unsafe extern "C" fn apply_clamped_constant(
    gl_info: *const wined3d_gl_info,
    location: GLint,
    data: *const wined3d_vec4,
) {
    let mut clamped_constant: [GLfloat; 4] = [0.0; 4];

    if location == -1 {
        return;
    }

    clamped_constant[0 as usize] = if (*data).x < -1.0f32 {
        -1.0f32
    } else if (*data).x > 1.0f32 {
        1.0f32
    } else {
        (*data).x
    } as GLfloat;
    clamped_constant[1 as usize] = if (*data).y < -1.0f32 {
        -1.0f32
    } else if (*data).y > 1.0f32 {
        1.0f32
    } else {
        (*data).y
    } as GLfloat;
    clamped_constant[2 as usize] = if (*data).z < -1.0f32 {
        -1.0f32
    } else if (*data).z > 1.0f32 {
        1.0f32
    } else {
        (*data).z
    } as GLfloat;
    clamped_constant[3 as usize] = if (*data).w < -1.0f32 {
        -1.0f32
    } else if (*data).w > 1.0f32 {
        1.0f32
    } else {
        (*data).w
    } as GLfloat;

    ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
        location,
        1,
        clamped_constant.as_mut_ptr(),
    );
}

unsafe extern "C" fn walk_constant_heap_clamped(gl_info: *const wined3d_gl_info, constants: *const wined3d_vec4, constant_locations: *const GLint, heap: *const constant_heap, stack: *mut u8, version: DWORD) {
    let mut stack_idx: i32 = 0;
    let mut heap_idx: u32 = 1;
    let mut idx: u32 = 0;

    if (*(*heap).entries.add(heap_idx as usize)).version <= version {
        return;
    }

    idx = (*(*heap).entries.add(heap_idx as usize)).idx;
    apply_clamped_constant(gl_info, *constant_locations.add(idx as usize), constants.add(idx as usize));
    *stack.offset(stack_idx as isize) = HEAP_NODE_TRAVERSE_LEFT as u8;

    while stack_idx >= 0 {
        /* Note that we fall through to the next case statement. */
        let sw: i32 = *stack.offset(stack_idx as isize) as i32;
        let mut at: u8 = if sw == HEAP_NODE_TRAVERSE_LEFT {
            0
        } else if sw == HEAP_NODE_TRAVERSE_RIGHT {
            1
        } else if sw == HEAP_NODE_POP {
            2
        } else {
            3
        };
        loop {
            match at {
                0 => {
                    let left_idx: u32 = heap_idx << 1;
                    if left_idx < (*heap).size && (*(*heap).entries.add(left_idx as usize)).version > version {
                        heap_idx = left_idx;
                        idx = (*(*heap).entries.add(heap_idx as usize)).idx;
                        apply_clamped_constant(gl_info, *constant_locations.add(idx as usize), constants.add(idx as usize));

                        let fresh0: i32 = stack_idx;
                        stack_idx += 1;
                        *stack.offset(fresh0 as isize) = HEAP_NODE_TRAVERSE_RIGHT as u8;
                        *stack.offset(stack_idx as isize) = HEAP_NODE_TRAVERSE_LEFT as u8;
                        break;
                    }
                    at = 1;
                    continue;
                }
                1 => {
                    let right_idx: u32 = (heap_idx << 1).wrapping_add(1);
                    if right_idx < (*heap).size && (*(*heap).entries.add(right_idx as usize)).version > version {
                        heap_idx = right_idx;
                        idx = (*(*heap).entries.add(heap_idx as usize)).idx;
                        apply_clamped_constant(gl_info, *constant_locations.add(idx as usize), constants.add(idx as usize));

                        let fresh1: i32 = stack_idx;
                        stack_idx += 1;
                        *stack.offset(fresh1 as isize) = HEAP_NODE_POP as u8;
                        *stack.offset(stack_idx as isize) = HEAP_NODE_TRAVERSE_LEFT as u8;
                        break;
                    }
                    at = 2;
                    continue;
                }
                2 => {
                    heap_idx >>= 1;
                    stack_idx -= 1;
                    break;
                }
                _ => break,
            }
        }
    }
    checkGLcall!(gl_info, b"walk_constant_heap_clamped()\0".as_ptr() as *const i8);
}

unsafe extern "C" fn shader_glsl_load_constants_f(
    shader: *const wined3d_shader,
    context_gl: *mut wined3d_context_gl,
    constant_buffer: *mut wined3d_buffer,
    constant_locations: *const GLint,
    heap: *const constant_heap,
    stack: *mut ::core::ffi::c_uchar,
    version: ::core::ffi::c_uint,
) {
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut lconst: *const wined3d_shader_lconst = core::ptr::null();

    if !constant_buffer.is_null() {
        let constants: *const wined3d_vec4 = wined3d_buffer_load_sysmem(
            constant_buffer,
            core::ptr::addr_of_mut!((*context_gl).c),
        ) as *const wined3d_vec4;

        /* 1.X pshaders have the constants clamped to [-1;1] implicitly. */
        if (*shader).reg_maps.shader_version.major as ::core::ffi::c_int == 1
            && (*shader).reg_maps.shader_version.type_ as ::core::ffi::c_uint
                == WINED3D_SHADER_TYPE_PIXEL as ::core::ffi::c_uint
        {
            walk_constant_heap_clamped(
                gl_info,
                constants,
                constant_locations,
                heap,
                stack,
                version as DWORD,
            );
        } else {
            walk_constant_heap(
                gl_info,
                constants,
                constant_locations,
                heap,
                stack,
                version as DWORD,
            );
        }
    }

    if !(*shader).load_local_constsF {
        TRACE!("No need to load local float constants for this shader.\n");
        return;
    }

    /* Immediate constants are clamped to [-1;1] at shader creation time if needed */
    lconst = ((*shader).constantsF.next as *mut ::core::ffi::c_char).offset(
        -(core::mem::offset_of!(wined3d_shader_lconst, entry) as isize),
    ) as *mut wined3d_shader_lconst;
    while core::ptr::addr_of!((*lconst).entry) != core::ptr::addr_of!((*shader).constantsF) {
        ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
            *constant_locations.offset((*lconst).idx as isize),
            1,
            core::ptr::addr_of!((*lconst).value) as *const GLfloat,
        );
        lconst = ((*lconst).entry.next as *mut ::core::ffi::c_char).offset(
            -(core::mem::offset_of!(wined3d_shader_lconst, entry) as isize),
        ) as *mut wined3d_shader_lconst;
    }
    checkGLcall!(gl_info, b"glUniform4fv()\0" as *const u8 as *const ::core::ffi::c_char);
}

unsafe extern "C" fn shader_glsl_load_constants_i(shader: *const wined3d_shader, context_gl: *mut wined3d_context_gl, constant_buffer: *mut wined3d_buffer, locations: *const GLint, mut constants_set: uint32_t) {
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut i: ::core::ffi::c_uint = 0;
    let mut ptr: *mut list;

    if !constant_buffer.is_null() {
        let constants: *const wined3d_ivec4 = wined3d_buffer_load_sysmem(constant_buffer, &raw mut (*context_gl).c) as *const wined3d_ivec4;

        while constants_set != 0 {
            /* We found this uniform name in the program - go ahead and send the data */
            i = wined3d_bit_scan(&raw mut constants_set) as ::core::ffi::c_uint;
            ((*gl_info).gl_ops.ext.p_glUniform4iv.unwrap_unchecked())(*locations.add(i as usize), 1, &raw const (*constants.add(i as usize)).x);
        }
    }

    /* Load immediate constants */
    ptr = list_head(&raw const (*shader).constantsI);
    while !ptr.is_null() {
        let lconst: *const wined3d_shader_lconst = LIST_ENTRY!(ptr, wined3d_shader_lconst, entry);
        let idx: ::core::ffi::c_uint = (*lconst).idx;
        let values: *const GLint = &raw const (*lconst).value as *const GLint;

        /* We found this uniform name in the program - go ahead and send the data */
        ((*gl_info).gl_ops.ext.p_glUniform4iv.unwrap_unchecked())(*locations.add(idx as usize), 1, values);
        ptr = list_next(&raw const (*shader).constantsI, ptr);
    }
    checkGLcall!(gl_info, "glUniform4iv()");
}

unsafe extern "C" fn shader_glsl_load_constants_b(
    shader: *const wined3d_shader,
    context_gl: *mut wined3d_context_gl,
    constant_buffer: *mut wined3d_buffer,
    locations: *const GLint,
    mut constants_set: uint32_t,
) {
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut i: ::core::ffi::c_uint = 0;
    let mut ptr: *mut list = ::core::ptr::null_mut::<list>();

    if !constant_buffer.is_null() {
        let constants: *const BOOL = wined3d_buffer_load_sysmem(
            constant_buffer,
            core::ptr::addr_of_mut!((*context_gl).c),
        ) as *const BOOL;

        while constants_set != 0 {
            i = wined3d_bit_scan(core::ptr::addr_of_mut!(constants_set)) as ::core::ffi::c_uint;
            ((*gl_info).gl_ops.ext.p_glUniform1iv.unwrap_unchecked())(
                *locations.offset(i as isize),
                1,
                constants.offset(i as isize) as *const GLint,
            );
        }
    }

    /* Load immediate constants */
    ptr = list_head(core::ptr::addr_of!((*shader).constantsB));
    while !ptr.is_null() {
        let lconst: *const wined3d_shader_lconst = (ptr as *mut ::core::ffi::c_char)
            .sub(core::mem::offset_of!(wined3d_shader_lconst, entry))
            as *const wined3d_shader_lconst;
        let idx: ::core::ffi::c_uint = (*lconst).idx;
        let values: *const GLint = core::ptr::addr_of!((*lconst).value) as *const GLint;

        ((*gl_info).gl_ops.ext.p_glUniform1iv.unwrap_unchecked())(
            *locations.offset(idx as isize),
            1,
            values,
        );
        ptr = list_next(core::ptr::addr_of!((*shader).constantsB), ptr);
    }
    checkGLcall!(gl_info, b"glUniform1iv()\0".as_ptr() as *const ::core::ffi::c_char);
}

unsafe extern "C" fn reset_program_constant_version(
    entry: *mut list,
    context: *mut core::ffi::c_void,
) {
    let _ = context;
    (*((entry as *mut u8).sub(core::mem::offset_of!(glsl_shader_prog_link, program_lookup_entry))
        as *mut glsl_shader_prog_link))
        .constant_version = 0;
}

unsafe extern "C" fn get_projection_matrix(
    context: *const wined3d_context,
    constants: *const wined3d_ffp_vs_constants,
    state: *const wined3d_state,
    mat: *mut wined3d_matrix,
) {
    let d3d_info: *const wined3d_d3d_info = (*context).d3d_info;
    let clip_control: bool;
    let flip: bool;
    let center_offset: f32;

    /* Projection matrices are <= d3d9, which all have integer pixel centers. */
    if ((*d3d_info).wined3d_creation_flags & WINED3D_PIXEL_CENTER_INTEGER) == 0 {
        ERR!("Did not expect to enter this codepath without WINED3D_PIXEL_CENTER_INTEGER.\n");
    }

    clip_control = (*d3d_info).clip_control() != 0;
    flip = !clip_control;
    if !clip_control {
        center_offset = 1.0f32 + (*d3d_info).filling_convention_offset;
    } else {
        center_offset = 0.0f32;
    }

    if (*context).stream_info.position_transformed() != 0 {
        /* Transform D3D RHW coordinates to OpenGL clip coordinates. */
        let x: f32 = (*state).viewports[0 as usize].x;
        let y: f32 = (*state).viewports[0 as usize].y;
        let w: f32 = (*state).viewports[0 as usize].width;
        let h: f32 = (*state).viewports[0 as usize].height;
        let x_scale: f32 = 2.0f32 / w;
        let x_offset: f32 = (center_offset - 2.0f32 * x - w) / w;
        let y_scale: f32 = if flip { 2.0f32 / h } else { 2.0f32 / -h };
        let y_offset: f32 = if flip {
            (center_offset - 2.0f32 * y - h) / h
        } else {
            (center_offset - 2.0f32 * y - h) / -h
        };
        let zenable: bool = if !(*state).fb.depth_stencil.is_null() {
            if !(*state).depth_stencil_state.is_null() {
                (*(*state).depth_stencil_state).desc.depth as i32 != 0
            } else {
                true
            }
        } else {
            false
        };
        let z_scale: f32 = if zenable {
            if clip_control { 1.0f32 } else { 2.0f32 }
        } else {
            0.0f32
        };
        let z_offset: f32 = if zenable {
            if clip_control { 0.0f32 } else { -1.0f32 }
        } else {
            0.0f32
        };
        let projection: wined3d_matrix = wined3d_matrix {
            _11: x_scale,
            _12: 0.0f32,
            _13: 0.0f32,
            _14: 0.0f32,
            _21: 0.0f32,
            _22: y_scale,
            _23: 0.0f32,
            _24: 0.0f32,
            _31: 0.0f32,
            _32: 0.0f32,
            _33: z_scale,
            _34: 0.0f32,
            _41: x_offset,
            _42: y_offset,
            _43: z_offset,
            _44: 1.0f32,
        };

        *mat = projection;
    } else {
        let y_scale: f32 = if flip { -1.0f32 } else { 1.0f32 };
        let x_offset: f32 =
            center_offset / (*state).viewports[0 as usize].width;
        let y_offset: f32 = if flip {
            center_offset / (*state).viewports[0 as usize].height
        } else {
            -center_offset / (*state).viewports[0 as usize].height
        };
        let z_scale: f32 = if clip_control { 1.0f32 } else { 2.0f32 };
        let z_offset: f32 = if clip_control { 0.0f32 } else { -1.0f32 };
        let projection: wined3d_matrix = wined3d_matrix {
            _11: 1.0f32,
            _12: 0.0f32,
            _13: 0.0f32,
            _14: 0.0f32,
            _21: 0.0f32,
            _22: y_scale,
            _23: 0.0f32,
            _24: 0.0f32,
            _31: 0.0f32,
            _32: 0.0f32,
            _33: z_scale,
            _34: 0.0f32,
            _41: x_offset,
            _42: y_offset,
            _43: z_offset,
            _44: 1.0f32,
        };

        multiply_matrix(
            mat,
            core::ptr::addr_of!(projection),
            core::ptr::addr_of!((*constants).projection_matrix),
        );
    }
}

unsafe extern "C" fn shader_glsl_ffp_vertex_normalmatrix_uniform(
    context_gl: *const wined3d_context_gl,
    constants: *const wined3d_ffp_vs_constants,
    prog: *mut glsl_shader_prog_link,
) {
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;

    if (*prog).vs.normal_matrix_location == -1 {
        return;
    }

    ((*gl_info).gl_ops.ext.p_glUniformMatrix4fv.unwrap_unchecked())(
        (*prog).vs.normal_matrix_location,
        1,
        (FALSE as u8),
        core::ptr::addr_of!((*constants).modelview.not_blended.normal_matrix._11),
    );
    checkGLcall!(gl_info, "glUniformMatrix4fv");
}

unsafe extern "C" fn shader_glsl_ffp_vertex_texmatrix_uniform(
    context_gl: *const wined3d_context_gl,
    constants: *const wined3d_ffp_vs_constants,
    tex: ::core::ffi::c_uint,
    prog: *mut glsl_shader_prog_link,
) {
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;

    if tex >= WINED3D_MAX_FFP_TEXTURES {
        return;
    }
    if (*prog).vs.texture_matrix_location[tex as usize] == -1 {
        return;
    }

    ((*gl_info).gl_ops.ext.p_glUniformMatrix4fv.unwrap_unchecked())(
        (*prog).vs.texture_matrix_location[tex as usize],
        1,
        (FALSE as u8),
        &raw const (*(&raw const (*constants).texture_matrices as *const wined3d_matrix)
            .offset(tex as isize))
        ._11,
    );
    checkGLcall!(gl_info, "glUniformMatrix4fv");
}

unsafe extern "C" fn shader_glsl_ffp_vertex_material_uniform(
    mut context_gl: *mut wined3d_context_gl,
    mut state: *const wined3d_state,
    mut prog: *mut glsl_shader_prog_link,
) {
    let mut gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut constants: *const wined3d_ffp_vs_constants = core::ptr::null::<wined3d_ffp_vs_constants>();

    constants = wined3d_buffer_load_sysmem(
        (*(*context_gl).c.device).push_constants[WINED3D_PUSH_CONSTANTS_VS_FFP as usize],
        core::ptr::addr_of_mut!((*context_gl).c),
    ) as *const wined3d_ffp_vs_constants;

    ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
        (*prog).vs.material_specular_location,
        1 as GLsizei,
        core::ptr::addr_of!((*constants).material.specular.r),
    );
    ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())(
        (*prog).vs.material_shininess_location,
        (*constants).material.power as GLfloat,
    );
    ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
        (*prog).vs.material_ambient_location,
        1 as GLsizei,
        core::ptr::addr_of!((*constants).material.ambient.r),
    );
    ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
        (*prog).vs.material_diffuse_location,
        1 as GLsizei,
        core::ptr::addr_of!((*constants).material.diffuse.r),
    );
    ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
        (*prog).vs.material_emissive_location,
        1 as GLsizei,
        core::ptr::addr_of!((*constants).material.emissive.r),
    );
    checkGLcall!(gl_info, b"setting FFP material uniforms\0" as *const u8 as *const ::core::ffi::c_char);
}

unsafe extern "C" fn shader_glsl_ffp_vertex_light_uniform(
    context_gl: *const wined3d_context_gl,
    state: *const wined3d_state,
    light: ::core::ffi::c_uint,
    type_: wined3d_light_type,
    constants: *const wined3d_light_constants,
    prog: *mut glsl_shader_prog_link,
) {
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;

    ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())((*prog).vs.light_location[light as usize].diffuse, 1, core::ptr::addr_of!((*constants).diffuse.r));
    ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())((*prog).vs.light_location[light as usize].specular, 1, core::ptr::addr_of!((*constants).specular.r));
    ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())((*prog).vs.light_location[light as usize].ambient, 1, core::ptr::addr_of!((*constants).ambient.r));

    match type_ as ::core::ffi::c_uint {
        WINED3D_LIGHT_POINT => {
            ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())((*prog).vs.light_location[light as usize].position, 1, core::ptr::addr_of!((*constants).position.x));
            ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.light_location[light as usize].range, (*constants).range);
            ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.light_location[light as usize].c_att, (*constants).const_att);
            ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.light_location[light as usize].l_att, (*constants).linear_att);
            ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.light_location[light as usize].q_att, (*constants).quad_att);
        }

        WINED3D_LIGHT_SPOT => {
            ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())((*prog).vs.light_location[light as usize].position, 1, core::ptr::addr_of!((*constants).position.x));

            ((*gl_info).gl_ops.ext.p_glUniform3fv.unwrap_unchecked())((*prog).vs.light_location[light as usize].direction, 1, core::ptr::addr_of!((*constants).direction.x));

            ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.light_location[light as usize].range, (*constants).range);
            ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.light_location[light as usize].falloff, (*constants).falloff);
            ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.light_location[light as usize].c_att, (*constants).const_att);
            ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.light_location[light as usize].l_att, (*constants).linear_att);
            ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.light_location[light as usize].q_att, (*constants).quad_att);
            ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.light_location[light as usize].cos_htheta, (*constants).cos_half_theta);
            ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.light_location[light as usize].cos_hphi, (*constants).cos_half_phi);
        }

        WINED3D_LIGHT_DIRECTIONAL => {
            ((*gl_info).gl_ops.ext.p_glUniform3fv.unwrap_unchecked())((*prog).vs.light_location[light as usize].direction, 1, core::ptr::addr_of!((*constants).direction.x));
        }

        WINED3D_LIGHT_PARALLELPOINT => {
            ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())((*prog).vs.light_location[light as usize].position, 1, core::ptr::addr_of!((*constants).position.x));
        }

        _ => {
            FIXME!("Unrecognized light type %#x.\n", type_);
        }
    }
    checkGLcall!(gl_info, b"setting FFP lights uniforms\0".as_ptr() as *const i8);
}

unsafe extern "C" fn shader_glsl_pointsize_uniform(
    context_gl: *mut wined3d_context_gl,
    state: *const wined3d_state,
    prog: *mut glsl_shader_prog_link,
) {
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let constants: *const wined3d_ffp_vs_constants;
    let mut min: f32 = 0.0;
    let mut max: f32 = 0.0;

    constants = wined3d_buffer_load_sysmem(
            (*(*context_gl).c.device).push_constants[WINED3D_PUSH_CONSTANTS_VS_FFP as usize],
            core::ptr::addr_of_mut!((*context_gl).c),
    ) as *const wined3d_ffp_vs_constants;

    get_pointsize_minmax(core::ptr::addr_of_mut!((*context_gl).c), state, core::ptr::addr_of_mut!(min), core::ptr::addr_of_mut!(max));

    ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.pointsize_min_location, min);
    checkGLcall!(gl_info, "glUniform1f");
    ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.pointsize_max_location, max);
    checkGLcall!(gl_info, "glUniform1f");

    ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())(
        (*prog).vs.pointsize_location,
        int_to_float((*state).render_states[WINED3D_RS_POINTSIZE as usize]),
    );
    checkGLcall!(gl_info, "glUniform1f");
    ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.pointsize_c_att_location, (*constants).point.scale_const);
    checkGLcall!(gl_info, "glUniform1f");
    ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.pointsize_l_att_location, (*constants).point.scale_linear);
    checkGLcall!(gl_info, "glUniform1f");
    ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())((*prog).vs.pointsize_q_att_location, (*constants).point.scale_quad);
    checkGLcall!(gl_info, "glUniform1f");
}

unsafe extern "C" fn shader_glsl_load_fog_uniform(
    context_gl: *const wined3d_context_gl,
    state: *const wined3d_state,
    prog: *mut glsl_shader_prog_link,
) {
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut color: wined3d_color = wined3d_color {
        r: 0.0,
        g: 0.0,
        b: 0.0,
        a: 0.0,
    };
    let mut start: f32 = 0.0;
    let mut end: f32 = 0.0;
    let mut scale: f32 = 0.0;
    let mut tmpvalue_d: DWORD = 0;
    let mut tmpvalue_f: f32 = 0.0;

    wined3d_color_from_d3dcolor(
        core::ptr::addr_of_mut!(color),
        (*state).render_states[WINED3D_RS_FOGCOLOR as usize],
    );
    (*gl_info)
        .gl_ops
        .ext
        .p_glUniform4fv
        .unwrap_unchecked()(
        (*prog).ps.fog_color_location,
        1 as GLsizei,
        core::ptr::addr_of_mut!(color.r),
    );
    tmpvalue_d = (*state).render_states[WINED3D_RS_FOGDENSITY as usize] as DWORD;
    tmpvalue_f = f32::from_bits(tmpvalue_d);
    (*gl_info)
        .gl_ops
        .ext
        .p_glUniform1f
        .unwrap_unchecked()(
        (*prog).ps.fog_density_location,
        tmpvalue_f as GLfloat,
    );
    get_fog_start_end(
        core::ptr::addr_of!((*context_gl).c),
        state,
        core::ptr::addr_of_mut!(start),
        core::ptr::addr_of_mut!(end),
    );
    scale = 1.0f32 / (end - start);
    (*gl_info)
        .gl_ops
        .ext
        .p_glUniform1f
        .unwrap_unchecked()((*prog).ps.fog_end_location, end as GLfloat);
    (*gl_info)
        .gl_ops
        .ext
        .p_glUniform1f
        .unwrap_unchecked()((*prog).ps.fog_scale_location, scale as GLfloat);
    checkGLcall!(gl_info, b"fog emulation uniforms\0".as_ptr() as *const i8);
}

unsafe extern "C" fn shader_glsl_clip_plane_uniform(
    context_gl: *const wined3d_context_gl,
    state: *const wined3d_state,
    index: ::core::ffi::c_uint,
    prog: *mut glsl_shader_prog_link,
) {
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;

    ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
        ((*prog).vs.clip_planes_location as ::core::ffi::c_uint).wrapping_add(index) as GLint,
        1,
        &raw const (*(&raw const (*state).clip_planes as *const wined3d_vec4)
            .offset(index as isize))
            .x,
    );
}

unsafe extern "C" fn shader_glsl_load_constants(
    priv_0: *mut shader_glsl_priv,
    context: *mut wined3d_context,
    state: *const wined3d_state,
) {
    let vshader: *const wined3d_shader = (*state).shader[((WINED3D_SHADER_TYPE_VERTEX)) as usize];
    let pshader: *const wined3d_shader = (*state).shader[((WINED3D_SHADER_TYPE_PIXEL)) as usize];
    let ctx_data: *const glsl_context_data =
        (*context).shader_backend_data as *const glsl_context_data;
    let context_gl: *mut wined3d_context_gl = wined3d_context_gl(context);
    let prog: *mut glsl_shader_prog_link = (*ctx_data).glsl_program;
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut position_fixup: [f32; ((4) * (WINED3D_MAX_VIEWPORTS)) as _] =
        [0.0; ((4) * (WINED3D_MAX_VIEWPORTS)) as _];
    let device: *mut wined3d_device = (*context).device;
    let mut constant_version: u32 = 0;
    let mut update_mask: DWORD = 0;
    let mut i: i32 = 0;

    /* No GLSL program set - nothing to do. */
    if prog.is_null() {
        return;
    }

    constant_version = (*prog).constant_version;
    update_mask = (*context).constant_update_mask & (*prog).constant_update_mask;

    if !vshader.is_null() && (*vshader).is_ffp_vs as i32 != 0 {
        /* The shader's constant update mask is WINED3D_SHADER_CONST_VS_F.
         * This may be set from shader_glsl_update_graphics_program().
         * However, we also need to update constants when FFP flags change. */
        let vs_update_mask: uint32_t = (WINED3D_SHADER_CONST_VS_F)
            | (WINED3D_SHADER_CONST_FFP_LIGHTS)
            | (WINED3D_SHADER_CONST_FFP_MATERIAL)
            | (WINED3D_SHADER_CONST_FFP_MODELVIEW)
            | (WINED3D_SHADER_CONST_FFP_PROJ)
            | (WINED3D_SHADER_CONST_FFP_TEXMATRIX)
            | (WINED3D_SHADER_CONST_FFP_VERTEXBLEND)
            | (WINED3D_SHADER_CONST_VS_POINTSIZE);

        if (((*context).constant_update_mask as uint32_t) & vs_update_mask) != 0 {
            shader_glsl_load_constants_f(
                vshader,
                context_gl,
                (*device).push_constants[((WINED3D_PUSH_CONSTANTS_VS_FFP)) as usize],
                &raw mut (*prog).vs.uniform_f_locations as *mut GLint,
                &raw mut (*priv_0).vconst_heap,
                (*priv_0).stack,
                constant_version,
            );
        }
    } else {
        if (update_mask & (WINED3D_SHADER_CONST_VS_F)) != 0 {
            shader_glsl_load_constants_f(
                vshader,
                context_gl,
                (*device).push_constants[((WINED3D_PUSH_CONSTANTS_VS_F)) as usize],
                &raw mut (*prog).vs.uniform_f_locations as *mut GLint,
                &raw mut (*priv_0).vconst_heap,
                (*priv_0).stack,
                constant_version,
            );
        }

        if (update_mask & (WINED3D_SHADER_CONST_VS_I)) != 0 {
            shader_glsl_load_constants_i(
                vshader,
                context_gl,
                (*device).push_constants[((WINED3D_PUSH_CONSTANTS_VS_I)) as usize],
                &raw mut (*prog).vs.uniform_i_locations as *mut GLint as *const GLint,
                (*vshader).reg_maps.integer_constants as uint32_t,
            );
        }

        if (update_mask & (WINED3D_SHADER_CONST_VS_B)) != 0 {
            shader_glsl_load_constants_b(
                vshader,
                context_gl,
                (*device).push_constants[((WINED3D_PUSH_CONSTANTS_VS_B)) as usize],
                &raw mut (*prog).vs.uniform_b_locations as *mut GLint as *const GLint,
                (*vshader).reg_maps.boolean_constants as uint32_t,
            );
        }
    }

    if (update_mask & (WINED3D_SHADER_CONST_VS_CLIP_PLANES)) != 0 {
        if (*gl_info).supported[((WINED3D_GLSL_130)) as usize] != 0 {
            i = (0);
            while (i as u32) < (*gl_info).limits.user_clip_distances {
                shader_glsl_clip_plane_uniform(context_gl, state, i as u32, prog);
                i += 1;
            }
        } else {
            ffp_vertex_update_clip_plane_constants(gl_info, state);
        }
    }

    if (update_mask & (WINED3D_SHADER_CONST_VS_POINTSIZE)) != 0 {
        shader_glsl_pointsize_uniform(context_gl, state, prog);
    }

    if (update_mask & (WINED3D_SHADER_CONST_POS_FIXUP)) != 0 {
        let fixup_count: u32 = if !(*state).shader[((WINED3D_SHADER_TYPE_GEOMETRY)) as usize].is_null() {
            max!((*state).viewport_count, (1))
        } else {
            (1)
        };
        shader_get_position_fixup(
            context,
            state,
            fixup_count,
            &raw mut position_fixup as *mut f32,
        );
        if !(*state).shader[((WINED3D_SHADER_TYPE_GEOMETRY)) as usize].is_null() {
            ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
                (*prog).gs.pos_fixup_location,
                fixup_count as i32,
                &raw mut position_fixup as *mut f32,
            );
        } else if !(*state).shader[((WINED3D_SHADER_TYPE_DOMAIN)) as usize].is_null() {
            ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
                (*prog).ds.pos_fixup_location,
                (1),
                &raw mut position_fixup as *mut f32,
            );
        } else {
            ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
                (*prog).vs.pos_fixup_location,
                (1),
                &raw mut position_fixup as *mut f32,
            );
        }
        checkGLcall!(gl_info, "glUniform4fv");
    }

    if (update_mask & (WINED3D_SHADER_CONST_BASE_VERTEX_ID)) != 0 {
        ((*gl_info).gl_ops.ext.p_glUniform1i.unwrap_unchecked())(
            (*prog).vs.base_vertex_id_location,
            (*state).base_vertex_index as i32,
        );
        checkGLcall!(gl_info, "base vertex id");
    }

    if (update_mask & (WINED3D_SHADER_CONST_FFP_MODELVIEW)) != 0 {
        let constants: *const wined3d_ffp_vs_constants = wined3d_buffer_load_sysmem(
            (*(*context).device).push_constants[((WINED3D_PUSH_CONSTANTS_VS_FFP)) as usize],
            context,
        ) as *const wined3d_ffp_vs_constants;

        ((*gl_info).gl_ops.ext.p_glUniformMatrix4fv.unwrap_unchecked())(
            (*prog).vs.modelview_matrix_location[(0)],
            (1),
            ((FALSE)) as u8,
            &raw const (*constants).modelview.modelview_matrices[(0)]._11,
        );
        checkGLcall!(gl_info, "glUniformMatrix4fv");

        shader_glsl_ffp_vertex_normalmatrix_uniform(context_gl, constants, prog);
    }

    if (update_mask & (WINED3D_SHADER_CONST_FFP_VERTEXBLEND)) != 0 {
        let constants: *const wined3d_ffp_vs_constants = wined3d_buffer_load_sysmem(
            (*(*context).device).push_constants[((WINED3D_PUSH_CONSTANTS_VS_FFP)) as usize],
            context,
        ) as *const wined3d_ffp_vs_constants;

        i = (1);
        while ((i) as u32) < (MAX_VERTEX_BLENDS) {
            if (*prog).vs.modelview_matrix_location[i as usize] == -(1) {
                break;
            }

            ((*gl_info).gl_ops.ext.p_glUniformMatrix4fv.unwrap_unchecked())(
                (*prog).vs.modelview_matrix_location[i as usize],
                (1),
                ((FALSE)) as u8,
                &raw const (*constants).modelview.modelview_matrices[i as usize]._11,
            );
            checkGLcall!(gl_info, "glUniformMatrix4fv");
            i += 1;
        }
    }

    if (update_mask & (WINED3D_SHADER_CONST_FFP_PROJ)) != 0 {
        let constants: *const wined3d_ffp_vs_constants = wined3d_buffer_load_sysmem(
            (*(*context).device).push_constants[((WINED3D_PUSH_CONSTANTS_VS_FFP)) as usize],
            context,
        ) as *const wined3d_ffp_vs_constants;
        let mut projection: wined3d_matrix = core::mem::zeroed();

        get_projection_matrix(context, constants, state, &raw mut projection);
        ((*gl_info).gl_ops.ext.p_glUniformMatrix4fv.unwrap_unchecked())(
            (*prog).vs.projection_matrix_location,
            (1),
            ((FALSE)) as u8,
            &raw mut projection._11,
        );
        checkGLcall!(gl_info, "glUniformMatrix4fv");
    }

    if (update_mask & (WINED3D_SHADER_CONST_FFP_TEXMATRIX)) != 0 {
        let constants: *const wined3d_ffp_vs_constants = wined3d_buffer_load_sysmem(
            (*(*context).device).push_constants[((WINED3D_PUSH_CONSTANTS_VS_FFP)) as usize],
            context,
        ) as *const wined3d_ffp_vs_constants;

        i = (0);
        while ((i) as u32) < (WINED3D_MAX_FFP_TEXTURES) {
            shader_glsl_ffp_vertex_texmatrix_uniform(context_gl, constants, i as u32, prog);
            i += 1;
        }
    }

    if (update_mask & (WINED3D_SHADER_CONST_FFP_MATERIAL)) != 0 {
        shader_glsl_ffp_vertex_material_uniform(context_gl, state, prog);
    }

    if (update_mask & (WINED3D_SHADER_CONST_FFP_LIGHTS)) != 0 {
        let constants: *const wined3d_ffp_vs_constants = wined3d_buffer_load_sysmem(
            (*(*context).device).push_constants[((WINED3D_PUSH_CONSTANTS_VS_FFP)) as usize],
            context,
        ) as *const wined3d_ffp_vs_constants;
        let mut point_count: DWORD = (0);
        let mut spot_count: DWORD = (0);
        let mut directional_count: DWORD = (0);
        let mut parallel_point_count: DWORD = (0);

        i = (0);
        while ((i) as u32) < (WINED3D_MAX_ACTIVE_LIGHTS) {
            if !(*state).light_state.lights[i as usize].is_null() {
                match (*(*state).light_state.lights[i as usize]).OriginalParms.type_ as u32 {
                    (WINED3D_LIGHT_POINT) => {
                        point_count = point_count.wrapping_add(1);
                    }
                    (WINED3D_LIGHT_SPOT) => {
                        spot_count = spot_count.wrapping_add(1);
                    }
                    (WINED3D_LIGHT_DIRECTIONAL) => {
                        directional_count = directional_count.wrapping_add(1);
                    }
                    (WINED3D_LIGHT_PARALLELPOINT) => {
                        parallel_point_count = parallel_point_count.wrapping_add(1);
                    }
                    _ => {
                        FIXME!(
                            "Unhandled light type %#x.\n",
                            (*(*state).light_state.lights[i as usize]).OriginalParms.type_
                                as u32
                        );
                    }
                }
            }
            i += 1;
        }

        ((*gl_info).gl_ops.ext.p_glUniform3fv.unwrap_unchecked())(
            (*prog).vs.light_ambient_location,
            (1),
            &raw const (*constants).light.ambient.r,
        );
        checkGLcall!(gl_info, "glUniform3fv");

        i = (0);
        while (i as DWORD) < point_count {
            shader_glsl_ffp_vertex_light_uniform(
                context_gl,
                state,
                i as u32,
                (WINED3D_LIGHT_POINT),
                &raw const (*constants).light.lights[i as usize],
                prog,
            );
            i += 1;
        }
        while (i as DWORD) < point_count.wrapping_add(spot_count) {
            shader_glsl_ffp_vertex_light_uniform(
                context_gl,
                state,
                i as u32,
                (WINED3D_LIGHT_SPOT),
                &raw const (*constants).light.lights[i as usize],
                prog,
            );
            i += 1;
        }
        while (i as DWORD)
            < point_count
                .wrapping_add(spot_count)
                .wrapping_add(directional_count)
        {
            shader_glsl_ffp_vertex_light_uniform(
                context_gl,
                state,
                i as u32,
                (WINED3D_LIGHT_DIRECTIONAL),
                &raw const (*constants).light.lights[i as usize],
                prog,
            );
            i += 1;
        }
        while (i as DWORD)
            < point_count
                .wrapping_add(spot_count)
                .wrapping_add(directional_count)
                .wrapping_add(parallel_point_count)
        {
            shader_glsl_ffp_vertex_light_uniform(
                context_gl,
                state,
                i as u32,
                (WINED3D_LIGHT_PARALLELPOINT),
                &raw const (*constants).light.lights[i as usize],
                prog,
            );
            i += 1;
        }
    }

    if !pshader.is_null() && (*pshader).is_ffp_ps as i32 != 0 {
        let ps_update_mask: uint32_t = (WINED3D_SHADER_CONST_PS_F)
            | (WINED3D_SHADER_CONST_FFP_COLOR_KEY)
            | (WINED3D_SHADER_CONST_FFP_PS)
            | (WINED3D_SHADER_CONST_PS_BUMP_ENV);

        if (((*context).constant_update_mask as uint32_t) & ps_update_mask) != 0 {
            shader_glsl_load_constants_f(
                pshader,
                context_gl,
                (*device).push_constants[((WINED3D_PUSH_CONSTANTS_PS_FFP)) as usize],
                &raw mut (*prog).ps.uniform_f_locations as *mut GLint,
                &raw mut (*priv_0).pconst_heap,
                (*priv_0).stack,
                constant_version,
            );
        }
    } else {
        if (update_mask & (WINED3D_SHADER_CONST_PS_F)) != 0 {
            shader_glsl_load_constants_f(
                pshader,
                context_gl,
                (*device).push_constants[((WINED3D_PUSH_CONSTANTS_PS_F)) as usize],
                &raw mut (*prog).ps.uniform_f_locations as *mut GLint,
                &raw mut (*priv_0).pconst_heap,
                (*priv_0).stack,
                constant_version,
            );
        }

        if (update_mask & (WINED3D_SHADER_CONST_PS_I)) != 0 {
            shader_glsl_load_constants_i(
                pshader,
                context_gl,
                (*device).push_constants[((WINED3D_PUSH_CONSTANTS_PS_I)) as usize],
                &raw mut (*prog).ps.uniform_i_locations as *mut GLint as *const GLint,
                (*pshader).reg_maps.integer_constants as uint32_t,
            );
        }

        if (update_mask & (WINED3D_SHADER_CONST_PS_B)) != 0 {
            shader_glsl_load_constants_b(
                pshader,
                context_gl,
                (*device).push_constants[((WINED3D_PUSH_CONSTANTS_PS_B)) as usize],
                &raw mut (*prog).ps.uniform_b_locations as *mut GLint as *const GLint,
                (*pshader).reg_maps.boolean_constants as uint32_t,
            );
        }
    }

    if (update_mask & (WINED3D_SHADER_CONST_PS_BUMP_ENV)) != 0 {
        let constants: *const wined3d_ffp_ps_constants = wined3d_buffer_load_sysmem(
            (*(*context_gl).c.device).push_constants[((WINED3D_PUSH_CONSTANTS_PS_FFP)) as usize],
            &raw mut (*context_gl).c,
        ) as *const wined3d_ffp_ps_constants;

        i = (0);
        while ((i) as u32) < (WINED3D_MAX_FFP_TEXTURES) {
            if !((*prog).ps.bumpenv_mat_location[i as usize] == -(1)) {
                ((*gl_info).gl_ops.ext.p_glUniformMatrix2fv.unwrap_unchecked())(
                    (*prog).ps.bumpenv_mat_location[i as usize],
                    (1),
                    (0),
                    &raw const (*constants).bumpenv.matrices[i as usize]._00,
                );

                if (*prog).ps.bumpenv_lum_scale_location[i as usize] != -(1) {
                    ((*gl_info).gl_ops.ext.p_glUniform1fv.unwrap_unchecked())(
                        (*prog).ps.bumpenv_lum_scale_location[i as usize],
                        (1),
                        &raw const (*constants).bumpenv.lscale[i as usize],
                    );
                    ((*gl_info).gl_ops.ext.p_glUniform1fv.unwrap_unchecked())(
                        (*prog).ps.bumpenv_lum_offset_location[i as usize],
                        (1),
                        &raw const (*constants).bumpenv.loffset[i as usize],
                    );
                }
            }
            i += 1;
        }

        checkGLcall!(gl_info, "bump env uniforms");
    }

    if (update_mask & (WINED3D_SHADER_CONST_FFP_COLOR_KEY)) != 0 {
        let constants: *const wined3d_ffp_ps_constants = wined3d_buffer_load_sysmem(
            (*(*context_gl).c.device).push_constants[((WINED3D_PUSH_CONSTANTS_PS_FFP)) as usize],
            &raw mut (*context_gl).c,
        ) as *const wined3d_ffp_ps_constants;

        ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
            (*prog).ps.color_key_location,
            (2),
            &raw const (*constants).color_key[(0)].r,
        );
    }

    if (update_mask & (WINED3D_SHADER_CONST_FFP_PS)) != 0 {
        let constants: *const wined3d_ffp_ps_constants = wined3d_buffer_load_sysmem(
            (*(*context_gl).c.device).push_constants[((WINED3D_PUSH_CONSTANTS_PS_FFP)) as usize],
            &raw mut (*context_gl).c,
        ) as *const wined3d_ffp_ps_constants;

        if (*prog).ps.tex_factor_location != -(1) {
            ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
                (*prog).ps.tex_factor_location,
                (1),
                &raw const (*constants).texture_factor.r,
            );
        }

        ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
            (*prog).ps.specular_enable_location,
            (1),
            &raw const (*constants).specular_enable.r,
        );

        i = (0);
        while ((i) as u32) < (WINED3D_MAX_FFP_TEXTURES) {
            if !((*prog).ps.tss_constant_location[i as usize] == -(1)) {
                ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
                    (*prog).ps.tss_constant_location[i as usize],
                    (1),
                    &raw const (*constants).texture_constants[i as usize].r,
                );
            }
            i += 1;
        }

        checkGLcall!(gl_info, "fixed function uniforms");
    }

    if (update_mask & (WINED3D_SHADER_CONST_PS_FOG)) != 0 {
        shader_glsl_load_fog_uniform(context_gl, state, prog);
    }

    if (update_mask & (WINED3D_SHADER_CONST_PS_ALPHA_TEST)) != 0 {
        let constants: *const wined3d_ffp_ps_constants = wined3d_buffer_load_sysmem(
            (*(*context_gl).c.device).push_constants[((WINED3D_PUSH_CONSTANTS_PS_FFP)) as usize],
            &raw mut (*context_gl).c,
        ) as *const wined3d_ffp_ps_constants;

        ((*gl_info).gl_ops.ext.p_glUniform1f.unwrap_unchecked())(
            (*prog).ps.alpha_test_ref_location,
            (*constants).alpha_test_ref,
        );
        checkGLcall!(gl_info, "alpha test emulation uniform");
    }

    if (*priv_0).next_constant_version == (UINT_MAX) {
        TRACE!("Max constant version reached, resetting to 0.\n");
        unsafe extern "C" fn reset_program_constant_version_entry(
            entry: *mut rb_entry,
            context: *mut core::ffi::c_void,
        ) {
            reset_program_constant_version(entry as *mut list, context);
        }
        wine_rb_for_each_entry(
            &raw mut (*priv_0).program_lookup,
            Some(reset_program_constant_version_entry),
            core::ptr::null_mut(),
        );
        (*priv_0).next_constant_version = (1);
    } else {
        let fresh18 = (*priv_0).next_constant_version;
        (*priv_0).next_constant_version = (*priv_0).next_constant_version.wrapping_add(1);
        (*prog).constant_version = fresh18 as u32;
    }
}

unsafe extern "C" fn update_heap_entry(heap: *mut constant_heap, idx: ::core::ffi::c_uint, new_version: DWORD) {
    let mut entries: *mut constant_entry = (*heap).entries;
    let mut positions: *mut ::core::ffi::c_uint = (*heap).positions;
    let mut heap_idx: ::core::ffi::c_uint = 0;
    let mut parent_idx: ::core::ffi::c_uint = 0;

    if *(*heap).contained.offset(idx as isize) == 0 {
        let fresh15 = (*heap).size;
        (*heap).size = (*heap).size.wrapping_add(1);
        heap_idx = fresh15;
        *(*heap).contained.offset(idx as isize) = TRUE as BOOL;
    } else {
        heap_idx = *positions.offset(idx as isize);
    }

    while heap_idx > 1 as ::core::ffi::c_uint {
        parent_idx = heap_idx >> 1 as ::core::ffi::c_int;

        if new_version <= (*entries.offset(parent_idx as isize)).version {
            break;
        }

        *entries.offset(heap_idx as isize) = core::ptr::read(entries.offset(parent_idx as isize));
        *positions.offset((*entries.offset(parent_idx as isize)).idx as isize) = heap_idx;
        heap_idx = parent_idx;
    }

    (*entries.offset(heap_idx as isize)).version = new_version as ::core::ffi::c_uint;
    (*entries.offset(heap_idx as isize)).idx = idx;
    *positions.offset(idx as isize) = heap_idx;
}

unsafe extern "C" fn shader_glsl_update_float_vertex_constants(device: *mut wined3d_device, start: UINT, count: UINT) {
    let mut priv_: *mut shader_glsl_priv = (*device).shader_priv as *mut shader_glsl_priv;
    let mut heap: *mut constant_heap = &raw mut (*priv_).vconst_heap;
    let mut i: UINT = 0;
    i = start;
    while i < count.wrapping_add(start) {
        update_heap_entry(heap, i as ::core::ffi::c_uint, (*priv_).next_constant_version as DWORD);
        i = i.wrapping_add(1);
    }
}

unsafe extern "C" fn shader_glsl_update_float_pixel_constants(device: *mut wined3d_device, start: UINT, count: UINT) {
    let priv_: *mut shader_glsl_priv = (*device).shader_priv as *mut shader_glsl_priv;
    let heap: *mut constant_heap = core::ptr::addr_of_mut!((*priv_).pconst_heap);
    let mut i: UINT;
    i = start;
    while i < count + start {
        update_heap_entry(heap, i, (*priv_).next_constant_version as DWORD);
        i = i + 1;
    }
}

unsafe extern "C" fn vec4_varyings(shader_major: DWORD, gl_info: *const wined3d_gl_info) -> ::core::ffi::c_uint {
    let mut ret: ::core::ffi::c_uint = (*gl_info).limits.glsl_varyings / 4;
    /* 4.0 shaders do not write clip coords because d3d10 does not support user clipplanes */
    if shader_major > 3 {
        return ret;
    }

    /* 3.0 shaders may need an extra varying for the clip coord on some cards(mostly dx10 ones) */
    if (*gl_info).quirks & WINED3D_QUIRK_GLSL_CLIP_VARYING != 0 {
        ret -= 1;
    }
    return ret;
}

unsafe extern "C" fn needs_legacy_glsl_syntax(gl_info: *const wined3d_gl_info) -> BOOL {
    return ((*gl_info).glsl_version < MAKEDWORD_VERSION!(1, 30)) as BOOL;
}

unsafe extern "C" fn shader_glsl_use_explicit_attrib_location(gl_info: *const wined3d_gl_info) -> BOOL {
    return ((*gl_info).supported[ARB_EXPLICIT_ATTRIB_LOCATION as usize] != 0
        && shader_glsl_use_layout_qualifier(gl_info) != 0
        && needs_legacy_glsl_syntax(gl_info) == 0) as BOOL;
}

unsafe extern "C" fn shader_glsl_use_interface_blocks(gl_info: *const wined3d_gl_info) -> BOOL {
    return (shader_glsl_get_version(gl_info) >= 150) as BOOL;
}

unsafe extern "C" fn get_attribute_keyword(gl_info: *const wined3d_gl_info) -> *const i8 {
    return if needs_legacy_glsl_syntax(gl_info) != 0 {
        b"attribute\0".as_ptr() as *const i8
    } else {
        b"in\0".as_ptr() as *const i8
    };
}

#[no_mangle]
unsafe extern "C" fn declare_in_varying_v(
    gl_info: *const wined3d_gl_info,
    buffer: *mut wined3d_string_buffer,
    flat: BOOL,
    format: *const ::core::ffi::c_char,
    ap_list: *mut ::core::ffi::c_void,
) {
    let mut args: va_list = *(ap_list as *mut va_list);
    let mut ret: ::core::ffi::c_int = 0;
    shader_addline(
        buffer,
        b"%s%s \0" as *const u8 as *const ::core::ffi::c_char,
        if flat != 0 {
            b"flat \0" as *const u8 as *const ::core::ffi::c_char
        } else {
            b"\0" as *const u8 as *const ::core::ffi::c_char
        },
        if needs_legacy_glsl_syntax(gl_info) != 0 {
            b"varying\0" as *const u8 as *const ::core::ffi::c_char
        } else {
            b"in\0" as *const u8 as *const ::core::ffi::c_char
        },
    );
    loop {

        ret = shader_vaddline(buffer, format, args);

        if ret == 0 {
            return;
        }
        if string_buffer_resize(buffer, ret) == 0 {
            return;
        }
    }
}



#[no_mangle]
unsafe extern "C" fn declare_out_varying_v(gl_info: *const wined3d_gl_info, buffer: *mut wined3d_string_buffer, flat: BOOL, format: *const i8, ap_list: *mut ::core::ffi::c_void) {
    let mut args: va_list = *(ap_list as *mut va_list);
    let mut ret: i32;
    shader_addline(
        buffer,
        b"%s%s \0".as_ptr() as *const i8,
        if flat != 0 { b"flat \0".as_ptr() as *const i8 } else { b"\0".as_ptr() as *const i8 },
        if needs_legacy_glsl_syntax(gl_info) != 0 { b"varying\0".as_ptr() as *const i8 } else { b"out\0".as_ptr() as *const i8 },
    );
    loop {

        ret = shader_vaddline(buffer, format, args);

        if ret == 0 {
            return;
        }
        if string_buffer_resize(buffer, ret) == 0 {
            return;
        }
    }
}



unsafe extern "C" fn shader_glsl_shader_input_name(
    gl_info: *const wined3d_gl_info,
) -> *const i8 {
    return if shader_glsl_use_interface_blocks(gl_info) != 0 {
        b"shader_in.reg\0".as_ptr() as *const i8
    } else {
        b"ps_link\0".as_ptr() as *const i8
    };
}

unsafe extern "C" fn shader_glsl_shader_output_name(
    gl_info: *const wined3d_gl_info,
) -> *const ::core::ffi::c_char {
    return if shader_glsl_use_interface_blocks(gl_info) != 0 {
        b"shader_out.reg\0".as_ptr() as *const ::core::ffi::c_char
    } else {
        b"ps_link\0".as_ptr() as *const ::core::ffi::c_char
    };
}

unsafe extern "C" fn shader_glsl_interpolation_qualifiers(mode: wined3d_shader_interpolation_mode) -> *const i8 {
    match mode as u32 {
        WINED3DSIM_CONSTANT => {
            return b"flat \0".as_ptr() as *const i8;
        }
        WINED3DSIM_LINEAR_NOPERSPECTIVE => {
            return b"noperspective \0".as_ptr() as *const i8;
        }
        WINED3DSIM_NONE | WINED3DSIM_LINEAR => {}
        _ => {
            FIXME!("Unhandled interpolation mode %#x.\n", mode);
        }
    }
    return b"\0".as_ptr() as *const i8;
}

unsafe extern "C" fn wined3d_extract_interpolation_mode(
    mut packed_interpolation_mode: *const uint32_t,
    mut register_idx: ::core::ffi::c_uint,
) -> wined3d_shader_interpolation_mode {
    return wined3d_extract_bits(
        packed_interpolation_mode,
        register_idx.wrapping_mul(WINED3D_PACKED_INTERPOLATION_BIT_COUNT as ::core::ffi::c_uint),
        WINED3D_PACKED_INTERPOLATION_BIT_COUNT as ::core::ffi::c_uint,
    ) as wined3d_shader_interpolation_mode;
}

unsafe extern "C" fn shader_glsl_declare_shader_inputs(gl_info: *const wined3d_gl_info, buffer: *mut wined3d_string_buffer, element_count: u32, interpolation_mode: *const uint32_t, unroll: BOOL) {
    let mut mode: wined3d_shader_interpolation_mode = core::mem::zeroed();
    let mut i: u32;

    if shader_glsl_use_interface_blocks(gl_info) != 0 {
        if unroll != 0 {
            shader_addline(buffer, b"in shader_in_out {\n\0".as_ptr() as *const i8);
            i = 0;
            while i < element_count {
                mode = wined3d_extract_interpolation_mode(interpolation_mode, i);
                shader_addline(buffer, b"    %svec4 reg%u;\n\0".as_ptr() as *const i8, shader_glsl_interpolation_qualifiers(mode), i);
                i = i.wrapping_add(1);
            }
            shader_addline(buffer, b"} shader_in;\n\0".as_ptr() as *const i8);
        } else {
            shader_addline(buffer, b"in shader_in_out { vec4 reg[%u]; } shader_in;\n\0".as_ptr() as *const i8, element_count);
        }
    } else {
        declare_in_varying(gl_info, buffer, (FALSE) as BOOL, b"vec4 ps_link[%u];\n\0".as_ptr() as *const i8, element_count);
    }
}

unsafe extern "C" fn needs_interpolation_qualifiers_for_shader_outputs(gl_info: *const wined3d_gl_info) -> BOOL {
    return ((*gl_info).glsl_version < MAKEDWORD_VERSION!(4, 40)) as BOOL;
}

unsafe extern "C" fn shader_glsl_declare_shader_outputs(
    gl_info: *const wined3d_gl_info,
    buffer: *mut wined3d_string_buffer,
    element_count: ::core::ffi::c_uint,
    rasterizer_setup: BOOL,
    interpolation_mode: *const uint32_t,
) {
    let mut mode: wined3d_shader_interpolation_mode = WINED3DSIM_NONE;
    let mut i: ::core::ffi::c_uint = 0;
    if shader_glsl_use_interface_blocks(gl_info) != 0 {
        if rasterizer_setup != 0 {
            shader_addline(
                buffer,
                b"out shader_in_out {\n\0".as_ptr() as *const ::core::ffi::c_char,
            );
            i = 0;
            while i < element_count {
                let mut interpolation_qualifiers: *const ::core::ffi::c_char =
                    b"\0".as_ptr() as *const ::core::ffi::c_char;
                if needs_interpolation_qualifiers_for_shader_outputs(gl_info) != 0 {
                    mode = wined3d_extract_interpolation_mode(interpolation_mode, i);
                    interpolation_qualifiers = shader_glsl_interpolation_qualifiers(mode);
                }
                shader_addline(
                    buffer,
                    b"    %svec4 reg%u;\n\0".as_ptr() as *const ::core::ffi::c_char,
                    interpolation_qualifiers,
                    i,
                );
                i = i.wrapping_add(1);
            }
            shader_addline(
                buffer,
                b"} shader_out;\n\0".as_ptr() as *const ::core::ffi::c_char,
            );
        } else {
            shader_addline(
                buffer,
                b"out shader_in_out { vec4 reg[%u]; } shader_out;\n\0".as_ptr()
                    as *const ::core::ffi::c_char,
                element_count,
            );
        }
    } else {
        declare_out_varying(
            gl_info,
            buffer,
            (FALSE) as BOOL,
            b"vec4 ps_link[%u];\n\0".as_ptr() as *const ::core::ffi::c_char,
            element_count,
        );
    }
}

unsafe extern "C" fn use_legacy_fragment_output(gl_info: *const wined3d_gl_info) -> BOOL {
    return ((*gl_info).glsl_version <= MAKEDWORD_VERSION!(1, 30)) as BOOL;
}

unsafe extern "C" fn get_fragment_output(
    gl_info: *const wined3d_gl_info,
) -> *const ::core::ffi::c_char {
    return if use_legacy_fragment_output(gl_info) != 0 {
        b"gl_FragData\0".as_ptr() as *const ::core::ffi::c_char
    } else {
        b"ps_out\0".as_ptr() as *const ::core::ffi::c_char
    };
}

unsafe extern "C" fn glsl_primitive_type_from_d3d(
    mut primitive_type: wined3d_primitive_type,
) -> *const ::core::ffi::c_char {
    match primitive_type as ::core::ffi::c_uint {
        WINED3D_PT_POINTLIST => {
            return b"points\0" as *const u8 as *const ::core::ffi::c_char;
        }
        WINED3D_PT_LINELIST => {
            return b"lines\0" as *const u8 as *const ::core::ffi::c_char;
        }
        WINED3D_PT_LINESTRIP => {
            return b"line_strip\0" as *const u8 as *const ::core::ffi::c_char;
        }
        WINED3D_PT_TRIANGLELIST => {
            return b"triangles\0" as *const u8 as *const ::core::ffi::c_char;
        }
        WINED3D_PT_TRIANGLESTRIP => {
            return b"triangle_strip\0" as *const u8 as *const ::core::ffi::c_char;
        }
        WINED3D_PT_LINELIST_ADJ => {
            return b"lines_adjacency\0" as *const u8 as *const ::core::ffi::c_char;
        }
        WINED3D_PT_TRIANGLELIST_ADJ => {
            return b"triangles_adjacency\0" as *const u8 as *const ::core::ffi::c_char;
        }
        _ => {
            FIXME!(
                "Unhandled primitive type %s.\n",
                debug_d3dprimitivetype(primitive_type)
            );
            return b"\0" as *const u8 as *const ::core::ffi::c_char;
        }
    }
}

unsafe extern "C" fn glsl_is_color_reg_read(shader: *const wined3d_shader, idx: u32) -> BOOL {
    let input_signature: *const wined3d_shader_signature = core::ptr::addr_of!((*shader).input_signature);
    let reg_maps: *const wined3d_shader_reg_maps = core::ptr::addr_of!((*shader).reg_maps);
    let input_reg_used: DWORD = (*shader).u.ps.input_reg_used;
    let mut i: u32;

    if ((*reg_maps).shader_version.major as i32) < 3 {
        return (input_reg_used & (1 << idx)) as BOOL;
    }

    i = 0;
    while i < (*input_signature).element_count {
        let input: *const wined3d_shader_signature_element =
            (*input_signature).elements.offset(i as isize) as *mut wined3d_shader_signature_element;

        if !(((*reg_maps).input_registers & (1 << (*input).register_idx)) == 0) {
            if shader_match_semantic((*input).semantic_name, WINED3D_DECL_USAGE_COLOR) != 0
                && (*input).semantic_idx == idx
            {
                return (input_reg_used & (1 << (*input).register_idx)) as BOOL;
            }
        }
        i = i.wrapping_add(1);
    }
    return (FALSE) as BOOL;
}

unsafe extern "C" fn shader_glsl_declare_typed_vertex_attribute(
    buffer: *mut wined3d_string_buffer,
    gl_info: *const wined3d_gl_info,
    vector_type: *const ::core::ffi::c_char,
    scalar_type: *const ::core::ffi::c_char,
    index: ::core::ffi::c_uint,
) {
    shader_addline(
        buffer,
        b"%s %s4 vs_in_%s%u;\n\0".as_ptr() as *const ::core::ffi::c_char,
        get_attribute_keyword(gl_info),
        vector_type,
        scalar_type,
        index,
    );
    shader_addline(
        buffer,
        b"vec4 vs_in%u = %sBitsToFloat(vs_in_%s%u);\n\0".as_ptr() as *const ::core::ffi::c_char,
        index,
        scalar_type,
        scalar_type,
        index,
    );
}

unsafe extern "C" fn shader_glsl_declare_generic_vertex_attribute(
    mut buffer: *mut wined3d_string_buffer,
    mut gl_info: *const wined3d_gl_info,
    mut e: *const wined3d_shader_signature_element,
) {
    let mut index: ::core::ffi::c_uint = (*e).register_idx;
    let mut type_: wined3d_component_type;

    if (*e).sysval_semantic == WINED3D_SV_VERTEX_ID {
        shader_addline(
            buffer,
            b"uniform int base_vertex_id;\n\0".as_ptr() as *const i8,
        );
        shader_addline(
            buffer,
            b"vec4 vs_in%u = vec4(intBitsToFloat(gl_VertexID - base_vertex_id), 0.0, 0.0, 0.0);\n\0"
                .as_ptr() as *const i8,
            index,
        );
        return;
    }
    if (*e).sysval_semantic == WINED3D_SV_INSTANCE_ID {
        shader_addline(
            buffer,
            b"vec4 vs_in%u = vec4(intBitsToFloat(gl_InstanceID), 0.0, 0.0, 0.0);\n\0"
                .as_ptr() as *const i8,
            index,
        );
        return;
    }
    if (*e).sysval_semantic != 0 && (*e).sysval_semantic != WINED3D_SV_POSITION {
        FIXME!("Unhandled sysval semantic %#x.\n", (*e).sysval_semantic);
    }

    if shader_glsl_use_explicit_attrib_location(gl_info) != 0 {
        shader_addline(
            buffer,
            b"layout(location = %u) \0".as_ptr() as *const i8,
            index,
        );
    }

    type_ = (*e).component_type;
    if (type_ as ::core::ffi::c_uint) >= ARRAY_SIZE!(component_type_info) {
        type_ = WINED3D_TYPE_FLOAT;
    }
    if type_ == WINED3D_TYPE_FLOAT || type_ == WINED3D_TYPE_UNKNOWN {
        shader_addline(
            buffer,
            b"%s vec4 vs_in%u;\n\0".as_ptr() as *const i8,
            get_attribute_keyword(gl_info),
            index,
        );
    } else {
        shader_glsl_declare_typed_vertex_attribute(
            buffer,
            gl_info,
            component_type_info[type_ as usize].glsl_vector_type,
            component_type_info[type_ as usize].glsl_scalar_type,
            index,
        );
    }
}

unsafe extern "C" fn shader_generate_glsl_declarations(
    context_gl: *const wined3d_context_gl,
    buffer: *mut wined3d_string_buffer,
    shader: *const wined3d_shader,
    reg_maps: *const wined3d_shader_reg_maps,
    ctx_priv: *const shader_glsl_ctx_priv,
) {
    let version: *const wined3d_shader_version = core::ptr::addr_of!((*reg_maps).shader_version);
    let vs_args: *const vs_compile_args = (*ctx_priv).cur_vs_args;
    let ps_args: *const ps_compile_args = (*ctx_priv).cur_ps_args;
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut idx_temp_reg: *const wined3d_shader_indexable_temp =
        core::ptr::null::<wined3d_shader_indexable_temp>();
    let mut uniform_block_base: ::core::ffi::c_uint = 0;
    let mut uniform_block_count: ::core::ffi::c_uint = 0;
    let mut resource_type: wined3d_shader_resource_type = WINED3D_SHADER_RESOURCE_NONE;
    let mut lconst: *const wined3d_shader_lconst = core::ptr::null::<wined3d_shader_lconst>();
    let mut prefix: *const ::core::ffi::c_char = core::ptr::null::<::core::ffi::c_char>();
    let mut i: ::core::ffi::c_uint = 0;
    let mut map: uint32_t = 0;

    if wined3d_settings.strict_shader_math != 0 {
        shader_addline(
            buffer,
            b"#pragma optionNV(fastmath off)\n\0" as *const u8 as *const ::core::ffi::c_char,
        );
    }

    prefix = shader_glsl_get_prefix((*version).type_);

    /* Prototype the subroutines */
    map = (*reg_maps).labels as uint32_t;
    while map != 0 {
        i = wined3d_bit_scan(core::ptr::addr_of_mut!(map)) as ::core::ffi::c_uint;
        shader_addline(
            buffer,
            b"void subroutine%u();\n\0" as *const u8 as *const ::core::ffi::c_char,
            i,
        );
    }

    if (*version).type_ as ::core::ffi::c_uint != WINED3D_SHADER_TYPE_PIXEL as ::core::ffi::c_uint
        && (*version).type_ as ::core::ffi::c_uint != WINED3D_SHADER_TYPE_COMPUTE as ::core::ffi::c_uint
    {
        if (*version).type_ as ::core::ffi::c_uint == WINED3D_SHADER_TYPE_HULL as ::core::ffi::c_uint {
            shader_addline(
                buffer,
                b"out gl_PerVertex { invariant vec4 gl_Position; } gl_out[];\n\0" as *const u8
                    as *const ::core::ffi::c_char,
            );
        } else {
            shader_addline(
                buffer,
                b"invariant gl_Position;\n\0" as *const u8 as *const ::core::ffi::c_char,
            );
        }
    }

    /* Declare the constants (aka uniforms) */
    if (*(*shader).limits).constant_float > 0 as ::core::ffi::c_uint {
        let mut max_constantsF: ::core::ffi::c_uint = 0;

        if (*version).type_ as ::core::ffi::c_uint == WINED3D_SHADER_TYPE_PIXEL as ::core::ffi::c_uint {
            /* No indirect addressing here. */
            max_constantsF = (*gl_info).limits.glsl_ps_float_constants;
        } else {
            if (*reg_maps).usesrelconstF() != 0 {
                max_constantsF = (*gl_info)
                    .limits
                    .glsl_vs_float_constants
                    .wrapping_sub(3 as ::core::ffi::c_uint);
                if (*vs_args).clip_enabled() != 0 {
                    max_constantsF =
                        max_constantsF.wrapping_sub((*gl_info).limits.user_clip_distances);
                }
                max_constantsF = max_constantsF.wrapping_sub(wined3d_popcount(
                    (*reg_maps).integer_constants as ::core::ffi::c_uint,
                ));
                max_constantsF = max_constantsF.wrapping_sub(wined3d_popcount(
                    (*reg_maps).boolean_constants as ::core::ffi::c_uint,
                ));
                /* Set by driver quirks in directx.c */
                max_constantsF = max_constantsF.wrapping_sub((*gl_info).reserved_glsl_constants);

                if max_constantsF < (*(*shader).limits).constant_float {
                    static mut once: ::core::ffi::c_uint = 0;
                    let fresh = once;
                    once = once.wrapping_add(1);
                    if fresh == 0 {
                        WINE_ERR_!(__wine_dbch_winediag,
                            "The hardware does not support enough uniform components to run this shader, it may not render correctly.\n"
                        );
                    } else {
                        WARN!(
                            "The hardware does not support enough uniform components to run this shader.\n"
                        );
                    }
                }
            } else {
                max_constantsF = (*gl_info).limits.glsl_vs_float_constants;
            }
        }
        max_constantsF = min!((*(*shader).limits).constant_float, max_constantsF);
        shader_addline(
            buffer,
            b"uniform vec4 %s_c[%u];\n\0" as *const u8 as *const ::core::ffi::c_char,
            prefix,
            max_constantsF,
        );
    }

    /* Always declare the full set of constants, the compiler can remove the
     * unused ones because d3d doesn't (yet) support indirect int and bool
     * constant addressing. This avoids problems if the app uses e.g. i0 and i9. */
    if (*(*shader).limits).constant_int > 0 as ::core::ffi::c_uint
        && (*reg_maps).integer_constants as ::core::ffi::c_int != 0
    {
        shader_addline(
            buffer,
            b"uniform ivec4 %s_i[%u];\n\0" as *const u8 as *const ::core::ffi::c_char,
            prefix,
            (*(*shader).limits).constant_int,
        );
    }

    if (*(*shader).limits).constant_bool > 0 as ::core::ffi::c_uint
        && (*reg_maps).boolean_constants as ::core::ffi::c_int != 0
    {
        shader_addline(
            buffer,
            b"uniform bool %s_b[%u];\n\0" as *const u8 as *const ::core::ffi::c_char,
            prefix,
            (*(*shader).limits).constant_bool,
        );
    }

    /* Declare immediate constant buffer */
    if !(*reg_maps).icb.is_null() {
        shader_addline(
            buffer,
            b"uniform vec4 %s_icb[%u];\n\0" as *const u8 as *const ::core::ffi::c_char,
            prefix,
            (*(*reg_maps).icb).vec4_count,
        );
    }

    /* Declare constant buffers */
    wined3d_gl_limits_get_uniform_block_range(
        core::ptr::addr_of!((*gl_info).limits),
        (*version).type_,
        core::ptr::addr_of_mut!(uniform_block_base),
        core::ptr::addr_of_mut!(uniform_block_count),
    );
    i = 0 as ::core::ffi::c_uint;
    while i < min!(uniform_block_count, WINED3D_MAX_CBS as ::core::ffi::c_uint) {
        if (*reg_maps).cb_sizes[i as usize] != 0 {
            shader_addline(
                buffer,
                b"layout(std140\0" as *const u8 as *const ::core::ffi::c_char,
            );
            if shader_glsl_use_layout_binding_qualifier(gl_info) != 0 {
                shader_addline(
                    buffer,
                    b", binding = %u\0" as *const u8 as *const ::core::ffi::c_char,
                    uniform_block_base.wrapping_add(i),
                );
            }
            shader_addline(
                buffer,
                b") uniform block_%s_cb%u { vec4 %s_cb%u[%u]; };\n\0" as *const u8
                    as *const ::core::ffi::c_char,
                prefix,
                i,
                prefix,
                i,
                (*reg_maps).cb_sizes[i as usize],
            );
        }
        i = i.wrapping_add(1);
    }

    /* Declare texture samplers */
    i = 0 as ::core::ffi::c_uint;
    while (i as usize) < (*reg_maps).sampler_map.count as usize {
        let mut entry: *mut wined3d_shader_sampler_map_entry =
            core::ptr::null_mut::<wined3d_shader_sampler_map_entry>();
        let mut sampler_type_prefix: *const ::core::ffi::c_char =
            core::ptr::null::<::core::ffi::c_char>();
        let mut sampler_type: *const ::core::ffi::c_char =
            core::ptr::null::<::core::ffi::c_char>();
        let mut shadow_sampler: BOOL = 0;

        entry = (*reg_maps).sampler_map.entries.offset(i as isize)
            as *mut wined3d_shader_sampler_map_entry;

        if (*entry).resource_idx as u32
            >= ARRAY_SIZE!((*core::ptr::addr_of!((*reg_maps).resource_info)))
        {
            ERR!("Invalid resource index %u.\n", (*entry).resource_idx);
            i = i.wrapping_add(1);
            continue;
        }

        match (*reg_maps).resource_info[(*entry).resource_idx as usize].data_type
            as ::core::ffi::c_uint
        {
            WINED3D_DATA_FLOAT
            | WINED3D_DATA_UNORM
            | WINED3D_DATA_SNORM => {
                sampler_type_prefix = b"\0" as *const u8 as *const ::core::ffi::c_char;
            }
            WINED3D_DATA_INT => {
                sampler_type_prefix = b"i\0" as *const u8 as *const ::core::ffi::c_char;
            }
            WINED3D_DATA_UINT => {
                sampler_type_prefix = b"u\0" as *const u8 as *const ::core::ffi::c_char;
            }
            _ => {
                sampler_type_prefix = b"\0" as *const u8 as *const ::core::ffi::c_char;
                ERR!(
                    "Unhandled resource data type %#x.\n",
                    (*reg_maps).resource_info[i as usize].data_type as ::core::ffi::c_uint
                );
            }
        }

        shadow_sampler = shader_sampler_is_shadow(
            shader,
            ps_args,
            (*entry).resource_idx,
            (*entry).sampler_idx,
        );
        resource_type = (if (*version).type_ as ::core::ffi::c_uint
            == WINED3D_SHADER_TYPE_PIXEL as ::core::ffi::c_uint
        {
            pixelshader_get_resource_type(reg_maps, (*entry).resource_idx, (*ps_args).tex_types)
                as ::core::ffi::c_uint
        } else {
            (*reg_maps).resource_info[(*entry).resource_idx as usize].type_ as ::core::ffi::c_uint
        }) as wined3d_shader_resource_type;

        match resource_type as ::core::ffi::c_uint {
            WINED3D_SHADER_RESOURCE_BUFFER => {
                sampler_type = b"samplerBuffer\0" as *const u8 as *const ::core::ffi::c_char;
            }
            WINED3D_SHADER_RESOURCE_TEXTURE_1D => {
                if shadow_sampler != 0 {
                    sampler_type = b"sampler1DShadow\0" as *const u8 as *const ::core::ffi::c_char;
                } else {
                    sampler_type = b"sampler1D\0" as *const u8 as *const ::core::ffi::c_char;
                }
            }
            WINED3D_SHADER_RESOURCE_TEXTURE_2D => {
                if shadow_sampler != 0 {
                    sampler_type = b"sampler2DShadow\0" as *const u8 as *const ::core::ffi::c_char;
                } else {
                    sampler_type = b"sampler2D\0" as *const u8 as *const ::core::ffi::c_char;
                }
            }
            WINED3D_SHADER_RESOURCE_TEXTURE_3D => {
                if shadow_sampler != 0 {
                    FIXME!("Unsupported 3D shadow sampler.\n");
                }
                sampler_type = b"sampler3D\0" as *const u8 as *const ::core::ffi::c_char;
            }
            WINED3D_SHADER_RESOURCE_TEXTURE_CUBE => {
                if shadow_sampler != 0 {
                    sampler_type =
                        b"samplerCubeShadow\0" as *const u8 as *const ::core::ffi::c_char;
                } else {
                    sampler_type = b"samplerCube\0" as *const u8 as *const ::core::ffi::c_char;
                }
            }
            WINED3D_SHADER_RESOURCE_TEXTURE_1DARRAY => {
                if shadow_sampler != 0 {
                    sampler_type =
                        b"sampler1DArrayShadow\0" as *const u8 as *const ::core::ffi::c_char;
                } else {
                    sampler_type = b"sampler1DArray\0" as *const u8 as *const ::core::ffi::c_char;
                }
            }
            WINED3D_SHADER_RESOURCE_TEXTURE_2DARRAY => {
                if shadow_sampler != 0 {
                    sampler_type =
                        b"sampler2DArrayShadow\0" as *const u8 as *const ::core::ffi::c_char;
                } else {
                    sampler_type = b"sampler2DArray\0" as *const u8 as *const ::core::ffi::c_char;
                }
            }
            WINED3D_SHADER_RESOURCE_TEXTURE_CUBEARRAY => {
                if shadow_sampler != 0 {
                    sampler_type =
                        b"samplerCubeArrayShadow\0" as *const u8 as *const ::core::ffi::c_char;
                } else {
                    sampler_type =
                        b"samplerCubeArray\0" as *const u8 as *const ::core::ffi::c_char;
                }
            }
            WINED3D_SHADER_RESOURCE_TEXTURE_2DMS => {
                sampler_type = b"sampler2DMS\0" as *const u8 as *const ::core::ffi::c_char;
            }
            WINED3D_SHADER_RESOURCE_TEXTURE_2DMSARRAY => {
                sampler_type = b"sampler2DMSArray\0" as *const u8 as *const ::core::ffi::c_char;
            }
            _ => {
                sampler_type = b"unsupported_sampler\0" as *const u8 as *const ::core::ffi::c_char;
            }
        }

        if shader_glsl_use_layout_binding_qualifier(gl_info) != 0 {
            shader_glsl_append_sampler_binding_qualifier(
                buffer,
                core::ptr::addr_of!((*context_gl).c),
                version,
                (*entry).bind_idx,
            );
        }
        shader_addline(
            buffer,
            b"uniform %s%s %s_sampler%u;\n\0" as *const u8 as *const ::core::ffi::c_char,
            sampler_type_prefix,
            sampler_type,
            prefix,
            (*entry).bind_idx,
        );
        i = i.wrapping_add(1);
    }

    /* Declare images */
    i = 0 as ::core::ffi::c_uint;
    while (i as u32) < ARRAY_SIZE!((*core::ptr::addr_of!((*reg_maps).uav_resource_info))) {
        let mut image_type_prefix: *const ::core::ffi::c_char =
            core::ptr::null::<::core::ffi::c_char>();
        let mut image_type: *const ::core::ffi::c_char = core::ptr::null::<::core::ffi::c_char>();
        let mut read_format: *const ::core::ffi::c_char =
            core::ptr::null::<::core::ffi::c_char>();

        if !((*reg_maps).uav_resource_info[i as usize].type_ as u64 == 0) {
            match (*reg_maps).uav_resource_info[i as usize].data_type as ::core::ffi::c_uint {
                WINED3D_DATA_FLOAT
                | WINED3D_DATA_UNORM
                | WINED3D_DATA_SNORM => {
                    image_type_prefix = b"\0" as *const u8 as *const ::core::ffi::c_char;
                    read_format = b"r32f\0" as *const u8 as *const ::core::ffi::c_char;
                }
                WINED3D_DATA_INT => {
                    image_type_prefix = b"i\0" as *const u8 as *const ::core::ffi::c_char;
                    read_format = b"r32i\0" as *const u8 as *const ::core::ffi::c_char;
                }
                WINED3D_DATA_UINT => {
                    image_type_prefix = b"u\0" as *const u8 as *const ::core::ffi::c_char;
                    read_format = b"r32ui\0" as *const u8 as *const ::core::ffi::c_char;
                }
                _ => {
                    image_type_prefix = b"\0" as *const u8 as *const ::core::ffi::c_char;
                    read_format = b"\0" as *const u8 as *const ::core::ffi::c_char;
                    ERR!(
                        "Unhandled resource data type %#x.\n",
                        (*reg_maps).uav_resource_info[i as usize].data_type as ::core::ffi::c_uint
                    );
                }
            }

            match (*reg_maps).uav_resource_info[i as usize].type_ as ::core::ffi::c_uint {
                WINED3D_SHADER_RESOURCE_BUFFER => {
                    image_type = b"imageBuffer\0" as *const u8 as *const ::core::ffi::c_char;
                }
                WINED3D_SHADER_RESOURCE_TEXTURE_1D => {
                    image_type = b"image1D\0" as *const u8 as *const ::core::ffi::c_char;
                }
                WINED3D_SHADER_RESOURCE_TEXTURE_2D => {
                    image_type = b"image2D\0" as *const u8 as *const ::core::ffi::c_char;
                }
                WINED3D_SHADER_RESOURCE_TEXTURE_3D => {
                    image_type = b"image3D\0" as *const u8 as *const ::core::ffi::c_char;
                }
                WINED3D_SHADER_RESOURCE_TEXTURE_1DARRAY => {
                    image_type = b"image1DArray\0" as *const u8 as *const ::core::ffi::c_char;
                }
                WINED3D_SHADER_RESOURCE_TEXTURE_2DARRAY => {
                    image_type = b"image2DArray\0" as *const u8 as *const ::core::ffi::c_char;
                }
                _ => {
                    image_type = b"unsupported_image\0" as *const u8 as *const ::core::ffi::c_char;
                }
            }

            if shader_glsl_use_layout_binding_qualifier(gl_info) != 0 {
                shader_addline(
                    buffer,
                    b"layout(binding = %u)\n\0" as *const u8 as *const ::core::ffi::c_char,
                    i,
                );
            }
            if (*reg_maps).uav_read_mask() & (1 as ::core::ffi::c_uint) << i != 0 {
                shader_addline(
                    buffer,
                    b"layout(%s) uniform %s%s %s_image%u;\n\0" as *const u8
                        as *const ::core::ffi::c_char,
                    read_format,
                    image_type_prefix,
                    image_type,
                    prefix,
                    i,
                );
            } else {
                shader_addline(
                    buffer,
                    b"writeonly uniform %s%s %s_image%u;\n\0" as *const u8
                        as *const ::core::ffi::c_char,
                    image_type_prefix,
                    image_type,
                    prefix,
                    i,
                );
            }

            if (*reg_maps).uav_counter_mask() & (1 as ::core::ffi::c_uint) << i != 0 {
                shader_addline(
                    buffer,
                    b"layout(binding = %u) uniform atomic_uint %s_counter%u;\n\0" as *const u8
                        as *const ::core::ffi::c_char,
                    i,
                    prefix,
                    i,
                );
            }
        }
        i = i.wrapping_add(1);
    }

    /* Declare address variables */
    map = (*reg_maps).address as uint32_t;
    while map != 0 {
        i = wined3d_bit_scan(core::ptr::addr_of_mut!(map)) as ::core::ffi::c_uint;
        shader_addline(
            buffer,
            b"ivec4 A%u;\n\0" as *const u8 as *const ::core::ffi::c_char,
            i,
        );
    }

    /* Declare output register temporaries */
    if (*(*shader).limits).packed_output != 0 {
        shader_addline(
            buffer,
            b"vec4 %s_out[%u];\n\0" as *const u8 as *const ::core::ffi::c_char,
            prefix,
            (*(*shader).limits).packed_output,
        );
    }

    /* Declare temporary variables */
    if (*reg_maps).temporary_count != 0 {
        i = 0 as ::core::ffi::c_uint;
        while i < (*reg_maps).temporary_count {
            shader_addline(
                buffer,
                b"vec4 R%u;\n\0" as *const u8 as *const ::core::ffi::c_char,
                i,
            );
            i = i.wrapping_add(1);
        }
    } else if ((*version).major as ::core::ffi::c_int) < (4 as ::core::ffi::c_int) {
        map = (*reg_maps).temporary as uint32_t;
        while map != 0 {
            i = wined3d_bit_scan(core::ptr::addr_of_mut!(map)) as ::core::ffi::c_uint;
            shader_addline(
                buffer,
                b"vec4 R%u;\n\0" as *const u8 as *const ::core::ffi::c_char,
                i,
            );
        }
    }

    /* Declare indexable temporary variables */
    idx_temp_reg = ((*reg_maps).indexable_temps.next as *mut ::core::ffi::c_char).offset(
        -(core::mem::offset_of!(wined3d_shader_indexable_temp, entry) as isize),
    ) as *mut wined3d_shader_indexable_temp;
    while core::ptr::addr_of!((*idx_temp_reg).entry)
        != core::ptr::addr_of!((*reg_maps).indexable_temps)
    {
        if (*idx_temp_reg).component_count != 4 as ::core::ffi::c_uint {
            FIXME!(
                "Ignoring component count %u.\n",
                (*idx_temp_reg).component_count
            );
        }
        shader_addline(
            buffer,
            b"vec4 X%u[%u];\n\0" as *const u8 as *const ::core::ffi::c_char,
            (*idx_temp_reg).register_idx,
            (*idx_temp_reg).register_size,
        );
        idx_temp_reg = ((*idx_temp_reg).entry.next as *mut ::core::ffi::c_char).offset(
            -(core::mem::offset_of!(wined3d_shader_indexable_temp, entry) as isize),
        ) as *mut wined3d_shader_indexable_temp;
    }

    /* Declare loop registers aLx */
    if ((*version).major as ::core::ffi::c_int) < (4 as ::core::ffi::c_int) {
        i = 0 as ::core::ffi::c_uint;
        while i < (*reg_maps).loop_depth {
            shader_addline(
                buffer,
                b"int aL%u;\n\0" as *const u8 as *const ::core::ffi::c_char,
                i,
            );
            shader_addline(
                buffer,
                b"int tmpInt%u;\n\0" as *const u8 as *const ::core::ffi::c_char,
                i,
            );
            i = i.wrapping_add(1);
        }
    }

    /* Temporary variables for matrix operations */
    shader_addline(
        buffer,
        b"vec4 tmp0;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"vec4 tmp1;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    if (*gl_info).supported[ARB_GPU_SHADER5 as usize] != 0 {
        shader_addline(
            buffer,
            b"precise vec4 tmp_precise[2];\n\0" as *const u8 as *const ::core::ffi::c_char,
        );
    } else {
        shader_addline(
            buffer,
            b"/* precise */ vec4 tmp_precise[2];\n\0" as *const u8 as *const ::core::ffi::c_char,
        );
    }

    if !(*shader).load_local_constsF {
        lconst = ((*shader).constantsF.next as *mut ::core::ffi::c_char).offset(
            -(core::mem::offset_of!(wined3d_shader_lconst, entry) as isize),
        ) as *mut wined3d_shader_lconst;
        while core::ptr::addr_of!((*lconst).entry) != core::ptr::addr_of!((*shader).constantsF) {
            shader_addline(
                buffer,
                b"const vec4 %s_lc%u = \0" as *const u8 as *const ::core::ffi::c_char,
                prefix,
                (*lconst).idx,
            );
            shader_glsl_append_imm_vec(
                buffer,
                core::ptr::addr_of!((*lconst).value) as *const ::core::ffi::c_uint
                    as *const ::core::ffi::c_float,
                ARRAY_SIZE!((*core::ptr::addr_of!((*lconst).value))) as ::core::ffi::c_uint,
                gl_info,
            );
            shader_addline(buffer, b";\n\0" as *const u8 as *const ::core::ffi::c_char);
            lconst = ((*lconst).entry.next as *mut ::core::ffi::c_char).offset(
                -(core::mem::offset_of!(wined3d_shader_lconst, entry) as isize),
            ) as *mut wined3d_shader_lconst;
        }
    }
}

unsafe extern "C" fn shader_glsl_gen_modifier(
    mut src_modifier: wined3d_shader_src_modifier,
    mut in_reg: *const ::core::ffi::c_char,
    mut in_regswizzle: *const ::core::ffi::c_char,
    mut out_str: *mut ::core::ffi::c_char,
) {
    match src_modifier as ::core::ffi::c_uint {
        WINED3DSPSM_DZ | WINED3DSPSM_DW | WINED3DSPSM_NONE => {
            sprintf(
                out_str,
                b"%s%s\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
            );
        }
        WINED3DSPSM_NEG => {
            sprintf(
                out_str,
                b"-%s%s\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
            );
        }
        WINED3DSPSM_NOT => {
            sprintf(
                out_str,
                b"!%s%s\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
            );
        }
        WINED3DSPSM_BIAS => {
            sprintf(
                out_str,
                b"(%s%s - vec4(0.5)%s)\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
                in_regswizzle,
            );
        }
        WINED3DSPSM_BIASNEG => {
            sprintf(
                out_str,
                b"-(%s%s - vec4(0.5)%s)\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
                in_regswizzle,
            );
        }
        WINED3DSPSM_SIGN => {
            sprintf(
                out_str,
                b"(2.0 * (%s%s - 0.5))\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
            );
        }
        WINED3DSPSM_SIGNNEG => {
            sprintf(
                out_str,
                b"-(2.0 * (%s%s - 0.5))\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
            );
        }
        WINED3DSPSM_COMP => {
            sprintf(
                out_str,
                b"(1.0 - %s%s)\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
            );
        }
        WINED3DSPSM_X2 => {
            sprintf(
                out_str,
                b"(2.0 * %s%s)\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
            );
        }
        WINED3DSPSM_X2NEG => {
            sprintf(
                out_str,
                b"-(2.0 * %s%s)\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
            );
        }
        WINED3DSPSM_ABS => {
            sprintf(
                out_str,
                b"abs(%s%s)\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
            );
        }
        WINED3DSPSM_ABSNEG => {
            sprintf(
                out_str,
                b"-abs(%s%s)\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
            );
        }
        _ => {
            FIXME!(
                "Unhandled modifier %u\n",
                src_modifier as ::core::ffi::c_uint
            );
            sprintf(
                out_str,
                b"%s%s\0".as_ptr() as *const ::core::ffi::c_char,
                in_reg,
                in_regswizzle,
            );
        }
    }
}

unsafe extern "C" fn shader_glsl_fixup_scalar_register_variable(
    mut register_name: *mut wined3d_string_buffer,
    mut glsl_variable: *const ::core::ffi::c_char,
    mut gl_info: *const wined3d_gl_info,
) {
    if (*gl_info).supported[ARB_SHADING_LANGUAGE_420PACK as usize] != 0 {
        string_buffer_sprintf(
            register_name,
            b"%s\0" as *const u8 as *const ::core::ffi::c_char,
            glsl_variable,
        );
    } else {
        string_buffer_sprintf(
            register_name,
            b"ivec2(%s, 0)\0" as *const u8 as *const ::core::ffi::c_char,
            glsl_variable,
        );
    };
}

unsafe extern "C" fn shader_glsl_get_register_name(
    reg: *const wined3d_shader_register,
    data_type: wined3d_data_type,
    register_name: *mut wined3d_string_buffer,
    is_swizzled: *mut BOOL,
    ctx: *const wined3d_shader_context,
) {
    /* oPos, oFog and oPts in D3D */
    static mut hwrastout_reg_names: [*const core::ffi::c_char; 3] = [
        b"vs_out[10]\0".as_ptr() as *const core::ffi::c_char,
        b"vs_out[11].x\0".as_ptr() as *const core::ffi::c_char,
        b"vs_out[11].y\0".as_ptr() as *const core::ffi::c_char,
    ];

    let shader: *const wined3d_shader = (*ctx).shader;
    let reg_maps: *const wined3d_shader_reg_maps = (*ctx).reg_maps;
    let version: *const wined3d_shader_version = core::ptr::addr_of!((*reg_maps).shader_version);
    let priv_0: *const shader_glsl_ctx_priv = (*ctx).backend_data as *const shader_glsl_ctx_priv;
    let prefix: *const core::ffi::c_char = shader_glsl_get_prefix((*version).type_);
    let gl_info: *const wined3d_gl_info = (*priv_0).gl_info;
    let mut rel_param0: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mut rel_param1: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };

    if (*reg).idx[0 as usize].offset != !0
        && !(*reg).idx[0 as usize].rel_addr.is_null()
    {
        shader_glsl_add_src_param_ext(
            ctx,
            (*reg).idx[0 as usize].rel_addr as *const wined3d_shader_src_param,
            WINED3DSP_WRITEMASK_0,
            core::ptr::addr_of_mut!(rel_param0),
            (*(*reg).idx[0 as usize].rel_addr).reg.data_type,
        );
    }
    if (*reg).idx[1 as usize].offset != !0
        && !(*reg).idx[1 as usize].rel_addr.is_null()
    {
        shader_glsl_add_src_param_ext(
            ctx,
            (*reg).idx[1 as usize].rel_addr as *const wined3d_shader_src_param,
            WINED3DSP_WRITEMASK_0,
            core::ptr::addr_of_mut!(rel_param1),
            (*(*reg).idx[1 as usize].rel_addr).reg.data_type,
        );
    }
    if !is_swizzled.is_null() {
        *is_swizzled = (FALSE as i32);
    }

    match (*reg).type_ as u32 {
        WINED3DSPR_TEMP => {
            string_buffer_sprintf(
                register_name,
                b"R%u\0".as_ptr() as *const core::ffi::c_char,
                (*reg).idx[0 as usize].offset,
            );
        }

        WINED3DSPR_INPUT | WINED3DSPR_INCONTROLPOINT => {
            if (*version).type_ as u32 == WINED3D_SHADER_TYPE_VERTEX {
                if !(*reg).idx[0 as usize].rel_addr.is_null() {
                    FIXME!("VS3 input registers relative addressing.\n");
                }
                if !is_swizzled.is_null()
                    && ((*(*priv_0).cur_vs_args).swizzle_map as u32
                        & (1
                            << (*reg).idx[0 as usize].offset))
                        != 0
                {
                    *is_swizzled = (TRUE as i32);
                }
                if !(*reg).idx[0 as usize].rel_addr.is_null() {
                    string_buffer_sprintf(
                        register_name,
                        b"%s_in[%s + %u]\0".as_ptr() as *const core::ffi::c_char,
                        prefix,
                        core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                        (*reg).idx[0 as usize].offset,
                    );
                } else {
                    string_buffer_sprintf(
                        register_name,
                        b"%s_in%u\0".as_ptr() as *const core::ffi::c_char,
                        prefix,
                        (*reg).idx[0 as usize].offset,
                    );
                }
            } else if (*version).type_ as u32 == WINED3D_SHADER_TYPE_HULL
                || (*version).type_ as u32 == WINED3D_SHADER_TYPE_DOMAIN
                || (*version).type_ as u32 == WINED3D_SHADER_TYPE_GEOMETRY
            {
                if !(*reg).idx[0 as usize].rel_addr.is_null() {
                    if !(*reg).idx[1 as usize].rel_addr.is_null() {
                        string_buffer_sprintf(
                            register_name,
                            b"shader_in[%s + %u].reg[%s + %u]\0".as_ptr() as *const core::ffi::c_char,
                            core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                            (*reg).idx[0 as usize].offset,
                            core::ptr::addr_of_mut!(rel_param1.param_str) as *mut core::ffi::c_char,
                            (*reg).idx[1 as usize].offset,
                        );
                    } else {
                        string_buffer_sprintf(
                            register_name,
                            b"shader_in[%s + %u].reg[%u]\0".as_ptr() as *const core::ffi::c_char,
                            core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                            (*reg).idx[0 as usize].offset,
                            (*reg).idx[1 as usize].offset,
                        );
                    }
                } else if !(*reg).idx[1 as usize].rel_addr.is_null() {
                    string_buffer_sprintf(
                        register_name,
                        b"shader_in[%u].reg[%s + %u]\0".as_ptr() as *const core::ffi::c_char,
                        (*reg).idx[0 as usize].offset,
                        core::ptr::addr_of_mut!(rel_param1.param_str) as *mut core::ffi::c_char,
                        (*reg).idx[1 as usize].offset,
                    );
                } else {
                    string_buffer_sprintf(
                        register_name,
                        b"shader_in[%u].reg[%u]\0".as_ptr() as *const core::ffi::c_char,
                        (*reg).idx[0 as usize].offset,
                        (*reg).idx[1 as usize].offset,
                    );
                }
            } else if (*version).major >= 3 {
                /* pixel shaders >= 3.0 */
                let idx: u32 = (*shader).u.ps.input_reg_map
                    [(*reg).idx[0 as usize].offset as usize];
                let in_count: u32 = vec4_varyings((*version).major as DWORD, gl_info);

                if !(*reg).idx[0 as usize].rel_addr.is_null() {
                    /* Removing a + 0 would be an obvious optimization, but
                     * OS X doesn't see the NOP operation there. */
                    if idx != 0 {
                        if needs_legacy_glsl_syntax(gl_info) != 0
                            && (*shader).u.ps.declared_in_count > in_count
                        {
                            string_buffer_sprintf(
                                register_name,
                                b"((%s + %u) > %u ? (%s + %u) > %u ? gl_SecondaryColor : gl_Color : %s_in[%s + %u])\0"
                                    .as_ptr() as *const core::ffi::c_char,
                                core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                                idx,
                                in_count.wrapping_sub(1),
                                core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                                idx,
                                in_count,
                                prefix,
                                core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                                idx,
                            );
                        } else {
                            string_buffer_sprintf(
                                register_name,
                                b"%s_in[%s + %u]\0".as_ptr() as *const core::ffi::c_char,
                                prefix,
                                core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                                idx,
                            );
                        }
                    } else {
                        if needs_legacy_glsl_syntax(gl_info) != 0
                            && (*shader).u.ps.declared_in_count > in_count
                        {
                            string_buffer_sprintf(
                                register_name,
                                b"((%s) > %u ? (%s) > %u ? gl_SecondaryColor : gl_Color : %s_in[%s])\0"
                                    .as_ptr() as *const core::ffi::c_char,
                                core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                                in_count.wrapping_sub(1),
                                core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                                in_count,
                                prefix,
                                core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                            );
                        } else {
                            string_buffer_sprintf(
                                register_name,
                                b"%s_in[%s]\0".as_ptr() as *const core::ffi::c_char,
                                prefix,
                                core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                            );
                        }
                    }
                } else {
                    if idx == in_count {
                        string_buffer_sprintf(
                            register_name,
                            b"gl_Color\0".as_ptr() as *const core::ffi::c_char,
                        );
                    } else if idx == in_count.wrapping_add(1) {
                        string_buffer_sprintf(
                            register_name,
                            b"gl_SecondaryColor\0".as_ptr() as *const core::ffi::c_char,
                        );
                    } else {
                        string_buffer_sprintf(
                            register_name,
                            b"%s_in[%u]\0".as_ptr() as *const core::ffi::c_char,
                            prefix,
                            idx,
                        );
                    }
                }
            } else {
                if (*reg).idx[0 as usize].offset == 0 {
                    string_buffer_sprintf(
                        register_name,
                        b"ffp_varying_diffuse\0".as_ptr() as *const core::ffi::c_char,
                    );
                } else {
                    string_buffer_sprintf(
                        register_name,
                        b"ffp_varying_specular\0".as_ptr() as *const core::ffi::c_char,
                    );
                }
            }
        }

        WINED3DSPR_CONST => {
            /* Relative addressing */
            if !(*reg).idx[0 as usize].rel_addr.is_null() {
                if wined3d_settings.check_float_constants {
                    string_buffer_sprintf(
                        register_name,
                        b"(%s + %u >= 0 && %s + %u < %u ? %s_c[%s + %u] : vec4(0.0))\0".as_ptr()
                            as *const core::ffi::c_char,
                        core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                        (*reg).idx[0 as usize].offset,
                        core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                        (*reg).idx[0 as usize].offset,
                        (*(*shader).limits).constant_float,
                        prefix,
                        core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                        (*reg).idx[0 as usize].offset,
                    );
                } else if (*reg).idx[0 as usize].offset != 0 {
                    string_buffer_sprintf(
                        register_name,
                        b"%s_c[%s + %u]\0".as_ptr() as *const core::ffi::c_char,
                        prefix,
                        core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                        (*reg).idx[0 as usize].offset,
                    );
                } else {
                    string_buffer_sprintf(
                        register_name,
                        b"%s_c[%s]\0".as_ptr() as *const core::ffi::c_char,
                        prefix,
                        core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                    );
                }
            } else {
                if shader_constant_is_local(shader, (*reg).idx[0 as usize].offset as DWORD) != 0 {
                    string_buffer_sprintf(
                        register_name,
                        b"%s_lc%u\0".as_ptr() as *const core::ffi::c_char,
                        prefix,
                        (*reg).idx[0 as usize].offset,
                    );
                } else {
                    string_buffer_sprintf(
                        register_name,
                        b"%s_c[%u]\0".as_ptr() as *const core::ffi::c_char,
                        prefix,
                        (*reg).idx[0 as usize].offset,
                    );
                }
            }
        }

        WINED3DSPR_CONSTINT => {
            string_buffer_sprintf(
                register_name,
                b"%s_i[%u]\0".as_ptr() as *const core::ffi::c_char,
                prefix,
                (*reg).idx[0 as usize].offset,
            );
        }

        WINED3DSPR_CONSTBOOL => {
            string_buffer_sprintf(
                register_name,
                b"%s_b[%u]\0".as_ptr() as *const core::ffi::c_char,
                prefix,
                (*reg).idx[0 as usize].offset,
            );
        }

        WINED3DSPR_TEXTURE => {
            /* case WINED3DSPR_ADDR: */
            if (*version).type_ as u32 == WINED3D_SHADER_TYPE_PIXEL {
                string_buffer_sprintf(
                    register_name,
                    b"T%u\0".as_ptr() as *const core::ffi::c_char,
                    (*reg).idx[0 as usize].offset,
                );
            } else {
                string_buffer_sprintf(
                    register_name,
                    b"A%u\0".as_ptr() as *const core::ffi::c_char,
                    (*reg).idx[0 as usize].offset,
                );
            }
        }

        WINED3DSPR_LOOP => {
            string_buffer_sprintf(
                register_name,
                b"aL%u\0".as_ptr() as *const core::ffi::c_char,
                (*(*ctx).state).current_loop_reg.wrapping_sub(1),
            );
        }

        WINED3DSPR_SAMPLER => {
            string_buffer_sprintf(
                register_name,
                b"%s_sampler%u\0".as_ptr() as *const core::ffi::c_char,
                prefix,
                (*reg).idx[0 as usize].offset,
            );
        }

        WINED3DSPR_COLOROUT => {
            if (*reg).idx[0 as usize].offset >= (*gl_info).limits.buffers {
                WARN!(
                    "Write to render target %u, only %d supported.\n",
                    (*reg).idx[0 as usize].offset,
                    (*gl_info).limits.buffers
                );
            }

            string_buffer_sprintf(
                register_name,
                b"%s[%u]\0".as_ptr() as *const core::ffi::c_char,
                get_fragment_output(gl_info),
                (*reg).idx[0 as usize].offset,
            );
        }

        WINED3DSPR_RASTOUT => {
            string_buffer_sprintf(
                register_name,
                b"%s\0".as_ptr() as *const core::ffi::c_char,
                hwrastout_reg_names[(*reg).idx[0 as usize].offset as usize],
            );
        }

        WINED3DSPR_DEPTHOUT | WINED3DSPR_DEPTHOUTGE | WINED3DSPR_DEPTHOUTLE => {
            string_buffer_sprintf(
                register_name,
                b"gl_FragDepth\0".as_ptr() as *const core::ffi::c_char,
            );
        }

        WINED3DSPR_ATTROUT => {
            if (*reg).idx[0 as usize].offset == 0 {
                string_buffer_sprintf(
                    register_name,
                    b"%s_out[8]\0".as_ptr() as *const core::ffi::c_char,
                    prefix,
                );
            } else {
                string_buffer_sprintf(
                    register_name,
                    b"%s_out[9]\0".as_ptr() as *const core::ffi::c_char,
                    prefix,
                );
            }
        }

        WINED3DSPR_TEXCRDOUT => {
            /* Vertex shaders >= 3.0: WINED3DSPR_OUTPUT */
            if !(*reg).idx[0 as usize].rel_addr.is_null() {
                string_buffer_sprintf(
                    register_name,
                    b"%s_out[%s + %u]\0".as_ptr() as *const core::ffi::c_char,
                    prefix,
                    core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                    (*reg).idx[0 as usize].offset,
                );
            } else {
                string_buffer_sprintf(
                    register_name,
                    b"%s_out[%u]\0".as_ptr() as *const core::ffi::c_char,
                    prefix,
                    (*reg).idx[0 as usize].offset,
                );
            }
        }

        WINED3DSPR_MISCTYPE => {
            if (*reg).idx[0 as usize].offset == 0 {
                /* vPos */
                string_buffer_sprintf(
                    register_name,
                    b"vpos\0".as_ptr() as *const core::ffi::c_char,
                );
            } else if (*reg).idx[0 as usize].offset == 1 {
                /* Note that gl_FrontFacing is a bool, while vFace is
                 * a float for which the sign determines front/back */
                string_buffer_sprintf(
                    register_name,
                    b"(gl_FrontFacing ? 1.0 : -1.0)\0".as_ptr() as *const core::ffi::c_char,
                );
            } else {
                FIXME!(
                    "Unhandled misctype register %u.\n",
                    (*reg).idx[0 as usize].offset
                );
                string_buffer_sprintf(
                    register_name,
                    b"unrecognized_register\0".as_ptr() as *const core::ffi::c_char,
                );
            }
        }

        WINED3DSPR_IMMCONST => match (*reg).immconst_type as u32 {
            WINED3D_IMMCONST_SCALAR => match data_type as u32 {
                WINED3D_DATA_UNORM | WINED3D_DATA_SNORM | WINED3D_DATA_FLOAT => {
                    string_buffer_clear(register_name);
                    shader_glsl_append_imm_vec(
                        register_name,
                        core::ptr::addr_of!((*reg).u.immconst_data) as *const f32,
                        1,
                        gl_info,
                    );
                }
                WINED3D_DATA_INT => {
                    string_buffer_sprintf(
                        register_name,
                        b"%#x\0".as_ptr() as *const core::ffi::c_char,
                        (*reg).u.immconst_data[0 as usize],
                    );
                }
                WINED3D_DATA_RESOURCE | WINED3D_DATA_SAMPLER | WINED3D_DATA_UINT => {
                    string_buffer_sprintf(
                        register_name,
                        b"%#xu\0".as_ptr() as *const core::ffi::c_char,
                        (*reg).u.immconst_data[0 as usize],
                    );
                }
                _ => {
                    string_buffer_sprintf(
                        register_name,
                        b"<unhandled data type %#x>\0".as_ptr() as *const core::ffi::c_char,
                        data_type as u32,
                    );
                }
            },

            WINED3D_IMMCONST_VEC4 => match data_type as u32 {
                WINED3D_DATA_UNORM | WINED3D_DATA_SNORM | WINED3D_DATA_FLOAT => {
                    string_buffer_clear(register_name);
                    shader_glsl_append_imm_vec(
                        register_name,
                        core::ptr::addr_of!((*reg).u.immconst_data) as *const f32,
                        4,
                        gl_info,
                    );
                }
                WINED3D_DATA_INT => {
                    string_buffer_sprintf(
                        register_name,
                        b"ivec4(%#x, %#x, %#x, %#x)\0".as_ptr() as *const core::ffi::c_char,
                        (*reg).u.immconst_data[0 as usize],
                        (*reg).u.immconst_data[1 as usize],
                        (*reg).u.immconst_data[2 as usize],
                        (*reg).u.immconst_data[3 as usize],
                    );
                }
                WINED3D_DATA_RESOURCE | WINED3D_DATA_SAMPLER | WINED3D_DATA_UINT => {
                    string_buffer_sprintf(
                        register_name,
                        b"uvec4(%#xu, %#xu, %#xu, %#xu)\0".as_ptr() as *const core::ffi::c_char,
                        (*reg).u.immconst_data[0 as usize],
                        (*reg).u.immconst_data[1 as usize],
                        (*reg).u.immconst_data[2 as usize],
                        (*reg).u.immconst_data[3 as usize],
                    );
                }
                _ => {
                    string_buffer_sprintf(
                        register_name,
                        b"<unhandled data type %#x>\0".as_ptr() as *const core::ffi::c_char,
                        data_type as u32,
                    );
                }
            },

            _ => {
                FIXME!(
                    "Unhandled immconst type %#x\n",
                    (*reg).immconst_type as u32
                );
                string_buffer_sprintf(
                    register_name,
                    b"<unhandled_immconst_type %#x>\0".as_ptr() as *const core::ffi::c_char,
                    (*reg).immconst_type as u32,
                );
            }
        },

        WINED3DSPR_CONSTBUFFER => {
            if !(*reg).idx[1 as usize].rel_addr.is_null() {
                string_buffer_sprintf(
                    register_name,
                    b"%s_cb%u[%s + %u]\0".as_ptr() as *const core::ffi::c_char,
                    prefix,
                    (*reg).idx[0 as usize].offset,
                    core::ptr::addr_of_mut!(rel_param1.param_str) as *mut core::ffi::c_char,
                    (*reg).idx[1 as usize].offset,
                );
            } else {
                string_buffer_sprintf(
                    register_name,
                    b"%s_cb%u[%u]\0".as_ptr() as *const core::ffi::c_char,
                    prefix,
                    (*reg).idx[0 as usize].offset,
                    (*reg).idx[1 as usize].offset,
                );
            }
        }

        WINED3DSPR_IMMCONSTBUFFER => {
            if !(*reg).idx[0 as usize].rel_addr.is_null() {
                string_buffer_sprintf(
                    register_name,
                    b"%s_icb[%s + %u]\0".as_ptr() as *const core::ffi::c_char,
                    prefix,
                    core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                    (*reg).idx[0 as usize].offset,
                );
            } else {
                string_buffer_sprintf(
                    register_name,
                    b"%s_icb[%u]\0".as_ptr() as *const core::ffi::c_char,
                    prefix,
                    (*reg).idx[0 as usize].offset,
                );
            }
        }

        WINED3DSPR_PRIMID => {
            if (*version).type_ as u32 == WINED3D_SHADER_TYPE_GEOMETRY {
                string_buffer_sprintf(
                    register_name,
                    b"gl_PrimitiveIDIn\0".as_ptr() as *const core::ffi::c_char,
                );
            } else {
                string_buffer_sprintf(
                    register_name,
                    b"gl_PrimitiveID\0".as_ptr() as *const core::ffi::c_char,
                );
            }
        }

        WINED3DSPR_IDXTEMP => {
            if !(*reg).idx[1 as usize].rel_addr.is_null() {
                string_buffer_sprintf(
                    register_name,
                    b"X%u[%s + %u]\0".as_ptr() as *const core::ffi::c_char,
                    (*reg).idx[0 as usize].offset,
                    core::ptr::addr_of_mut!(rel_param1.param_str) as *mut core::ffi::c_char,
                    (*reg).idx[1 as usize].offset,
                );
            } else {
                string_buffer_sprintf(
                    register_name,
                    b"X%u[%u]\0".as_ptr() as *const core::ffi::c_char,
                    (*reg).idx[0 as usize].offset,
                    (*reg).idx[1 as usize].offset,
                );
            }
        }

        WINED3DSPR_LOCALTHREADINDEX => {
            shader_glsl_fixup_scalar_register_variable(
                register_name,
                b"int(gl_LocalInvocationIndex)\0".as_ptr() as *const core::ffi::c_char,
                gl_info,
            );
        }

        WINED3DSPR_GSINSTID | WINED3DSPR_OUTPOINTID => {
            shader_glsl_fixup_scalar_register_variable(
                register_name,
                b"gl_InvocationID\0".as_ptr() as *const core::ffi::c_char,
                gl_info,
            );
        }

        WINED3DSPR_THREADID => {
            string_buffer_sprintf(
                register_name,
                b"ivec3(gl_GlobalInvocationID)\0".as_ptr() as *const core::ffi::c_char,
            );
        }

        WINED3DSPR_THREADGROUPID => {
            string_buffer_sprintf(
                register_name,
                b"ivec3(gl_WorkGroupID)\0".as_ptr() as *const core::ffi::c_char,
            );
        }

        WINED3DSPR_LOCALTHREADID => {
            string_buffer_sprintf(
                register_name,
                b"ivec3(gl_LocalInvocationID)\0".as_ptr() as *const core::ffi::c_char,
            );
        }

        WINED3DSPR_FORKINSTID | WINED3DSPR_JOININSTID => {
            shader_glsl_fixup_scalar_register_variable(
                register_name,
                b"phase_instance_id\0".as_ptr() as *const core::ffi::c_char,
                gl_info,
            );
        }

        WINED3DSPR_TESSCOORD => {
            string_buffer_sprintf(
                register_name,
                b"gl_TessCoord\0".as_ptr() as *const core::ffi::c_char,
            );
        }

        WINED3DSPR_OUTCONTROLPOINT => {
            if !(*reg).idx[0 as usize].rel_addr.is_null() {
                if !(*reg).idx[1 as usize].rel_addr.is_null() {
                    string_buffer_sprintf(
                        register_name,
                        b"shader_out[%s + %u].reg[%s + %u]\0".as_ptr() as *const core::ffi::c_char,
                        core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                        (*reg).idx[0 as usize].offset,
                        core::ptr::addr_of_mut!(rel_param1.param_str) as *mut core::ffi::c_char,
                        (*reg).idx[1 as usize].offset,
                    );
                } else {
                    string_buffer_sprintf(
                        register_name,
                        b"shader_out[%s + %u].reg[%u]\0".as_ptr() as *const core::ffi::c_char,
                        core::ptr::addr_of_mut!(rel_param0.param_str) as *mut core::ffi::c_char,
                        (*reg).idx[0 as usize].offset,
                        (*reg).idx[1 as usize].offset,
                    );
                }
            } else if !(*reg).idx[1 as usize].rel_addr.is_null() {
                string_buffer_sprintf(
                    register_name,
                    b"shader_out[%u].reg[%s + %u]\0".as_ptr() as *const core::ffi::c_char,
                    (*reg).idx[0 as usize].offset,
                    core::ptr::addr_of_mut!(rel_param1.param_str) as *mut core::ffi::c_char,
                    (*reg).idx[1 as usize].offset,
                );
            } else {
                string_buffer_sprintf(
                    register_name,
                    b"shader_out[%u].reg[%u]\0".as_ptr() as *const core::ffi::c_char,
                    (*reg).idx[0 as usize].offset,
                    (*reg).idx[1 as usize].offset,
                );
            }
        }

        WINED3DSPR_PATCHCONST => {
            if (*version).type_ as u32 == WINED3D_SHADER_TYPE_HULL {
                string_buffer_sprintf(
                    register_name,
                    b"hs_out[%u]\0".as_ptr() as *const core::ffi::c_char,
                    (*reg).idx[0 as usize].offset,
                );
            } else {
                string_buffer_sprintf(
                    register_name,
                    b"vpc[%u]\0".as_ptr() as *const core::ffi::c_char,
                    (*reg).idx[0 as usize].offset,
                );
            }
        }

        WINED3DSPR_COVERAGE => {
            string_buffer_sprintf(
                register_name,
                b"gl_SampleMaskIn[0]\0".as_ptr() as *const core::ffi::c_char,
            );
        }

        WINED3DSPR_SAMPLEMASK => {
            string_buffer_sprintf(
                register_name,
                b"sample_mask\0".as_ptr() as *const core::ffi::c_char,
            );
        }

        WINED3DSPR_STENCILREF => {
            string_buffer_sprintf(
                register_name,
                b"stencil_ref\0".as_ptr() as *const core::ffi::c_char,
            );
        }

        _ => {
            FIXME!("Unhandled register type %#x.\n", (*reg).type_ as u32);
            string_buffer_sprintf(
                register_name,
                b"unrecognised_register\0".as_ptr() as *const core::ffi::c_char,
            );
        }
    }
}

unsafe extern "C" fn shader_glsl_write_mask_to_str(write_mask: DWORD, mut str: *mut core::ffi::c_char) {
    let fresh24 = str;
    str = str.offset(1);
    *fresh24 = b'.' as core::ffi::c_char;
    if (write_mask & WINED3DSP_WRITEMASK_0) != 0 {
        let fresh25 = str;
        str = str.offset(1);
        *fresh25 = b'x' as core::ffi::c_char;
    }
    if (write_mask & WINED3DSP_WRITEMASK_1) != 0 {
        let fresh26 = str;
        str = str.offset(1);
        *fresh26 = b'y' as core::ffi::c_char;
    }
    if (write_mask & WINED3DSP_WRITEMASK_2) != 0 {
        let fresh27 = str;
        str = str.offset(1);
        *fresh27 = b'z' as core::ffi::c_char;
    }
    if (write_mask & WINED3DSP_WRITEMASK_3) != 0 {
        let fresh28 = str;
        str = str.offset(1);
        *fresh28 = b'w' as core::ffi::c_char;
    }
    *str = 0 as core::ffi::c_char;
}

unsafe extern "C" fn shader_glsl_get_write_mask(param: *const wined3d_shader_dst_param, write_mask: *mut ::core::ffi::c_char) -> DWORD {
    let mut mask: DWORD = (*param).write_mask as DWORD;

    if shader_is_scalar(core::ptr::addr_of!((*param).reg)) != 0 {
        mask = WINED3DSP_WRITEMASK_0 as DWORD;
        *write_mask = b'\0' as ::core::ffi::c_char;
    } else {
        shader_glsl_write_mask_to_str(mask, write_mask);
    }

    return mask;
}

unsafe extern "C" fn shader_glsl_get_write_mask_size(write_mask: DWORD) -> u32 {
    let mut size: u32 = 0;

    if write_mask & WINED3DSP_WRITEMASK_0 != 0 { size += 1; }
    if write_mask & WINED3DSP_WRITEMASK_1 != 0 { size += 1; }
    if write_mask & WINED3DSP_WRITEMASK_2 != 0 { size += 1; }
    if write_mask & WINED3DSP_WRITEMASK_3 != 0 { size += 1; }

    return size;
}

unsafe extern "C" fn shader_glsl_swizzle_get_component(swizzle: DWORD, component_idx: ::core::ffi::c_uint) -> ::core::ffi::c_uint {
    return (swizzle >> (2 * component_idx)) & 0x3;
}

unsafe extern "C" fn shader_glsl_swizzle_to_str(swizzle: DWORD, fixup: BOOL, mask: DWORD, mut str: *mut core::ffi::c_char) {
    let swizzle_chars: *const core::ffi::c_char = if fixup != 0 {
        b"zyxw\0".as_ptr() as *const core::ffi::c_char
    } else {
        b"xyzw\0".as_ptr() as *const core::ffi::c_char
    };
    let mut i: core::ffi::c_uint = 0;
    let fresh39 = str;
    str = str.offset(1);
    *fresh39 = b'.' as core::ffi::c_char;
    while i < 4 {
        if (mask as core::ffi::c_uint) & (WINED3DSP_WRITEMASK_0 << i) != 0 {
            let fresh40 = str;
            str = str.offset(1);
            *fresh40 = *swizzle_chars.offset(shader_glsl_swizzle_get_component(swizzle, i) as isize);
        }
        i = i.wrapping_add(1);
    }
    *str = b'\0' as core::ffi::c_char;
}

unsafe extern "C" fn shader_glsl_get_swizzle(
    param: *const wined3d_shader_src_param,
    fixup: BOOL,
    mask: DWORD,
    swizzle_str: *mut ::core::ffi::c_char,
) {
    if shader_is_scalar(core::ptr::addr_of!((*param).reg)) != 0 {
        *swizzle_str = b'\0' as ::core::ffi::c_char;
    } else {
        shader_glsl_swizzle_to_str((*param).swizzle, fixup, mask, swizzle_str);
    }
}

unsafe extern "C" fn shader_glsl_sprintf_cast(
    mut dst_param: *mut wined3d_string_buffer,
    mut src_param: *const ::core::ffi::c_char,
    mut dst_data_type: wined3d_data_type,
    mut src_data_type: wined3d_data_type,
    mut size: ::core::ffi::c_uint,
) {
    if dst_data_type as ::core::ffi::c_uint == WINED3D_DATA_UNORM as ::core::ffi::c_uint
        || dst_data_type as ::core::ffi::c_uint == WINED3D_DATA_SNORM as ::core::ffi::c_uint
    {
        dst_data_type = WINED3D_DATA_FLOAT;
    }
    if src_data_type as ::core::ffi::c_uint == WINED3D_DATA_UNORM as ::core::ffi::c_uint
        || src_data_type as ::core::ffi::c_uint == WINED3D_DATA_SNORM as ::core::ffi::c_uint
    {
        src_data_type = WINED3D_DATA_FLOAT;
    }
    if dst_data_type as ::core::ffi::c_uint == src_data_type as ::core::ffi::c_uint {
        string_buffer_sprintf(
            dst_param,
            b"%s\0" as *const u8 as *const ::core::ffi::c_char,
            src_param,
        );
        return;
    }
    if src_data_type as ::core::ffi::c_uint == WINED3D_DATA_FLOAT as ::core::ffi::c_uint {
        match dst_data_type as ::core::ffi::c_uint {
            WINED3D_DATA_INT => {
                string_buffer_sprintf(
                    dst_param,
                    b"floatBitsToInt(%s)\0" as *const u8 as *const ::core::ffi::c_char,
                    src_param,
                );
                return;
            }
            WINED3D_DATA_RESOURCE | WINED3D_DATA_SAMPLER | WINED3D_DATA_UINT => {
                string_buffer_sprintf(
                    dst_param,
                    b"floatBitsToUint(%s)\0" as *const u8 as *const ::core::ffi::c_char,
                    src_param,
                );
                return;
            }
            _ => {}
        }
    }
    if src_data_type as ::core::ffi::c_uint == WINED3D_DATA_UINT as ::core::ffi::c_uint
        && dst_data_type as ::core::ffi::c_uint == WINED3D_DATA_FLOAT as ::core::ffi::c_uint
    {
        string_buffer_sprintf(
            dst_param,
            b"uintBitsToFloat(%s)\0" as *const u8 as *const ::core::ffi::c_char,
            src_param,
        );
        return;
    }
    if src_data_type as ::core::ffi::c_uint == WINED3D_DATA_INT as ::core::ffi::c_uint {
        match dst_data_type as ::core::ffi::c_uint {
            WINED3D_DATA_FLOAT => {
                string_buffer_sprintf(
                    dst_param,
                    b"intBitsToFloat(%s)\0" as *const u8 as *const ::core::ffi::c_char,
                    src_param,
                );
                return;
            }
            WINED3D_DATA_UINT => {
                if size == 1 as ::core::ffi::c_uint {
                    string_buffer_sprintf(
                        dst_param,
                        b"uint(%s)\0" as *const u8 as *const ::core::ffi::c_char,
                        src_param,
                    );
                } else {
                    string_buffer_sprintf(
                        dst_param,
                        b"uvec%u(%s)\0" as *const u8 as *const ::core::ffi::c_char,
                        size,
                        src_param,
                    );
                }
                return;
            }
            _ => {}
        }
    }
    WINE_FIXME!("Unhandled cast from %#x to %#x.\n", src_data_type as ::core::ffi::c_uint, dst_data_type as ::core::ffi::c_uint);
    string_buffer_sprintf(
        dst_param,
        b"%s\0" as *const u8 as *const ::core::ffi::c_char,
        src_param,
    );
}

unsafe extern "C" fn shader_glsl_add_src_param_ext(
    ctx: *const wined3d_shader_context,
    wined3d_src: *const wined3d_shader_src_param,
    mask: DWORD,
    glsl_src: *mut glsl_src_param,
    data_type: wined3d_data_type,
) {
    let priv_: *mut shader_glsl_ctx_priv = (*ctx).backend_data as *mut shader_glsl_ctx_priv;
    let param_str: *mut wined3d_string_buffer = string_buffer_get((*priv_).string_buffers);
    let reg_name: *mut wined3d_string_buffer = string_buffer_get((*priv_).string_buffers);
    let mut param_data_type: wined3d_data_type = WINED3D_DATA_FLOAT;
    let mut is_color: BOOL = (FALSE as i32);
    let mut swizzle_str: [core::ffi::c_char; 6] = [0; 6];
    let mut size: core::ffi::c_uint = 0;

    (*glsl_src).param_str[0 as usize] = '\0' as i32 as core::ffi::c_char;
    swizzle_str[0 as usize] = '\0' as i32 as core::ffi::c_char;

    shader_glsl_get_register_name(
        &raw const (*wined3d_src).reg,
        data_type,
        reg_name,
        &raw mut is_color,
        ctx,
    );
    shader_glsl_get_swizzle(
        wined3d_src,
        is_color,
        mask,
        &raw mut swizzle_str as *mut core::ffi::c_char,
    );

    match (*wined3d_src).reg.type_ as core::ffi::c_uint {
        WINED3DSPR_IMMCONST => {
            param_data_type = data_type;
            size = (if (*wined3d_src).reg.immconst_type as core::ffi::c_uint
                == WINED3D_IMMCONST_SCALAR as core::ffi::c_uint
            {
                1
            } else {
                4
            }) as core::ffi::c_uint;
        }
        WINED3DSPR_FORKINSTID | WINED3DSPR_GSINSTID | WINED3DSPR_JOININSTID
        | WINED3DSPR_LOCALTHREADINDEX | WINED3DSPR_OUTPOINTID | WINED3DSPR_PRIMID => {
            param_data_type = WINED3D_DATA_INT;
            size = 1;
        }
        WINED3DSPR_LOCALTHREADID | WINED3DSPR_THREADGROUPID | WINED3DSPR_THREADID => {
            param_data_type = WINED3D_DATA_INT;
            size = 3;
        }
        _ => {
            param_data_type = WINED3D_DATA_FLOAT;
            size = 4;
        }
    }

    shader_glsl_sprintf_cast(
        param_str,
        (*reg_name).buffer,
        data_type,
        param_data_type,
        size,
    );
    shader_glsl_gen_modifier(
        (*wined3d_src).modifiers,
        (*param_str).buffer,
        &raw mut swizzle_str as *mut core::ffi::c_char,
        &raw mut (*glsl_src).param_str as *mut core::ffi::c_char,
    );

    string_buffer_release((*priv_).string_buffers, reg_name);
    string_buffer_release((*priv_).string_buffers, param_str);
}

unsafe extern "C" fn shader_glsl_add_src_param(
    ins: *const wined3d_shader_instruction,
    wined3d_src: *const wined3d_shader_src_param,
    mask: DWORD,
    glsl_src: *mut glsl_src_param,
) {
    shader_glsl_add_src_param_ext(
        (*ins).ctx,
        wined3d_src,
        mask,
        glsl_src,
        (*wined3d_src).reg.data_type,
    );
}

unsafe extern "C" fn shader_glsl_add_dst_param(
    ins: *const wined3d_shader_instruction,
    wined3d_dst: *const wined3d_shader_dst_param,
    glsl_dst: *mut glsl_dst_param,
) -> DWORD {
    let priv_: *mut shader_glsl_ctx_priv = (*(*ins).ctx).backend_data as *mut shader_glsl_ctx_priv;
    let mut reg_name: *mut wined3d_string_buffer = core::ptr::null_mut::<wined3d_string_buffer>();
    let mut len: size_t = 0;

    (*glsl_dst).mask_str[0 as usize] = b'\0' as c_char;

    reg_name = string_buffer_get((*priv_).string_buffers);
    shader_glsl_get_register_name(
        &raw const (*wined3d_dst).reg,
        (*wined3d_dst).reg.data_type,
        reg_name,
        core::ptr::null_mut::<BOOL>(),
        (*ins).ctx,
    );
    len = min!(
        (*reg_name).content_size as usize,
        (ARRAY_SIZE!((*glsl_dst).reg_name) - (1 as usize) as u32) as _,
    ) as size_t;
    memcpy(
        &raw mut (*glsl_dst).reg_name as *mut c_char as *mut c_void,
        (*reg_name).buffer as *const c_void,
        len,
    );
    (*glsl_dst).reg_name[len as usize] = b'\0' as c_char;
    string_buffer_release((*priv_).string_buffers, reg_name);

    return shader_glsl_get_write_mask(
        wined3d_dst,
        &raw mut (*glsl_dst).mask_str as *mut c_char,
    );
}

unsafe extern "C" fn shader_glsl_append_dst_ext(
    buffer: *mut wined3d_string_buffer,
    ins: *const wined3d_shader_instruction,
    dst: *const wined3d_shader_dst_param,
    dst_idx: ::core::ffi::c_uint,
    data_type: wined3d_data_type,
) -> DWORD {
    let mut glsl_dst: glsl_dst_param = glsl_dst_param {
        reg_name: [0; 150],
        mask_str: [0; 6],
    };
    let mut mask: DWORD = 0;
    mask = shader_glsl_add_dst_param(ins, dst, core::ptr::addr_of_mut!(glsl_dst));
    if mask != 0 {
        if ((*ins).flags & WINED3DSI_PRECISE_XYZW) != 0 {
            sprintf(
                core::ptr::addr_of_mut!(glsl_dst.reg_name) as *mut ::core::ffi::c_char,
                b"tmp_precise[%u]\0" as *const u8 as *const ::core::ffi::c_char,
                dst_idx,
            );
        }
        match data_type as ::core::ffi::c_uint {
            WINED3D_DATA_FLOAT | WINED3D_DATA_UNORM | WINED3D_DATA_SNORM => {
                shader_addline(
                    buffer,
                    b"%s%s = %s(\0" as *const u8 as *const ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(glsl_dst.reg_name) as *mut ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(glsl_dst.mask_str) as *mut ::core::ffi::c_char,
                    shift_glsl_tab[(*dst).shift as usize],
                );
            }
            WINED3D_DATA_INT => {
                shader_addline(
                    buffer,
                    b"%s%s = %sintBitsToFloat(\0" as *const u8 as *const ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(glsl_dst.reg_name) as *mut ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(glsl_dst.mask_str) as *mut ::core::ffi::c_char,
                    shift_glsl_tab[(*dst).shift as usize],
                );
            }
            WINED3D_DATA_RESOURCE | WINED3D_DATA_SAMPLER | WINED3D_DATA_UINT => {
                shader_addline(
                    buffer,
                    b"%s%s = %suintBitsToFloat(\0" as *const u8 as *const ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(glsl_dst.reg_name) as *mut ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(glsl_dst.mask_str) as *mut ::core::ffi::c_char,
                    shift_glsl_tab[(*dst).shift as usize],
                );
            }
            _ => {
                FIXME!("Unhandled data type %#x.\n", data_type);
                shader_addline(
                    buffer,
                    b"%s%s = %s(\0" as *const u8 as *const ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(glsl_dst.reg_name) as *mut ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(glsl_dst.mask_str) as *mut ::core::ffi::c_char,
                    shift_glsl_tab[(*dst).shift as usize],
                );
            }
        }
    }
    return mask;
}

unsafe extern "C" fn shader_glsl_append_dst(buffer: *mut wined3d_string_buffer, ins: *const wined3d_shader_instruction) -> DWORD {
    return shader_glsl_append_dst_ext(buffer, ins, (*ins).dst.add(0 as usize) as *const wined3d_shader_dst_param, 0 as core::ffi::c_uint, (*(*ins).dst.add(0 as usize)).reg.data_type);
}

unsafe extern "C" fn shader_glsl_add_instruction_modifiers(ins: *const wined3d_shader_instruction) {
    let mut dst: *const wined3d_shader_dst_param = core::ptr::null::<wined3d_shader_dst_param>();
    let mut dst_param: glsl_dst_param = glsl_dst_param {
        reg_name: [0; 150],
        mask_str: [0; 6],
    };
    let mut modifiers: DWORD = 0;
    let mut i: ::core::ffi::c_uint = 0 as ::core::ffi::c_uint;
    while i < (*ins).dst_count {
        'body: {
            dst = (*ins).dst.offset(i as isize) as *const wined3d_shader_dst_param;
            if (*dst).reg.type_ as ::core::ffi::c_uint
                == WINED3DSPR_NULL as ::core::ffi::c_uint
            {
                break 'body;
            }

            if ((*ins).flags & (WINED3DSI_PRECISE_XYZW as DWORD)) != 0 {
                shader_glsl_add_dst_param(ins, dst, core::ptr::addr_of_mut!(dst_param));
                shader_addline(
                    (*(*ins).ctx).buffer,
                    b"%s%s = tmp_precise[%u]%s;\n\0".as_ptr() as *const ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(dst_param.reg_name) as *mut ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(dst_param.mask_str) as *mut ::core::ffi::c_char,
                    i,
                    core::ptr::addr_of_mut!(dst_param.mask_str) as *mut ::core::ffi::c_char,
                );
            }

            modifiers = (*dst).modifiers as DWORD;
            if modifiers == 0 {
                break 'body;
            }

            shader_glsl_add_dst_param(ins, dst, core::ptr::addr_of_mut!(dst_param));

            if (modifiers & (WINED3DSPDM_SATURATE as DWORD)) != 0 {
                /* _SAT means to clamp the value of the register to between 0 and 1 */
                shader_addline(
                    (*(*ins).ctx).buffer,
                    b"%s%s = clamp(%s%s, 0.0, 1.0);\n\0".as_ptr() as *const ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(dst_param.reg_name) as *mut ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(dst_param.mask_str) as *mut ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(dst_param.reg_name) as *mut ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(dst_param.mask_str) as *mut ::core::ffi::c_char,
                );
            }

            if (modifiers & (WINED3DSPDM_MSAMPCENTROID as DWORD)) != 0 {
            }

            if (modifiers & (WINED3DSPDM_PARTIALPRECISION as DWORD)) != 0 {
                /* MSDN says this modifier can be safely ignored, so that's what we'll do. */
            }
        }
        i = i.wrapping_add(1);
    }
}

unsafe extern "C" fn shader_glsl_get_rel_op(op: wined3d_shader_rel_op) -> *const ::core::ffi::c_char {
    match op as ::core::ffi::c_uint {
        WINED3D_SHADER_REL_OP_GT => return b">\0" as *const u8 as *const ::core::ffi::c_char,
        WINED3D_SHADER_REL_OP_EQ => return b"==\0" as *const u8 as *const ::core::ffi::c_char,
        WINED3D_SHADER_REL_OP_GE => return b">=\0" as *const u8 as *const ::core::ffi::c_char,
        WINED3D_SHADER_REL_OP_LT => return b"<\0" as *const u8 as *const ::core::ffi::c_char,
        WINED3D_SHADER_REL_OP_NE => return b"!=\0" as *const u8 as *const ::core::ffi::c_char,
        WINED3D_SHADER_REL_OP_LE => return b"<=\0" as *const u8 as *const ::core::ffi::c_char,
        _ => {
            FIXME!("Unrecognized operator %#x.\n", op as ::core::ffi::c_uint);
            return b"(??)\0" as *const u8 as *const ::core::ffi::c_char;
        }
    }
}

unsafe extern "C" fn shader_glsl_has_core_grad(gl_info: *const wined3d_gl_info) -> BOOL {
    return (shader_glsl_get_version(gl_info) >= 130 as ::core::ffi::c_uint
        || (*gl_info).supported[EXT_GPU_SHADER4 as usize] != 0) as BOOL;
}

unsafe extern "C" fn shader_glsl_get_coord_size(
    mut resource_type: wined3d_shader_resource_type,
    mut coord_size: *mut ::core::ffi::c_uint,
    mut deriv_size: *mut ::core::ffi::c_uint,
) {
    let is_array: BOOL = (resource_type as ::core::ffi::c_uint == WINED3D_SHADER_RESOURCE_TEXTURE_1DARRAY
        || resource_type as ::core::ffi::c_uint == WINED3D_SHADER_RESOURCE_TEXTURE_2DARRAY)
        as ::core::ffi::c_int;
    *coord_size = resource_type_info[resource_type as usize].coord_size;
    *deriv_size = *coord_size;
    if is_array != 0 {
        *deriv_size = (*deriv_size).wrapping_sub(1);
    }
}

unsafe extern "C" fn shader_glsl_get_sample_function(
    mut ctx: *const wined3d_shader_context,
    mut resource_idx: DWORD,
    mut sampler_idx: DWORD,
    mut flags: uint32_t,
    mut sample_function: *mut glsl_sample_function,
) {
    let mut resource_type: wined3d_shader_resource_type = WINED3D_SHADER_RESOURCE_NONE;
    let mut priv_0: *mut shader_glsl_ctx_priv = (*ctx).backend_data as *mut shader_glsl_ctx_priv;
    let mut gl_info: *const wined3d_gl_info = (*priv_0).gl_info;
    let mut shadow: BOOL = shader_sampler_is_shadow(
        (*ctx).shader,
        (*priv_0).cur_ps_args,
        resource_idx as ::core::ffi::c_uint,
        sampler_idx as ::core::ffi::c_uint,
    );
    let mut projected: BOOL = ((flags & (WINED3D_GLSL_SAMPLE_PROJECTED as uint32_t)) != 0) as BOOL;
    let mut lod: BOOL = ((flags & (WINED3D_GLSL_SAMPLE_LOD as uint32_t)) != 0) as BOOL;
    let mut grad: BOOL = ((flags & (WINED3D_GLSL_SAMPLE_GRAD as uint32_t)) != 0) as BOOL;
    let mut offset: BOOL = ((flags & (WINED3D_GLSL_SAMPLE_OFFSET as uint32_t)) != 0) as BOOL;
    let mut base: *const ::core::ffi::c_char =
        b"texture\0".as_ptr() as *const ::core::ffi::c_char;
    let mut type_part: *const ::core::ffi::c_char =
        b"\0".as_ptr() as *const ::core::ffi::c_char;
    let mut suffix: *const ::core::ffi::c_char = b"\0".as_ptr() as *const ::core::ffi::c_char;
    let mut coord_size: ::core::ffi::c_uint = 0;
    let mut deriv_size: ::core::ffi::c_uint = 0;

    resource_type = (if (*(*ctx).reg_maps).shader_version.type_ as ::core::ffi::c_uint
        == WINED3D_SHADER_TYPE_PIXEL as ::core::ffi::c_uint
    {
        pixelshader_get_resource_type(
            (*ctx).reg_maps,
            resource_idx as ::core::ffi::c_uint,
            (*(*priv_0).cur_ps_args).tex_types,
        ) as ::core::ffi::c_uint
    } else {
        (*(*ctx).reg_maps).resource_info[resource_idx as usize].type_ as ::core::ffi::c_uint
    }) as wined3d_shader_resource_type;

    (*sample_function).data_type =
        (*(*ctx).reg_maps).resource_info[resource_idx as usize].data_type;

    if resource_type as usize >= ARRAY_SIZE!(resource_type_info) as usize {
        ERR!("Unexpected resource type %#x.\n", resource_type as ::core::ffi::c_uint);
        resource_type = WINED3D_SHADER_RESOURCE_TEXTURE_2D;
    }

    /* Note that there's no such thing as a projected cube texture. */
    if resource_type as ::core::ffi::c_uint == WINED3D_SHADER_RESOURCE_TEXTURE_CUBE as ::core::ffi::c_uint {
        projected = (FALSE as i32);
    }

    if needs_legacy_glsl_syntax(gl_info) != 0 {
        if shadow != 0 {
            base = b"shadow\0".as_ptr() as *const ::core::ffi::c_char;
        }

        type_part = resource_type_info[resource_type as usize].type_part;
        if *type_part.offset(0 as isize) == 0
            && resource_type as ::core::ffi::c_uint
                != WINED3D_SHADER_RESOURCE_TEXTURE_CUBEARRAY as ::core::ffi::c_uint
        {
            FIXME!("Unhandled resource type %#x.\n", resource_type as ::core::ffi::c_uint);
        }

        if lod == 0 && grad != 0 && shader_glsl_has_core_grad(gl_info) == 0 {
            if (*gl_info).supported[ARB_SHADER_TEXTURE_LOD as usize] != 0 {
                suffix = b"ARB\0".as_ptr() as *const ::core::ffi::c_char;
            } else {
                FIXME!("Unsupported grad function.\n");
            }
        }
    }

    if (flags & (WINED3D_GLSL_SAMPLE_LOAD as uint32_t)) != 0 {
        static texel_fetch_flags: uint32_t =
            (WINED3D_GLSL_SAMPLE_LOAD | WINED3D_GLSL_SAMPLE_OFFSET) as uint32_t;
        if (flags & !texel_fetch_flags) != 0 {
            ERR!(
                "Unexpected flags %#x for texelFetch.\n",
                (flags & !texel_fetch_flags) as ::core::ffi::c_uint
            );
        }

        base = b"texelFetch\0".as_ptr() as *const ::core::ffi::c_char;
        type_part = b"\0".as_ptr() as *const ::core::ffi::c_char;
    }

    (*sample_function).name = string_buffer_get((*priv_0).string_buffers);
    string_buffer_sprintf(
        (*sample_function).name,
        b"%s%s%s%s%s%s\0".as_ptr() as *const ::core::ffi::c_char,
        base,
        type_part,
        if projected != 0 {
            b"Proj\0".as_ptr() as *const ::core::ffi::c_char
        } else {
            b"\0".as_ptr() as *const ::core::ffi::c_char
        },
        if lod != 0 {
            b"Lod\0".as_ptr() as *const ::core::ffi::c_char
        } else if grad != 0 {
            b"Grad\0".as_ptr() as *const ::core::ffi::c_char
        } else {
            b"\0".as_ptr() as *const ::core::ffi::c_char
        },
        if offset != 0 {
            b"Offset\0".as_ptr() as *const ::core::ffi::c_char
        } else {
            b"\0".as_ptr() as *const ::core::ffi::c_char
        },
        suffix,
    );

    shader_glsl_get_coord_size(resource_type, &raw mut coord_size, &raw mut deriv_size);
    if shadow != 0 {
        coord_size = coord_size.wrapping_add(1);
    }
    (*sample_function).offset_size = if offset != 0 {
        deriv_size
    } else {
        0 as ::core::ffi::c_uint
    };
    (*sample_function).coord_mask = wined3d_mask_from_size(coord_size) as ::core::ffi::c_uint;
    (*sample_function).deriv_mask = wined3d_mask_from_size(deriv_size) as ::core::ffi::c_uint;
    (*sample_function).output_single_component =
        (shadow != 0 && needs_legacy_glsl_syntax(gl_info) == 0) as ::core::ffi::c_int as BOOL;
}

unsafe extern "C" fn shader_glsl_release_sample_function(
    ctx: *const wined3d_shader_context,
    sample_function: *mut glsl_sample_function,
) {
    let priv_0: *const shader_glsl_ctx_priv = (*ctx).backend_data as *const shader_glsl_ctx_priv;
    string_buffer_release((*priv_0).string_buffers, (*sample_function).name);
}

unsafe extern "C" fn shader_glsl_append_fixup_arg(
    mut arguments: *mut ::core::ffi::c_char,
    mut reg_name: *const ::core::ffi::c_char,
    mut sign_fixup: BOOL,
    mut channel_source: fixup_channel_source,
) {
    match channel_source as ::core::ffi::c_uint {
        CHANNEL_SOURCE_ZERO => {
            strcat(
                arguments,
                b"0.0\0" as *const u8 as *const ::core::ffi::c_char,
            );
        }
        CHANNEL_SOURCE_ONE => {
            strcat(
                arguments,
                b"1.0\0" as *const u8 as *const ::core::ffi::c_char,
            );
        }
        CHANNEL_SOURCE_X => {
            strcat(arguments, reg_name);
            strcat(
                arguments,
                b".x\0" as *const u8 as *const ::core::ffi::c_char,
            );
        }
        CHANNEL_SOURCE_Y => {
            strcat(arguments, reg_name);
            strcat(
                arguments,
                b".y\0" as *const u8 as *const ::core::ffi::c_char,
            );
        }
        CHANNEL_SOURCE_Z => {
            strcat(arguments, reg_name);
            strcat(
                arguments,
                b".z\0" as *const u8 as *const ::core::ffi::c_char,
            );
        }
        CHANNEL_SOURCE_W => {
            strcat(arguments, reg_name);
            strcat(
                arguments,
                b".w\0" as *const u8 as *const ::core::ffi::c_char,
            );
        }
        _ => {
            FIXME!("Unhandled channel source %#x\n", channel_source);
            strcat(
                arguments,
                b"undefined\0" as *const u8 as *const ::core::ffi::c_char,
            );
        }
    }

    if sign_fixup != 0 {
        strcat(
            arguments,
            b" * 2.0 - 1.0\0" as *const u8 as *const ::core::ffi::c_char,
        );
    }
}

unsafe extern "C" fn shader_glsl_color_correction_ext(
    buffer: *mut wined3d_string_buffer,
    reg_name: *const ::core::ffi::c_char,
    mut mask: DWORD,
    fixup: color_fixup_desc,
) {
    let mut mask_size: ::core::ffi::c_uint = 0;
    let mut remaining: ::core::ffi::c_uint = 0;
    let mut fixup_mask: DWORD = 0;
    let mut arguments: [::core::ffi::c_char; 256] = [0; 256];
    let mut mask_str: [::core::ffi::c_char; 6] = [0; 6];

    if fixup.x_sign_fixup() as ::core::ffi::c_int != 0
        || fixup.x_source() as ::core::ffi::c_int != CHANNEL_SOURCE_X as ::core::ffi::c_int
    {
        fixup_mask |= WINED3DSP_WRITEMASK_0;
    }
    if fixup.y_sign_fixup() as ::core::ffi::c_int != 0
        || fixup.y_source() as ::core::ffi::c_int != CHANNEL_SOURCE_Y as ::core::ffi::c_int
    {
        fixup_mask |= WINED3DSP_WRITEMASK_1;
    }
    if fixup.z_sign_fixup() as ::core::ffi::c_int != 0
        || fixup.z_source() as ::core::ffi::c_int != CHANNEL_SOURCE_Z as ::core::ffi::c_int
    {
        fixup_mask |= WINED3DSP_WRITEMASK_2;
    }
    if fixup.w_sign_fixup() as ::core::ffi::c_int != 0
        || fixup.w_source() as ::core::ffi::c_int != CHANNEL_SOURCE_W as ::core::ffi::c_int
    {
        fixup_mask |= WINED3DSP_WRITEMASK_3;
    }
    mask &= fixup_mask;
    if mask == 0 {
        return;
    }

    if is_complex_fixup(fixup) != 0 {
        let complex_fixup: complex_fixup = get_complex_fixup(fixup);
        FIXME!("Complex fixup (%#x) not supported\n", complex_fixup as ::core::ffi::c_uint);
        return;
    }

    shader_glsl_write_mask_to_str(
        mask,
        core::ptr::addr_of_mut!(mask_str) as *mut ::core::ffi::c_char,
    );
    mask_size = shader_glsl_get_write_mask_size(mask);

    arguments[0] = 0;
    remaining = mask_size;
    if mask as ::core::ffi::c_uint & WINED3DSP_WRITEMASK_0 != 0 {
        shader_glsl_append_fixup_arg(
            core::ptr::addr_of_mut!(arguments) as *mut ::core::ffi::c_char,
            reg_name,
            fixup.x_sign_fixup() as BOOL,
            fixup.x_source() as fixup_channel_source,
        );
        remaining = remaining.wrapping_sub(1);
        if remaining != 0 {
            strcat(
                core::ptr::addr_of_mut!(arguments) as *mut ::core::ffi::c_char,
                b", \0".as_ptr() as *const ::core::ffi::c_char,
            );
        }
    }
    if mask as ::core::ffi::c_uint & WINED3DSP_WRITEMASK_1 != 0 {
        shader_glsl_append_fixup_arg(
            core::ptr::addr_of_mut!(arguments) as *mut ::core::ffi::c_char,
            reg_name,
            fixup.y_sign_fixup() as BOOL,
            fixup.y_source() as fixup_channel_source,
        );
        remaining = remaining.wrapping_sub(1);
        if remaining != 0 {
            strcat(
                core::ptr::addr_of_mut!(arguments) as *mut ::core::ffi::c_char,
                b", \0".as_ptr() as *const ::core::ffi::c_char,
            );
        }
    }
    if mask as ::core::ffi::c_uint & WINED3DSP_WRITEMASK_2 != 0 {
        shader_glsl_append_fixup_arg(
            core::ptr::addr_of_mut!(arguments) as *mut ::core::ffi::c_char,
            reg_name,
            fixup.z_sign_fixup() as BOOL,
            fixup.z_source() as fixup_channel_source,
        );
        remaining = remaining.wrapping_sub(1);
        if remaining != 0 {
            strcat(
                core::ptr::addr_of_mut!(arguments) as *mut ::core::ffi::c_char,
                b", \0".as_ptr() as *const ::core::ffi::c_char,
            );
        }
    }
    if mask as ::core::ffi::c_uint & WINED3DSP_WRITEMASK_3 != 0 {
        shader_glsl_append_fixup_arg(
            core::ptr::addr_of_mut!(arguments) as *mut ::core::ffi::c_char,
            reg_name,
            fixup.w_sign_fixup() as BOOL,
            fixup.w_source() as fixup_channel_source,
        );
        remaining = remaining.wrapping_sub(1);
        if remaining != 0 {
            strcat(
                core::ptr::addr_of_mut!(arguments) as *mut ::core::ffi::c_char,
                b", \0".as_ptr() as *const ::core::ffi::c_char,
            );
        }
    }

    if mask_size > 1 as ::core::ffi::c_uint {
        shader_addline(
            buffer,
            b"%s%s = vec%u(%s);\n\0".as_ptr() as *const ::core::ffi::c_char,
            reg_name,
            core::ptr::addr_of_mut!(mask_str) as *mut ::core::ffi::c_char,
            mask_size,
            core::ptr::addr_of_mut!(arguments) as *mut ::core::ffi::c_char,
        );
    } else {
        shader_addline(
            buffer,
            b"%s%s = %s;\n\0".as_ptr() as *const ::core::ffi::c_char,
            reg_name,
            core::ptr::addr_of_mut!(mask_str) as *mut ::core::ffi::c_char,
            core::ptr::addr_of_mut!(arguments) as *mut ::core::ffi::c_char,
        );
    }
}

unsafe extern "C" fn shader_glsl_color_correction(ins: *const wined3d_shader_instruction, fixup: color_fixup_desc) {
    let priv_0: *mut shader_glsl_ctx_priv = (*(*ins).ctx).backend_data as *mut shader_glsl_ctx_priv;
    let mut reg_name: *mut wined3d_string_buffer = core::ptr::null_mut();
    reg_name = string_buffer_get((*priv_0).string_buffers);
    shader_glsl_get_register_name(
        core::ptr::addr_of!((*(*ins).dst.offset(0 as isize)).reg),
        (*(*ins).dst.offset(0 as isize)).reg.data_type,
        reg_name,
        core::ptr::null_mut::<BOOL>(),
        (*ins).ctx,
    );
    shader_glsl_color_correction_ext(
        (*(*ins).ctx).buffer,
        (*reg_name).buffer,
        (*(*ins).dst.offset(0 as isize)).write_mask as DWORD,
        fixup,
    );
    string_buffer_release((*priv_0).string_buffers, reg_name);
}

#[no_mangle]
unsafe extern "C" fn shader_glsl_gen_sample_code_v(
    mut ins: *const wined3d_shader_instruction,
    mut sampler_bind_idx: ::core::ffi::c_uint,
    mut sample_function: *const glsl_sample_function,
    mut swizzle: DWORD,
    mut dx: *const ::core::ffi::c_char,
    mut dy: *const ::core::ffi::c_char,
    mut bias: *const ::core::ffi::c_char,
    mut offset: *const wined3d_shader_texel_offset,
    mut coord_reg_fmt: *const ::core::ffi::c_char,
    ap_list: *mut ::core::ffi::c_void,
) {
    let mut args: va_list = *(ap_list as *mut va_list);
    let mut version: *const wined3d_shader_version =
        &raw const (*(*(*ins).ctx).reg_maps).shader_version;
    let mut dst_swizzle: [::core::ffi::c_char; 6] =
        [0 as ::core::ffi::c_char; 6];
    let mut fixup: color_fixup_desc = core::mem::zeroed();
    let mut args_0: va_list = *(ap_list as *mut va_list);
    let mut ret: ::core::ffi::c_int = 0;
    shader_glsl_swizzle_to_str(
        swizzle,
        (FALSE) as BOOL,
        (*(*ins).dst.offset(0 as ::core::ffi::c_int as isize)).write_mask as DWORD,
        &raw mut dst_swizzle as *mut ::core::ffi::c_char,
    );
    if (*version).type_ as ::core::ffi::c_uint
        == WINED3D_SHADER_TYPE_PIXEL as ::core::ffi::c_uint
        && ((*version).major as ::core::ffi::c_int) < 4 as ::core::ffi::c_int
    {
        let mut priv_0: *const shader_glsl_ctx_priv =
            (*(*ins).ctx).backend_data as *const shader_glsl_ctx_priv;
        fixup = (*(*priv_0).cur_ps_args).color_fixup[sampler_bind_idx as usize];
    } else {
        fixup = COLOR_FIXUP_IDENTITY;
    }
    shader_glsl_append_dst_ext(
        (*(*ins).ctx).buffer,
        ins,
        (*ins).dst.offset(0 as ::core::ffi::c_int as isize) as *const wined3d_shader_dst_param,
        0 as ::core::ffi::c_uint,
        (*sample_function).data_type,
    );
    if (*sample_function).output_single_component != 0 {
        shader_addline(
            (*(*ins).ctx).buffer,
            b"vec4(\0" as *const u8 as *const ::core::ffi::c_char,
        );
    }
    shader_addline(
        (*(*ins).ctx).buffer,
        b"%s(%s_sampler%u, \0" as *const u8 as *const ::core::ffi::c_char,
        (*(*sample_function).name).buffer,
        shader_glsl_get_prefix((*version).type_),
        sampler_bind_idx,
    );
    loop {


        ret = shader_vaddline(
            (*(*ins).ctx).buffer,
            coord_reg_fmt,
            args_0,
        );

        if ret == 0 {
            break;
        }
        if string_buffer_resize((*(*ins).ctx).buffer, ret) == 0 {
            break;
        }
    }
    if !dx.is_null() && !dy.is_null() {
        shader_addline(
            (*(*ins).ctx).buffer,
            b", %s, %s\0" as *const u8 as *const ::core::ffi::c_char,
            dx,
            dy,
        );
    } else if !bias.is_null() {
        shader_addline(
            (*(*ins).ctx).buffer,
            b", %s\0" as *const u8 as *const ::core::ffi::c_char,
            bias,
        );
    }
    if (*sample_function).offset_size != 0 {
        let mut offset_immdata: [::core::ffi::c_int; 4] = [
            (*offset).u as ::core::ffi::c_int,
            (*offset).v as ::core::ffi::c_int,
            (*offset).w as ::core::ffi::c_int,
            0,
        ];
        shader_addline(
            (*(*ins).ctx).buffer,
            b", \0" as *const u8 as *const ::core::ffi::c_char,
        );
        shader_glsl_append_imm_ivec(
            (*(*ins).ctx).buffer,
            &raw mut offset_immdata as *mut ::core::ffi::c_int,
            (*sample_function).offset_size,
        );
    }
    shader_addline(
        (*(*ins).ctx).buffer,
        b")\0" as *const u8 as *const ::core::ffi::c_char,
    );
    if (*sample_function).output_single_component != 0 {
        shader_addline(
            (*(*ins).ctx).buffer,
            b")\0" as *const u8 as *const ::core::ffi::c_char,
        );
    }
    shader_addline(
        (*(*ins).ctx).buffer,
        b"%s);\n\0" as *const u8 as *const ::core::ffi::c_char,
        &raw mut dst_swizzle as *mut ::core::ffi::c_char,
    );
    if is_identity_fixup(fixup) == 0 {
        shader_glsl_color_correction(ins, fixup);
    }
}



unsafe extern "C" fn shader_glsl_fixup_position(buffer: *mut wined3d_string_buffer, use_viewport_index: BOOL) {
    if use_viewport_index != 0 {
        shader_addline(
            buffer,
            b"gl_Position.y = gl_Position.y * pos_fixup[gl_ViewportIndex].y;\n\0".as_ptr() as *const i8,
        );
        shader_addline(
            buffer,
            b"gl_Position.xy += pos_fixup[gl_ViewportIndex].zw * gl_Position.ww;\n\0".as_ptr() as *const i8,
        );
    } else {
        shader_addline(
            buffer,
            b"gl_Position.y = gl_Position.y * pos_fixup.y;\n\0".as_ptr() as *const i8,
        );
        shader_addline(
            buffer,
            b"gl_Position.xy += pos_fixup.zw * gl_Position.ww;\n\0".as_ptr() as *const i8,
        );
    }
    shader_addline(
        buffer,
        b"gl_Position.z = gl_Position.z * 2.0 - gl_Position.w;\n\0".as_ptr() as *const i8,
    );
}

unsafe extern "C" fn shader_glsl_binop(ins: *const wined3d_shader_instruction) {
    let buffer: *mut wined3d_string_buffer = (*(*ins).ctx).buffer;
    let mut src0_param: glsl_src_param = core::mem::zeroed();
    let mut src1_param: glsl_src_param = core::mem::zeroed();
    let mut write_mask: DWORD = 0;
    let mut op: *const i8 = core::ptr::null();

    /* Determine the GLSL operator to use based on the opcode */
    match (*ins).handler_idx as u32 {
        WINED3DSIH_ADD => {
            op = b"+\0".as_ptr() as *const i8;
        }
        WINED3DSIH_AND => {
            op = b"&\0".as_ptr() as *const i8;
        }
        WINED3DSIH_DIV => {
            op = b"/\0".as_ptr() as *const i8;
        }
        WINED3DSIH_IADD => {
            op = b"+\0".as_ptr() as *const i8;
        }
        WINED3DSIH_ISHL => {
            op = b"<<\0".as_ptr() as *const i8;
        }
        WINED3DSIH_ISHR => {
            op = b">>\0".as_ptr() as *const i8;
        }
        WINED3DSIH_MUL => {
            op = b"*\0".as_ptr() as *const i8;
        }
        WINED3DSIH_OR => {
            op = b"|\0".as_ptr() as *const i8;
        }
        WINED3DSIH_SUB => {
            op = b"-\0".as_ptr() as *const i8;
        }
        WINED3DSIH_USHR => {
            op = b">>\0".as_ptr() as *const i8;
        }
        WINED3DSIH_XOR => {
            op = b"^\0".as_ptr() as *const i8;
        }
        _ => {
            op = b"<unhandled operator>\0".as_ptr() as *const i8;
            FIXME!(
                "Opcode %s not yet handled in GLSL.\n",
                debug_d3dshaderinstructionhandler((*ins).handler_idx)
            );
        }
    }

    write_mask = shader_glsl_append_dst(buffer, ins);
    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
        write_mask,
        core::ptr::addr_of_mut!(src0_param),
    );
    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(1 as isize) as *const wined3d_shader_src_param,
        write_mask,
        core::ptr::addr_of_mut!(src1_param),
    );
    shader_addline(
        buffer,
        b"%s %s %s);\n\0".as_ptr() as *const i8,
        core::ptr::addr_of_mut!(src0_param.param_str) as *mut i8,
        op,
        core::ptr::addr_of_mut!(src1_param.param_str) as *mut i8,
    );
}

unsafe extern "C" fn shader_glsl_relop(ins: *const wined3d_shader_instruction) {
    let buffer: *mut wined3d_string_buffer = (*(*ins).ctx).buffer;
    let mut src0_param: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mut src1_param: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mask_size: ::core::ffi::c_uint;
    let write_mask: DWORD;
    let mut op: *const ::core::ffi::c_char = core::ptr::null();

    write_mask = shader_glsl_append_dst(buffer, ins);
    mask_size = shader_glsl_get_write_mask_size(write_mask);
    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
        write_mask,
        core::ptr::addr_of_mut!(src0_param),
    );
    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(1 as isize) as *const wined3d_shader_src_param,
        write_mask,
        core::ptr::addr_of_mut!(src1_param),
    );

    if mask_size > 1 as ::core::ffi::c_uint {
        let h = (*ins).handler_idx as ::core::ffi::c_uint;
        if h == WINED3DSIH_EQ || h == WINED3DSIH_IEQ {
            op = b"equal\0".as_ptr() as *const ::core::ffi::c_char;
        } else if h == WINED3DSIH_GE
            || h == WINED3DSIH_IGE
            || h == WINED3DSIH_UGE
        {
            op = b"greaterThanEqual\0".as_ptr() as *const ::core::ffi::c_char;
        } else if h == WINED3DSIH_LT
            || h == WINED3DSIH_ILT
            || h == WINED3DSIH_ULT
        {
            op = b"lessThan\0".as_ptr() as *const ::core::ffi::c_char;
        } else if h == WINED3DSIH_NE || h == WINED3DSIH_INE {
            op = b"notEqual\0".as_ptr() as *const ::core::ffi::c_char;
        } else {
            op = b"<unhandled operator>\0".as_ptr() as *const ::core::ffi::c_char;
            ERR!("Unhandled opcode %#x.\n", (*ins).handler_idx);
        }

        shader_addline(
            buffer,
            b"uvec%u(%s(%s, %s)) * 0xffffffffu);\n\0".as_ptr() as *const ::core::ffi::c_char,
            mask_size,
            op,
            core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src1_param.param_str) as *mut ::core::ffi::c_char,
        );
    } else {
        let h = (*ins).handler_idx as ::core::ffi::c_uint;
        if h == WINED3DSIH_EQ || h == WINED3DSIH_IEQ {
            op = b"==\0".as_ptr() as *const ::core::ffi::c_char;
        } else if h == WINED3DSIH_GE
            || h == WINED3DSIH_IGE
            || h == WINED3DSIH_UGE
        {
            op = b">=\0".as_ptr() as *const ::core::ffi::c_char;
        } else if h == WINED3DSIH_LT
            || h == WINED3DSIH_ILT
            || h == WINED3DSIH_ULT
        {
            op = b"<\0".as_ptr() as *const ::core::ffi::c_char;
        } else if h == WINED3DSIH_NE || h == WINED3DSIH_INE {
            op = b"!=\0".as_ptr() as *const ::core::ffi::c_char;
        } else {
            op = b"<unhandled operator>\0".as_ptr() as *const ::core::ffi::c_char;
            ERR!("Unhandled opcode %#x.\n", (*ins).handler_idx);
        }

        shader_addline(
            buffer,
            b"%s %s %s ? 0xffffffffu : 0u);\n\0".as_ptr() as *const ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
            op,
            core::ptr::addr_of_mut!(src1_param.param_str) as *mut ::core::ffi::c_char,
        );
    }
}

unsafe extern "C" fn shader_glsl_unary_op(ins: *const wined3d_shader_instruction) {
    let mut src_param: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mut write_mask: DWORD = 0;
    let mut op: *const ::core::ffi::c_char = ::core::ptr::null::<::core::ffi::c_char>();
    match (*ins).handler_idx as u32 {
        WINED3DSIH_INEG => {
            op = b"-\0".as_ptr() as *const ::core::ffi::c_char;
        }
        WINED3DSIH_NOT => {
            op = b"~\0".as_ptr() as *const ::core::ffi::c_char;
        }
        _ => {
            op = b"<unhandled operator>\0".as_ptr() as *const ::core::ffi::c_char;
            ERR!(
                "Unhandled opcode %s.\n",
                debug_d3dshaderinstructionhandler((*ins).handler_idx)
            );
        }
    }
    write_mask = shader_glsl_append_dst((*(*ins).ctx).buffer, ins);
    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
        write_mask,
        core::ptr::addr_of_mut!(src_param),
    );
    shader_addline(
        (*(*ins).ctx).buffer,
        b"%s%s);\n\0".as_ptr() as *const ::core::ffi::c_char,
        op,
        core::ptr::addr_of_mut!(src_param.param_str) as *mut ::core::ffi::c_char,
    );
}

unsafe extern "C" fn shader_glsl_mul_extended(ins: *const wined3d_shader_instruction) {
    let mut buffer: *mut wined3d_string_buffer = (*(*ins).ctx).buffer;
    let mut src0_param: glsl_src_param = core::mem::zeroed();
    let mut src1_param: glsl_src_param = core::mem::zeroed();
    let mut write_mask: DWORD = 0;

    /* If we have ARB_gpu_shader5, we can use imulExtended() / umulExtended().
     * If not, we can emulate it. */
    if (*(*ins).dst.offset(0 as isize)).reg.type_
        as ::core::ffi::c_uint
        != WINED3DSPR_NULL as ::core::ffi::c_uint
    {
        FIXME!("64-bit integer multiplies not implemented.\n");
    }

    if (*(*ins).dst.offset(1 as isize)).reg.type_
        as ::core::ffi::c_uint
        != WINED3DSPR_NULL as ::core::ffi::c_uint
    {
        write_mask = shader_glsl_append_dst_ext(
            buffer,
            ins,
            (*ins).dst.offset(1 as isize) as *const wined3d_shader_dst_param,
            1 as ::core::ffi::c_uint,
            (*(*ins).dst.offset(1 as isize)).reg.data_type,
        );
        shader_glsl_add_src_param(
            ins,
            (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
            write_mask,
            core::ptr::addr_of_mut!(src0_param),
        );
        shader_glsl_add_src_param(
            ins,
            (*ins).src.offset(1 as isize) as *const wined3d_shader_src_param,
            write_mask,
            core::ptr::addr_of_mut!(src1_param),
        );

        shader_addline(
            (*(*ins).ctx).buffer,
            b"%s * %s);\n\0".as_ptr() as *const ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src1_param.param_str) as *mut ::core::ffi::c_char,
        );
    }
}

unsafe extern "C" fn shader_glsl_udiv(ins: *const wined3d_shader_instruction) {
    let mut buffer: *mut wined3d_string_buffer = (*(*ins).ctx).buffer;
    let mut src0_param: glsl_src_param = core::mem::zeroed();
    let mut src1_param: glsl_src_param = core::mem::zeroed();
    let mut write_mask: DWORD = 0;

    if (*(*ins).dst.offset(0 as isize)).reg.type_ as u32
        != WINED3DSPR_NULL as u32
    {
        if (*(*ins).dst.offset(1 as isize)).reg.type_ as u32
            != WINED3DSPR_NULL as u32
        {
            let mut dst_mask: [core::ffi::c_char; 6] =
                [0; 6];

            write_mask = shader_glsl_get_write_mask(
                (*ins).dst.offset(0 as isize) as *const wined3d_shader_dst_param,
                core::ptr::addr_of_mut!(dst_mask) as *mut core::ffi::c_char,
            );
            shader_glsl_add_src_param(
                ins,
                (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
                write_mask,
                core::ptr::addr_of_mut!(src0_param),
            );
            shader_glsl_add_src_param(
                ins,
                (*ins).src.offset(1 as isize) as *const wined3d_shader_src_param,
                write_mask,
                core::ptr::addr_of_mut!(src1_param),
            );
            shader_addline(
                buffer,
                b"tmp0%s = uintBitsToFloat(%s / %s);\n\0" as *const u8 as *const core::ffi::c_char,
                core::ptr::addr_of_mut!(dst_mask) as *mut core::ffi::c_char,
                core::ptr::addr_of_mut!(src0_param.param_str) as *mut core::ffi::c_char,
                core::ptr::addr_of_mut!(src1_param.param_str) as *mut core::ffi::c_char,
            );

            write_mask = shader_glsl_append_dst_ext(
                buffer,
                ins,
                (*ins).dst.offset(1 as isize) as *const wined3d_shader_dst_param,
                1 as u32,
                (*(*ins).dst.offset(1 as isize)).reg.data_type,
            );
            shader_glsl_add_src_param(
                ins,
                (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
                write_mask,
                core::ptr::addr_of_mut!(src0_param),
            );
            shader_glsl_add_src_param(
                ins,
                (*ins).src.offset(1 as isize) as *const wined3d_shader_src_param,
                write_mask,
                core::ptr::addr_of_mut!(src1_param),
            );
            shader_addline(
                buffer,
                b"%s %% %s);\n\0" as *const u8 as *const core::ffi::c_char,
                core::ptr::addr_of_mut!(src0_param.param_str) as *mut core::ffi::c_char,
                core::ptr::addr_of_mut!(src1_param.param_str) as *mut core::ffi::c_char,
            );

            shader_glsl_append_dst_ext(
                buffer,
                ins,
                (*ins).dst.offset(0 as isize) as *const wined3d_shader_dst_param,
                0 as u32,
                WINED3D_DATA_FLOAT,
            );
            shader_addline(
                buffer,
                b"tmp0%s);\n\0" as *const u8 as *const core::ffi::c_char,
                core::ptr::addr_of_mut!(dst_mask) as *mut core::ffi::c_char,
            );
        } else {
            write_mask = shader_glsl_append_dst_ext(
                buffer,
                ins,
                (*ins).dst.offset(0 as isize) as *const wined3d_shader_dst_param,
                0 as u32,
                (*(*ins).dst.offset(0 as isize)).reg.data_type,
            );
            shader_glsl_add_src_param(
                ins,
                (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
                write_mask,
                core::ptr::addr_of_mut!(src0_param),
            );
            shader_glsl_add_src_param(
                ins,
                (*ins).src.offset(1 as isize) as *const wined3d_shader_src_param,
                write_mask,
                core::ptr::addr_of_mut!(src1_param),
            );
            shader_addline(
                buffer,
                b"%s / %s);\n\0" as *const u8 as *const core::ffi::c_char,
                core::ptr::addr_of_mut!(src0_param.param_str) as *mut core::ffi::c_char,
                core::ptr::addr_of_mut!(src1_param.param_str) as *mut core::ffi::c_char,
            );
        }
    } else if (*(*ins).dst.offset(1 as isize)).reg.type_ as u32
        != WINED3DSPR_NULL as u32
    {
        write_mask = shader_glsl_append_dst_ext(
            buffer,
            ins,
            (*ins).dst.offset(1 as isize) as *const wined3d_shader_dst_param,
            1 as u32,
            (*(*ins).dst.offset(1 as isize)).reg.data_type,
        );
        shader_glsl_add_src_param(
            ins,
            (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
            write_mask,
            core::ptr::addr_of_mut!(src0_param),
        );
        shader_glsl_add_src_param(
            ins,
            (*ins).src.offset(1 as isize) as *const wined3d_shader_src_param,
            write_mask,
            core::ptr::addr_of_mut!(src1_param),
        );
        shader_addline(
            buffer,
            b"%s %% %s);\n\0" as *const u8 as *const core::ffi::c_char,
            core::ptr::addr_of_mut!(src0_param.param_str) as *mut core::ffi::c_char,
            core::ptr::addr_of_mut!(src1_param.param_str) as *mut core::ffi::c_char,
        );
    }
}

unsafe extern "C" fn shader_glsl_mov(ins: *const wined3d_shader_instruction) {
    let priv_: *const shader_glsl_ctx_priv =
        (*(*ins).ctx).backend_data as *const shader_glsl_ctx_priv;
    let buffer: *mut wined3d_string_buffer = (*(*ins).ctx).buffer;
    let gl_info: *const wined3d_gl_info = (*priv_).gl_info;
    let mut src0_param: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mut write_mask: DWORD = 0;

    write_mask = shader_glsl_append_dst(buffer, ins);
    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
        write_mask,
        core::ptr::addr_of_mut!(src0_param),
    );

    /* In vs_1_1 WINED3DSIO_MOV can write to the address register. In later
     * shader versions WINED3DSIO_MOVA is used for this. */
    if (*(*(*ins).ctx).reg_maps).shader_version.major as ::core::ffi::c_int
        == 1 as ::core::ffi::c_int
        && (*(*(*ins).ctx).reg_maps).shader_version.type_ as ::core::ffi::c_uint
            == WINED3D_SHADER_TYPE_VERTEX as ::core::ffi::c_uint
        && (*(*ins).dst.offset(0 as isize))
            .reg
            .type_ as ::core::ffi::c_uint
            == WINED3DSPR_ADDR as ::core::ffi::c_uint
    {
        /* This is a simple floor() */
        let mask_size: ::core::ffi::c_uint = shader_glsl_get_write_mask_size(write_mask);
        if mask_size > 1 as ::core::ffi::c_uint {
            shader_addline(
                buffer,
                b"ivec%d(floor(%s)));\n\0" as *const u8 as *const ::core::ffi::c_char,
                mask_size,
                core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
            );
        } else {
            shader_addline(
                buffer,
                b"int(floor(%s)));\n\0" as *const u8 as *const ::core::ffi::c_char,
                core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
            );
        }
    } else if (*ins).handler_idx as ::core::ffi::c_uint
        == WINED3DSIH_MOVA as ::core::ffi::c_uint
    {
        let mask_size: ::core::ffi::c_uint = shader_glsl_get_write_mask_size(write_mask);

        if shader_glsl_get_version(gl_info) >= 130 as ::core::ffi::c_uint
            || (*gl_info).supported[EXT_GPU_SHADER4 as usize] != 0
        {
            if mask_size > 1 as ::core::ffi::c_uint {
                shader_addline(
                    buffer,
                    b"ivec%d(round(%s)));\n\0" as *const u8 as *const ::core::ffi::c_char,
                    mask_size,
                    core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
                );
            } else {
                shader_addline(
                    buffer,
                    b"int(round(%s)));\n\0" as *const u8 as *const ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
                );
            }
        } else {
            if mask_size > 1 as ::core::ffi::c_uint {
                shader_addline(
                    buffer,
                    b"ivec%d(floor(abs(%s) + vec%d(0.5)) * sign(%s)));\n\0" as *const u8
                        as *const ::core::ffi::c_char,
                    mask_size,
                    core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
                    mask_size,
                    core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
                );
            } else {
                shader_addline(
                    buffer,
                    b"int(floor(abs(%s) + 0.5) * sign(%s)));\n\0" as *const u8
                        as *const ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
                    core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
                );
            }
        }
    } else {
        shader_addline(
            buffer,
            b"%s);\n\0" as *const u8 as *const ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
        );
    }
}
unsafe extern "C" fn shader_glsl_dot(ins: *const wined3d_shader_instruction) {
    let buffer: *mut wined3d_string_buffer = (*(*ins).ctx).buffer;
    let mut src0_param: glsl_src_param = core::mem::zeroed();
    let mut src1_param: glsl_src_param = core::mem::zeroed();
    let mut dst_write_mask: DWORD;
    let mut src_write_mask: DWORD;
    let mut dst_size: ::core::ffi::c_uint;

    dst_write_mask = shader_glsl_append_dst(buffer, ins);
    dst_size = shader_glsl_get_write_mask_size(dst_write_mask);

    /* dp4 works on vec4, dp3 on vec3, etc. */
    if (*ins).handler_idx as ::core::ffi::c_uint == WINED3DSIH_DP4 as ::core::ffi::c_uint {
        src_write_mask = WINED3DSP_WRITEMASK_ALL as DWORD;
    } else if (*ins).handler_idx as ::core::ffi::c_uint == WINED3DSIH_DP3 as ::core::ffi::c_uint {
        src_write_mask = (WINED3DSP_WRITEMASK_0 | WINED3DSP_WRITEMASK_1 | WINED3DSP_WRITEMASK_2) as DWORD;
    } else {
        src_write_mask = (WINED3DSP_WRITEMASK_0 | WINED3DSP_WRITEMASK_1) as DWORD;
    }

    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
        src_write_mask,
        core::ptr::addr_of_mut!(src0_param),
    );
    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(1 as isize) as *const wined3d_shader_src_param,
        src_write_mask,
        core::ptr::addr_of_mut!(src1_param),
    );

    if dst_size > 1 as ::core::ffi::c_uint {
        shader_addline(
            buffer,
            b"vec%d(dot(%s, %s)));\n\0".as_ptr() as *const ::core::ffi::c_char,
            dst_size,
            core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src1_param.param_str) as *mut ::core::ffi::c_char,
        );
    } else {
        shader_addline(
            buffer,
            b"dot(%s, %s));\n\0".as_ptr() as *const ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src1_param.param_str) as *mut ::core::ffi::c_char,
        );
    }
}

unsafe extern "C" fn shader_glsl_cross(ins: *const wined3d_shader_instruction) {
    let mut src_mask: DWORD = WINED3DSP_WRITEMASK_0 | WINED3DSP_WRITEMASK_1 | WINED3DSP_WRITEMASK_2;
    let mut src0_param: glsl_src_param = core::mem::zeroed();
    let mut src1_param: glsl_src_param = core::mem::zeroed();
    let mut dst_mask: [core::ffi::c_char; 6] = [0; 6];

    shader_glsl_get_write_mask(
        (*ins).dst.offset(0 as isize) as *const wined3d_shader_dst_param,
        core::ptr::addr_of_mut!(dst_mask) as *mut core::ffi::c_char,
    );
    shader_glsl_append_dst((*(*ins).ctx).buffer, ins);
    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
        src_mask,
        core::ptr::addr_of_mut!(src0_param),
    );
    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(1 as isize) as *const wined3d_shader_src_param,
        src_mask,
        core::ptr::addr_of_mut!(src1_param),
    );
    shader_addline(
        (*(*ins).ctx).buffer,
        b"cross(%s, %s)%s);\n\0".as_ptr() as *const core::ffi::c_char,
        core::ptr::addr_of_mut!(src0_param.param_str) as *mut core::ffi::c_char,
        core::ptr::addr_of_mut!(src1_param.param_str) as *mut core::ffi::c_char,
        core::ptr::addr_of_mut!(dst_mask) as *mut core::ffi::c_char,
    );
}

unsafe extern "C" fn shader_glsl_cut(ins: *const wined3d_shader_instruction) {
    let mut stream: u32 = if (*ins).handler_idx == WINED3DSIH_CUT {
        0
    } else {
        (*(*ins).src.add(0 as usize))
            .reg
            .idx[0 as usize]
            .offset
    };

    if stream == 0 {
        shader_addline(
            (*(*ins).ctx).buffer,
            b"EndPrimitive();\n\0".as_ptr() as *const i8,
        );
    } else {
        FIXME!("Unhandled primitive stream %u.\n", stream);
    }
}

unsafe extern "C" fn shader_glsl_pow(ins: *const wined3d_shader_instruction) {
    let buffer: *mut wined3d_string_buffer = (*(*ins).ctx).buffer;
    let mut src0_param: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mut src1_param: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mut dst_write_mask: DWORD = 0;
    let mut dst_size: ::core::ffi::c_uint = 0;

    dst_write_mask = shader_glsl_append_dst(buffer, ins);
    dst_size = shader_glsl_get_write_mask_size(dst_write_mask);

    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
        WINED3DSP_WRITEMASK_0,
        core::ptr::addr_of_mut!(src0_param),
    );
    shader_glsl_add_src_param(
        ins,
        (*ins).src.offset(1 as isize) as *const wined3d_shader_src_param,
        WINED3DSP_WRITEMASK_0,
        core::ptr::addr_of_mut!(src1_param),
    );

    if dst_size > 1 as ::core::ffi::c_uint {
        shader_addline(
            buffer,
            b"vec%u(%s == 0.0 ? 1.0 : pow(abs(%s), %s)));\n\0".as_ptr() as *const ::core::ffi::c_char,
            dst_size,
            core::ptr::addr_of_mut!(src1_param.param_str) as *mut ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src1_param.param_str) as *mut ::core::ffi::c_char,
        );
    } else {
        shader_addline(
            buffer,
            b"%s == 0.0 ? 1.0 : pow(abs(%s), %s));\n\0".as_ptr() as *const ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src1_param.param_str) as *mut ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src0_param.param_str) as *mut ::core::ffi::c_char,
            core::ptr::addr_of_mut!(src1_param.param_str) as *mut ::core::ffi::c_char,
        );
    }
}

unsafe extern "C" fn shader_glsl_map2gl(ins: *const wined3d_shader_instruction) {
    let buffer: *mut wined3d_string_buffer = (*(*ins).ctx).buffer;
    let mut src_param: glsl_src_param = glsl_src_param { param_str: [0; 200] };
    let mut instruction: *const i8 = core::ptr::null();
    let mut write_mask: u32;
    let mut i: u32;

    match (*ins).handler_idx as u32 {
        WINED3DSIH_ABS => {
            instruction = b"abs\0".as_ptr() as *const i8;
        }
        WINED3DSIH_BFREV => {
            instruction = b"bitfieldReverse\0".as_ptr() as *const i8;
        }
        WINED3DSIH_COUNTBITS => {
            instruction = b"bitCount\0".as_ptr() as *const i8;
        }
        WINED3DSIH_DSX => {
            instruction = b"dFdx\0".as_ptr() as *const i8;
        }
        WINED3DSIH_DSX_COARSE => {
            instruction = b"dFdxCoarse\0".as_ptr() as *const i8;
        }
        WINED3DSIH_DSX_FINE => {
            instruction = b"dFdxFine\0".as_ptr() as *const i8;
        }
        WINED3DSIH_DSY => {
            instruction = b"dFdy\0".as_ptr() as *const i8;
        }
        WINED3DSIH_DSY_COARSE => {
            instruction = b"dFdyCoarse\0".as_ptr() as *const i8;
        }
        WINED3DSIH_DSY_FINE => {
            instruction = b"dFdyFine\0".as_ptr() as *const i8;
        }
        WINED3DSIH_FIRSTBIT_HI => {
            instruction = b"findMSB\0".as_ptr() as *const i8;
        }
        WINED3DSIH_FIRSTBIT_LO => {
            instruction = b"findLSB\0".as_ptr() as *const i8;
        }
        WINED3DSIH_FIRSTBIT_SHI => {
            instruction = b"findMSB\0".as_ptr() as *const i8;
        }
        WINED3DSIH_FRC => {
            instruction = b"fract\0".as_ptr() as *const i8;
        }
        WINED3DSIH_IMAX => {
            instruction = b"max\0".as_ptr() as *const i8;
        }
        WINED3DSIH_IMIN => {
            instruction = b"min\0".as_ptr() as *const i8;
        }
        WINED3DSIH_MAX => {
            instruction = b"max\0".as_ptr() as *const i8;
        }
        WINED3DSIH_MIN => {
            instruction = b"min\0".as_ptr() as *const i8;
        }
        WINED3DSIH_ROUND_NE => {
            instruction = b"roundEven\0".as_ptr() as *const i8;
        }
        WINED3DSIH_ROUND_NI => {
            instruction = b"floor\0".as_ptr() as *const i8;
        }
        WINED3DSIH_ROUND_PI => {
            instruction = b"ceil\0".as_ptr() as *const i8;
        }
        WINED3DSIH_ROUND_Z => {
            instruction = b"trunc\0".as_ptr() as *const i8;
        }
        WINED3DSIH_SQRT => {
            instruction = b"sqrt\0".as_ptr() as *const i8;
        }
        WINED3DSIH_UMAX => {
            instruction = b"max\0".as_ptr() as *const i8;
        }
        WINED3DSIH_UMIN => {
            instruction = b"min\0".as_ptr() as *const i8;
        }
        _ => {
            instruction = b"\0".as_ptr() as *const i8;
            ERR!(
                b"Opcode %s not yet handled in GLSL.\n\0".as_ptr() as *const i8,
                debug_d3dshaderinstructionhandler((*ins).handler_idx)
            );
        }
    }

    write_mask = shader_glsl_append_dst(buffer, ins);

    /* In D3D bits are numbered from the most significant bit. */
    if (*ins).handler_idx as u32 == WINED3DSIH_FIRSTBIT_HI
        || (*ins).handler_idx as u32 == WINED3DSIH_FIRSTBIT_SHI
    {
        shader_addline(buffer, b"31 - \0".as_ptr() as *const i8);
    }
    shader_addline(buffer, b"%s(\0".as_ptr() as *const i8, instruction);

    if (*ins).src_count != 0 {
        shader_glsl_add_src_param(
            ins,
            (*ins).src.add(0 as usize),
            write_mask,
            core::ptr::addr_of_mut!(src_param),
        );
        shader_addline(
            buffer,
            b"%s\0".as_ptr() as *const i8,
            core::ptr::addr_of_mut!(src_param.param_str) as *mut i8,
        );
        i = 1;
        while i < (*ins).src_count {
            shader_glsl_add_src_param(
                ins,
                (*ins).src.add(i as usize),
                write_mask,
                core::ptr::addr_of_mut!(src_param),
            );
            shader_addline(
                buffer,
                b", %s\0".as_ptr() as *const i8,
                core::ptr::addr_of_mut!(src_param.param_str) as *mut i8,
            );
            i = i.wrapping_add(1);
        }
    }

    shader_addline(buffer, b"));\n\0".as_ptr() as *const i8);
}

unsafe extern "C" fn shader_glsl_float16(ins: *const wined3d_shader_instruction) {
    let mut dst: wined3d_shader_dst_param = core::mem::zeroed();
    let mut src: glsl_src_param = core::mem::zeroed();
    let mut write_mask: DWORD = 0;
    let mut fmt: *const ::core::ffi::c_char = ::core::ptr::null::<::core::ffi::c_char>();
    let mut i: ::core::ffi::c_uint = 0;
    fmt = if (*ins).handler_idx as ::core::ffi::c_uint
        == WINED3DSIH_F16TOF32 as ::core::ffi::c_uint
    {
        b"unpackHalf2x16(%s).x);\n\0".as_ptr() as *const ::core::ffi::c_char
    } else {
        b"packHalf2x16(vec2(%s, 0.0)));\n\0".as_ptr() as *const ::core::ffi::c_char
    };
    dst = *(*ins).dst.offset(0 as isize);
    i = 0 as ::core::ffi::c_uint;
    while i < 4 as ::core::ffi::c_uint {
        dst.write_mask = (*(*ins).dst.offset(0 as isize)).write_mask
            & ((WINED3DSP_WRITEMASK_0 as uint32_t) << i);
        write_mask = shader_glsl_append_dst_ext(
            (*(*ins).ctx).buffer,
            ins,
            &raw mut dst,
            0 as ::core::ffi::c_uint,
            dst.reg.data_type,
        );
        if !(write_mask == 0) {
            shader_glsl_add_src_param(
                ins,
                (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
                write_mask,
                &raw mut src,
            );
            shader_addline(
                (*(*ins).ctx).buffer,
                fmt,
                &raw mut src.param_str as *mut ::core::ffi::c_char,
            );
        }
        i = i.wrapping_add(1);
    }
}

unsafe extern "C" fn shader_glsl_bitwise_op(ins: *const wined3d_shader_instruction) {
    let mut buffer: *mut wined3d_string_buffer = (*(*ins).ctx).buffer;
    let mut dst: wined3d_shader_dst_param = *(*ins).dst.offset(0 as isize);
    let mut src: [glsl_src_param; 4] = core::mem::zeroed();
    let mut instruction: *const ::core::ffi::c_char = core::ptr::null();
    let mut tmp_dst: BOOL = (FALSE as i32);
    let mut mask_char: [::core::ffi::c_char; 6] = [0; 6];
    let mut i: ::core::ffi::c_uint = 0;
    let mut j: ::core::ffi::c_uint = 0;
    let mut write_mask: DWORD = 0;

    match (*ins).handler_idx as ::core::ffi::c_uint {
        WINED3DSIH_BFI => {
            instruction = b"bitfieldInsert\0".as_ptr() as *const ::core::ffi::c_char;
        }
        WINED3DSIH_IBFE => {
            instruction = b"bitfieldExtract\0".as_ptr() as *const ::core::ffi::c_char;
        }
        WINED3DSIH_UBFE => {
            instruction = b"bitfieldExtract\0".as_ptr() as *const ::core::ffi::c_char;
        }
        _ => {
            ERR!("Unhandled opcode %#x.\n", (*ins).handler_idx);
            return;
        }
    }

    i = 0 as ::core::ffi::c_uint;
    while i < (*ins).src_count {
        if (*(*ins).dst.offset(0 as isize))
            .reg
            .idx[0 as usize]
            .offset
            == (*(*ins).src.offset(i as isize))
                .reg
                .idx[0 as usize]
                .offset
            && (*(*ins).dst.offset(0 as isize))
                .reg
                .type_ as ::core::ffi::c_uint
                == (*(*ins).src.offset(i as isize)).reg.type_ as ::core::ffi::c_uint
        {
            tmp_dst = (TRUE as i32);
        }
        i = i.wrapping_add(1);
    }

    dst = *(*ins).dst.offset(0 as isize);
    i = 0 as ::core::ffi::c_uint;
    while i < 4 as ::core::ffi::c_uint {
        'body: {
            dst.write_mask = (*(*ins).dst.offset(0 as isize)).write_mask
                & ((WINED3DSP_WRITEMASK_0 as DWORD) << i);

            let mut is_tmp: bool = false;
            if tmp_dst != 0 {
                write_mask = shader_glsl_get_write_mask(
                    &raw mut dst,
                    mask_char.as_mut_ptr(),
                );
                is_tmp = write_mask != 0;
            }
            if is_tmp {
                shader_addline(
                    buffer,
                    b"tmp0%s = %sBitsToFloat(\0".as_ptr() as *const ::core::ffi::c_char,
                    mask_char.as_mut_ptr(),
                    if dst.reg.data_type as ::core::ffi::c_uint
                        == WINED3D_DATA_INT as ::core::ffi::c_uint
                    {
                        b"int\0".as_ptr() as *const ::core::ffi::c_char
                    } else {
                        b"uint\0".as_ptr() as *const ::core::ffi::c_char
                    },
                );
            } else {
                write_mask = shader_glsl_append_dst_ext(
                    buffer,
                    ins,
                    &raw mut dst,
                    0 as ::core::ffi::c_uint,
                    dst.reg.data_type,
                );
                if write_mask == 0 {
                    break 'body;
                }
            }

            j = 0 as ::core::ffi::c_uint;
            while j < (*ins).src_count {
                shader_glsl_add_src_param(
                    ins,
                    (*ins).src.offset(j as isize) as *const wined3d_shader_src_param,
                    write_mask,
                    (&raw mut src as *mut glsl_src_param).offset(j as isize) as *mut glsl_src_param,
                );
                j = j.wrapping_add(1);
            }
            shader_addline(
                buffer,
                b"%s(\0".as_ptr() as *const ::core::ffi::c_char,
                instruction,
            );
            j = 0 as ::core::ffi::c_uint;
            while j < (*ins).src_count.wrapping_sub(2 as ::core::ffi::c_uint) {
                shader_addline(
                    buffer,
                    b"%s, \0".as_ptr() as *const ::core::ffi::c_char,
                    &raw mut (*(&raw mut src as *mut glsl_src_param).offset(
                        (*ins)
                            .src_count
                            .wrapping_sub(j)
                            .wrapping_sub(1 as ::core::ffi::c_uint)
                            as isize,
                    ))
                    .param_str as *mut ::core::ffi::c_char,
                );
                j = j.wrapping_add(1);
            }
            shader_addline(
                buffer,
                b"%s & 0x1f, %s & 0x1f));\n\0".as_ptr() as *const ::core::ffi::c_char,
                &raw mut (*(&raw mut src as *mut glsl_src_param)
                    .offset(1 as isize))
                .param_str as *mut ::core::ffi::c_char,
                &raw mut (*(&raw mut src as *mut glsl_src_param)
                    .offset(0 as isize))
                .param_str as *mut ::core::ffi::c_char,
            );
        }
        i = i.wrapping_add(1);
    }

    if tmp_dst != 0 {
        shader_glsl_append_dst_ext(
            buffer,
            ins,
            (*ins).dst.offset(0 as isize) as *const wined3d_shader_dst_param,
            0 as ::core::ffi::c_uint,
            WINED3D_DATA_FLOAT,
        );
        shader_glsl_get_write_mask(
            (*ins).dst.offset(0 as isize) as *const wined3d_shader_dst_param,
            mask_char.as_mut_ptr(),
        );
        shader_addline(
            buffer,
            b"tmp0%s);\n\0".as_ptr() as *const ::core::ffi::c_char,
            mask_char.as_mut_ptr(),
        );
    }
}

