unsafe extern "C" fn shader_glsl_compare(ins: *const wined3d_shader_instruction) {
    let mut src0_param: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mut src1_param: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mut write_mask: DWORD;
    let mut mask_size: u32;

    write_mask = shader_glsl_append_dst((*(*ins).ctx).buffer, ins);
    mask_size = shader_glsl_get_write_mask_size(write_mask);
    shader_glsl_add_src_param(
        ins,
        (*ins).src.add(0) as *const wined3d_shader_src_param,
        write_mask,
        core::ptr::addr_of_mut!(src0_param),
    );
    shader_glsl_add_src_param(
        ins,
        (*ins).src.add(1) as *const wined3d_shader_src_param,
        write_mask,
        core::ptr::addr_of_mut!(src1_param),
    );

    if mask_size > 1 {
        let mut compare: *const i8 = core::ptr::null();

        match (*ins).handler_idx as u32 {
            WINED3DSIH_SLT => {
                compare = b"lessThan\0".as_ptr() as *const i8;
            }
            WINED3DSIH_SGE => {
                compare = b"greaterThanEqual\0".as_ptr() as *const i8;
            }
            _ => {
                compare = b"\0".as_ptr() as *const i8;
                FIXME!("Can't handle opcode %s.\n", debug_d3dshaderinstructionhandler((*ins).handler_idx));
            }
        }

        shader_addline(
            (*(*ins).ctx).buffer,
            b"vec%d(%s(%s, %s)));\n\0".as_ptr() as *const i8,
            mask_size,
            compare,
            core::ptr::addr_of_mut!(src0_param.param_str) as *mut i8,
            core::ptr::addr_of_mut!(src1_param.param_str) as *mut i8,
        );
    } else {
        match (*ins).handler_idx as u32 {
            WINED3DSIH_SLT => {
                /* Step(src0, src1) is not suitable here because if src0 == src1 SLT is supposed,
                 * to return 0.0 but step returns 1.0 because step is not < x
                 * An alternative is a bvec compare padded with an unused second component.
                 * step(src1 * -1.0, src0 * -1.0) is not an option because it suffers from the same
                 * issue. Playing with not() is not possible either because not() does not accept
                 * a scalar.
                 */
                shader_addline(
                    (*(*ins).ctx).buffer,
                    b"(%s < %s) ? 1.0 : 0.0);\n\0".as_ptr() as *const i8,
                    core::ptr::addr_of_mut!(src0_param.param_str) as *mut i8,
                    core::ptr::addr_of_mut!(src1_param.param_str) as *mut i8,
                );
            }
            WINED3DSIH_SGE => {
                /* Here we can use the step() function and safe a conditional */
                shader_addline(
                    (*(*ins).ctx).buffer,
                    b"step(%s, %s));\n\0".as_ptr() as *const i8,
                    core::ptr::addr_of_mut!(src1_param.param_str) as *mut i8,
                    core::ptr::addr_of_mut!(src0_param.param_str) as *mut i8,
                );
            }
            _ => {
                FIXME!("Can't handle opcode %s.\n", debug_d3dshaderinstructionhandler((*ins).handler_idx));
            }
        }
    }
}

unsafe extern "C" fn shader_glsl_swapc(ins: *const wined3d_shader_instruction) {
    let buffer: *mut wined3d_string_buffer = (*(*ins).ctx).buffer;
    let mut dst: [wined3d_shader_dst_param; 2 as usize] = core::mem::zeroed();
    let mut src: [glsl_src_param; 3 as usize] = core::mem::zeroed();
    let mut i: ::core::ffi::c_uint = 0;
    let mut j: ::core::ffi::c_uint = 0;
    let mut k: ::core::ffi::c_uint = 0;
    let mut mask_char: [::core::ffi::c_char; 6 as usize] = [0; 6 as usize];
    let mut write_mask: DWORD = 0;
    let mut tmp_dst: [BOOL; 2 as usize] = [0; 2 as usize];

    i = 0;
    while i < (*ins).dst_count {
        tmp_dst[i as usize] = (FALSE as i32);
        j = 0;
        while j < (*ins).src_count {
            if (*(*ins).dst.offset(i as isize)).reg.idx[0 as usize].offset
                == (*(*ins).src.offset(j as isize)).reg.idx[0 as usize].offset
                && (*(*ins).dst.offset(i as isize)).reg.type_ as ::core::ffi::c_uint
                    == (*(*ins).src.offset(j as isize)).reg.type_ as ::core::ffi::c_uint
            {
                tmp_dst[i as usize] = (TRUE as i32);
            }
            j = j.wrapping_add(1);
        }
        i = i.wrapping_add(1);
    }

    dst[0 as usize] = *(*ins).dst.offset(0 as isize);
    dst[1 as usize] = *(*ins).dst.offset(1 as isize);
    i = 0;
    while i < 4 {
        j = 0;
        while (j as usize) < ARRAY_SIZE!(dst) as usize {
            dst[j as usize].write_mask = (*(*ins).dst.offset(j as isize)).write_mask
                & (WINED3DSP_WRITEMASK_0 as uint32_t) << i;

            let body: bool;
            if tmp_dst[j as usize] != 0 && {
                write_mask = shader_glsl_get_write_mask(
                    (&raw mut dst as *mut wined3d_shader_dst_param).offset(j as isize)
                        as *mut wined3d_shader_dst_param,
                    &raw mut mask_char as *mut ::core::ffi::c_char,
                );
                write_mask != 0
            } {
                shader_addline(
                    buffer,
                    b"tmp%u%s = (\0" as *const u8 as *const ::core::ffi::c_char,
                    j,
                    &raw mut mask_char as *mut ::core::ffi::c_char,
                );
                body = true;
            } else {
                write_mask = shader_glsl_append_dst_ext(
                    buffer,
                    ins,
                    (&raw mut dst as *mut wined3d_shader_dst_param).offset(j as isize)
                        as *mut wined3d_shader_dst_param,
                    j,
                    dst[j as usize].reg.data_type,
                );
                body = write_mask != 0;
            }

            if body {
                k = 0;
                while (k as usize) < ARRAY_SIZE!(src) as usize {
                    shader_glsl_add_src_param(
                        ins,
                        (*ins).src.offset(k as isize) as *const wined3d_shader_src_param,
                        write_mask,
                        (&raw mut src as *mut glsl_src_param).offset(k as isize)
                            as *mut glsl_src_param,
                    );
                    k = k.wrapping_add(1);
                }
                shader_addline(
                    buffer,
                    b"%sbool(%s) ? %s : %s);\n\0" as *const u8 as *const ::core::ffi::c_char,
                    if j == 0 {
                        b"!\0" as *const u8 as *const ::core::ffi::c_char
                    } else {
                        b"\0" as *const u8 as *const ::core::ffi::c_char
                    },
                    &raw mut (*(&raw mut src as *mut glsl_src_param)
                        .offset(0 as isize))
                    .param_str as *mut ::core::ffi::c_char,
                    &raw mut (*(&raw mut src as *mut glsl_src_param)
                        .offset(1 as isize))
                    .param_str as *mut ::core::ffi::c_char,
                    &raw mut (*(&raw mut src as *mut glsl_src_param)
                        .offset(2 as isize))
                    .param_str as *mut ::core::ffi::c_char,
                );
            }
            j = j.wrapping_add(1);
        }
        i = i.wrapping_add(1);
    }

    i = 0;
    while (i as usize) < ARRAY_SIZE!(tmp_dst) as usize {
        if tmp_dst[i as usize] != 0 {
            shader_glsl_get_write_mask(
                (*ins).dst.offset(i as isize) as *const wined3d_shader_dst_param,
                &raw mut mask_char as *mut ::core::ffi::c_char,
            );
            shader_glsl_append_dst_ext(
                buffer,
                ins,
                (*ins).dst.offset(i as isize) as *const wined3d_shader_dst_param,
                i,
                (*(*ins).dst.offset(i as isize)).reg.data_type,
            );
            shader_addline(
                buffer,
                b"tmp%u%s);\n\0" as *const u8 as *const ::core::ffi::c_char,
                i,
                &raw mut mask_char as *mut ::core::ffi::c_char,
            );
        }
        i = i.wrapping_add(1);
    }
}

unsafe extern "C" fn shader_glsl_conditional_move(ins: *const wined3d_shader_instruction) {
    let mut condition_prefix: *const ::core::ffi::c_char = core::ptr::null();
    let mut condition_suffix: *const ::core::ffi::c_char = core::ptr::null();
    let mut dst: wined3d_shader_dst_param = core::mem::zeroed();
    let mut src0_param: glsl_src_param = core::mem::zeroed();
    let mut src1_param: glsl_src_param = core::mem::zeroed();
    let mut src2_param: glsl_src_param = core::mem::zeroed();
    let mut temp_destination: BOOL = (FALSE as i32);
    let mut cmp_channel: DWORD = 0;
    let mut i: ::core::ffi::c_uint;
    let mut j: ::core::ffi::c_uint;
    let mut mask_char: [::core::ffi::c_char; 6] = [0; 6];
    let mut write_mask: DWORD;

    match (*ins).handler_idx as ::core::ffi::c_uint {
        WINED3DSIH_CMP => {
            condition_prefix = b"\0".as_ptr() as *const ::core::ffi::c_char;
            condition_suffix = b" >= 0.0\0".as_ptr() as *const ::core::ffi::c_char;
        }
        WINED3DSIH_CND => {
            condition_prefix = b"\0".as_ptr() as *const ::core::ffi::c_char;
            condition_suffix = b" > 0.5\0".as_ptr() as *const ::core::ffi::c_char;
        }
        WINED3DSIH_MOVC => {
            condition_prefix = b"bool(\0".as_ptr() as *const ::core::ffi::c_char;
            condition_suffix = b")\0".as_ptr() as *const ::core::ffi::c_char;
        }
        _ => {
            FIXME!("Unhandled instruction %#x.\n", (*ins).handler_idx as ::core::ffi::c_uint);
            condition_prefix = b"<unhandled prefix>\0".as_ptr() as *const ::core::ffi::c_char;
            condition_suffix = b"<unhandled suffix>\0".as_ptr() as *const ::core::ffi::c_char;
        }
    }

    if shader_is_scalar(&raw const (*(*ins).dst.add(0 as usize)).reg) != 0
        || shader_is_scalar(&raw const (*(*ins).src.add(0 as usize)).reg) != 0
    {
        write_mask = shader_glsl_append_dst((*(*ins).ctx).buffer, ins);
        shader_glsl_add_src_param(
            ins,
            (*ins).src.add(0 as usize) as *const wined3d_shader_src_param,
            write_mask,
            &raw mut src0_param,
        );
        shader_glsl_add_src_param(
            ins,
            (*ins).src.add(1 as usize) as *const wined3d_shader_src_param,
            write_mask,
            &raw mut src1_param,
        );
        shader_glsl_add_src_param(
            ins,
            (*ins).src.add(2 as usize) as *const wined3d_shader_src_param,
            write_mask,
            &raw mut src2_param,
        );

        shader_addline(
            (*(*ins).ctx).buffer,
            b"%s%s%s ? %s : %s);\n\0".as_ptr() as *const ::core::ffi::c_char,
            condition_prefix,
            &raw mut src0_param.param_str as *mut ::core::ffi::c_char,
            condition_suffix,
            &raw mut src1_param.param_str as *mut ::core::ffi::c_char,
            &raw mut src2_param.param_str as *mut ::core::ffi::c_char,
        );
        return;
    }

    dst = *(*ins).dst.add(0 as usize);

    /* Splitting the instruction up in multiple lines imposes a problem:
     * The first lines may overwrite source parameters of the following lines.
     * Deal with that by using a temporary destination register if needed. */
    if ((*(*ins).src.add(0 as usize)).reg.idx[0 as usize].offset
            == dst.reg.idx[0 as usize].offset
            && (*(*ins).src.add(0 as usize)).reg.type_ as ::core::ffi::c_uint
                == dst.reg.type_ as ::core::ffi::c_uint)
        || ((*(*ins).src.add(1 as usize)).reg.idx[0 as usize].offset
            == dst.reg.idx[0 as usize].offset
            && (*(*ins).src.add(1 as usize)).reg.type_ as ::core::ffi::c_uint
                == dst.reg.type_ as ::core::ffi::c_uint)
        || ((*(*ins).src.add(2 as usize)).reg.idx[0 as usize].offset
            == dst.reg.idx[0 as usize].offset
            && (*(*ins).src.add(2 as usize)).reg.type_ as ::core::ffi::c_uint
                == dst.reg.type_ as ::core::ffi::c_uint)
    {
        temp_destination = (TRUE as i32);
    }

    /* Cycle through all source0 channels. */
    i = 0;
    while i < 4 {
        'body: {
            write_mask = 0;
            /* Find the destination channels which use the current source0 channel. */
            j = 0;
            while j < 4 {
                if shader_glsl_swizzle_get_component((*(*ins).src.add(0 as usize)).swizzle, j) == i {
                    write_mask |= (WINED3DSP_WRITEMASK_0 as DWORD) << j;
                    cmp_channel = (WINED3DSP_WRITEMASK_0 as DWORD) << j;
                }
                j = j.wrapping_add(1);
            }
            dst.write_mask = (*(*ins).dst.add(0 as usize)).write_mask & write_mask;

            if temp_destination != 0 {
                write_mask = shader_glsl_get_write_mask(&raw mut dst, &raw mut mask_char as *mut ::core::ffi::c_char);
                if write_mask == 0 {
                    break 'body;
                }
                shader_addline(
                    (*(*ins).ctx).buffer,
                    b"tmp0%s = (\0".as_ptr() as *const ::core::ffi::c_char,
                    &raw mut mask_char as *mut ::core::ffi::c_char,
                );
            } else {
                write_mask = shader_glsl_append_dst_ext(
                    (*(*ins).ctx).buffer,
                    ins,
                    &raw mut dst,
                    0,
                    dst.reg.data_type,
                );
                if write_mask == 0 {
                    break 'body;
                }
            }

            shader_glsl_add_src_param(
                ins,
                (*ins).src.add(0 as usize) as *const wined3d_shader_src_param,
                cmp_channel,
                &raw mut src0_param,
            );
            shader_glsl_add_src_param(
                ins,
                (*ins).src.add(1 as usize) as *const wined3d_shader_src_param,
                write_mask,
                &raw mut src1_param,
            );
            shader_glsl_add_src_param(
                ins,
                (*ins).src.add(2 as usize) as *const wined3d_shader_src_param,
                write_mask,
                &raw mut src2_param,
            );

            shader_addline(
                (*(*ins).ctx).buffer,
                b"%s%s%s ? %s : %s);\n\0".as_ptr() as *const ::core::ffi::c_char,
                condition_prefix,
                &raw mut src0_param.param_str as *mut ::core::ffi::c_char,
                condition_suffix,
                &raw mut src1_param.param_str as *mut ::core::ffi::c_char,
                &raw mut src2_param.param_str as *mut ::core::ffi::c_char,
            );
        }
        i = i.wrapping_add(1);
    }

    if temp_destination != 0 {
        shader_glsl_get_write_mask(
            (*ins).dst.add(0 as usize) as *const wined3d_shader_dst_param,
            &raw mut mask_char as *mut ::core::ffi::c_char,
        );
        shader_glsl_append_dst((*(*ins).ctx).buffer, ins);
        shader_addline(
            (*(*ins).ctx).buffer,
            b"tmp0%s);\n\0".as_ptr() as *const ::core::ffi::c_char,
            &raw mut mask_char as *mut ::core::ffi::c_char,
        );
    }
}

unsafe extern "C" fn shader_glsl_cnd(ins: *const wined3d_shader_instruction) {
    let mut src0_param: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mut src1_param: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mut src2_param: glsl_src_param = glsl_src_param {
        param_str: [0; 200],
    };
    let mut write_mask: DWORD = 0;
    let shader_version: DWORD = WINED3D_SHADER_VERSION!(
        (*(*(*ins).ctx).reg_maps).shader_version.major as DWORD,
        (*(*(*ins).ctx).reg_maps).shader_version.minor as DWORD,
    );

    if shader_version < WINED3D_SHADER_VERSION!(1, 4) {
        write_mask = shader_glsl_append_dst((*(*ins).ctx).buffer, ins);
        shader_glsl_add_src_param(
            ins,
            (*ins).src.offset(0 as isize) as *const wined3d_shader_src_param,
            WINED3DSP_WRITEMASK_0,
            core::ptr::addr_of_mut!(src0_param),
        );
        shader_glsl_add_src_param(
            ins,
            (*ins).src.offset(1 as isize) as *const wined3d_shader_src_param,
            write_mask,
            core::ptr::addr_of_mut!(src1_param),
        );
        shader_glsl_add_src_param(
            ins,
            (*ins).src.offset(2 as isize) as *const wined3d_shader_src_param,
            write_mask,
            core::ptr::addr_of_mut!(src2_param),
        );

        if (*ins).coissue != 0 && (*(*ins).dst).write_mask != WINED3DSP_WRITEMASK_3 {
            shader_addline(
                (*(*ins).ctx).buffer,
                b"%s /* COISSUE! */);\n\0".as_ptr() as *const i8,
                core::ptr::addr_of_mut!(src1_param.param_str) as *mut i8,
            );
        } else {
            shader_addline(
                (*(*ins).ctx).buffer,
                b"%s > 0.5 ? %s : %s);\n\0".as_ptr() as *const i8,
                core::ptr::addr_of_mut!(src0_param.param_str) as *mut i8,
                core::ptr::addr_of_mut!(src1_param.param_str) as *mut i8,
                core::ptr::addr_of_mut!(src2_param.param_str) as *mut i8,
            );
        }
        return;
    }

    shader_glsl_conditional_move(ins);
}

