unsafe extern "C" fn shader_glsl_emit(ins: *const wined3d_shader_instruction) {
    let stream: u32 = if (*ins).handler_idx == WINED3DSIH_EMIT {
        0
    } else {
        (*(*ins).src.offset(0 as isize)).reg.idx[0 as usize].offset
    };
    let reg_maps: *const wined3d_shader_reg_maps = (*(*ins).ctx).reg_maps;
    let priv_0: *const shader_glsl_ctx_priv = (*(*ins).ctx).backend_data as *const shader_glsl_ctx_priv;

    shader_addline(
        (*(*ins).ctx).buffer,
        b"setup_gs_output(gs_out);\n\0".as_ptr() as *const core::ffi::c_char,
    );
    if (*(*priv_0).gl_info).supported[ARB_CLIP_CONTROL as usize] == 0 {
        shader_glsl_fixup_position((*(*ins).ctx).buffer, (*reg_maps).viewport_array() as BOOL);
    }

    if stream == 0 {
        shader_addline(
            (*(*ins).ctx).buffer,
            b"EmitVertex();\n\0".as_ptr() as *const core::ffi::c_char,
        );
    } else {
        FIXME!("Unhandled primitive stream %u.\n", stream);
    }
}

