unsafe extern "C" fn shader_glsl_sync(ins: *const wined3d_shader_instruction) {
    let mut buffer: *mut wined3d_string_buffer = (*(*ins).ctx).buffer;
    let mut sync_flags: u32 = (*ins).flags as u32;

    if sync_flags & WINED3DSSF_THREAD_GROUP != 0 {
        shader_addline(buffer, b"barrier();\n\0".as_ptr() as *const i8);
        sync_flags &= !(WINED3DSSF_THREAD_GROUP | WINED3DSSF_GROUP_SHARED_MEMORY);
    }

    if sync_flags & WINED3DSSF_GROUP_SHARED_MEMORY != 0 {
        shader_addline(buffer, b"memoryBarrierShared();\n\0".as_ptr() as *const i8);
        sync_flags &= !WINED3DSSF_GROUP_SHARED_MEMORY;
    }

    if sync_flags & WINED3DSSF_GLOBAL_UAV != 0 {
        shader_addline(buffer, b"memoryBarrier();\n\0".as_ptr() as *const i8);
        sync_flags &= !WINED3DSSF_GLOBAL_UAV;
    }

    if sync_flags != 0 {
        FIXME!("Unhandled sync flags %#x.\n", sync_flags);
    }
}

