unsafe extern "C" fn glsl_fragment_pipe_alpha_test_func(
    mut context_gl: *mut wined3d_context_gl,
    mut state: *const wined3d_state,
) {
    let mut constants: *const wined3d_ffp_ps_constants = wined3d_buffer_load_sysmem(
        (*(*context_gl).c.device).push_constants[WINED3D_PUSH_CONSTANTS_PS_FFP as usize],
        &raw mut (*context_gl).c,
    ) as *const wined3d_ffp_ps_constants;
    let mut gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut func: GLint = wined3d_gl_compare_func(
        (*state).render_states[WINED3D_RS_ALPHAFUNC as usize] as wined3d_cmp_func,
    ) as GLint;
    if func != 0 {
        (*gl_info)
            .gl_ops
            .gl
            .p_glAlphaFunc
            .unwrap_unchecked()(
            func as GLenum,
            (*constants).alpha_test_ref as GLfloat,
        );
        checkGLcall!(gl_info, b"glAlphaFunc\0".as_ptr() as *const ::core::ffi::c_char);
    }
}

unsafe extern "C" fn glsl_fragment_pipe_core_alpha_test(
    context: *mut wined3d_context,
    state: *const wined3d_state,
    state_id: DWORD,
) {
    (*context).set_shader_update_mask(((*context).shader_update_mask() | ((1 as DWORD) << WINED3D_SHADER_TYPE_PIXEL)) as _);
}

unsafe extern "C" fn glsl_fragment_pipe_alpha_test(
    context_gl: *mut wined3d_context_gl,
    state: *const wined3d_state,
) {
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;

    if (*state).render_states[WINED3D_RS_ALPHATESTENABLE as usize] != 0 {
        (*gl_info)
            .gl_ops
            .gl
            .p_glEnable
            .unwrap_unchecked()(GL_ALPHA_TEST as GLenum);
        checkGLcall!(gl_info, b"glEnable(GL_ALPHA_TEST)\0".as_ptr() as *const i8);
    } else {
        (*gl_info)
            .gl_ops
            .gl
            .p_glDisable
            .unwrap_unchecked()(GL_ALPHA_TEST as GLenum);
        checkGLcall!(gl_info, b"glDisable(GL_ALPHA_TEST)\0".as_ptr() as *const i8);
    }
}

unsafe extern "C" fn glsl_fragment_pipe_shademode(
    context: *mut wined3d_context,
    state: *const wined3d_state,
    state_id: DWORD,
) {
    (*context).set_shader_update_mask(((*context).shader_update_mask() | (((1 as DWORD) << (WINED3D_SHADER_TYPE_PIXEL as u32)) as DWORD)) as _);
}

unsafe extern "C" fn glsl_fragment_pipe_alloc_context_data(
    context: *mut wined3d_context,
) -> BOOL {
    (TRUE as i32)
}

unsafe extern "C" fn glsl_fragment_pipe_free_context_data(context: *mut wined3d_context) {}

unsafe extern "C" fn shader_glsl_update_legacy_states(context_gl: *mut wined3d_context_gl, state: *const wined3d_state) {
    if (*(*context_gl).gl_info).supported[WINED3D_GL_LEGACY_CONTEXT as usize] == 0 {
        return;
    }

    if ((*context_gl).c.shader_update_mask() & ((1 as u32) << (WINED3D_SHADER_TYPE_PIXEL as u32))) != 0 {
        glsl_fragment_pipe_alpha_test(context_gl, state);
        glsl_fragment_pipe_alpha_test_func(context_gl, state);
    }

    if ((*context_gl).c.constant_update_mask & (WINED3D_SHADER_CONST_PS_ALPHA_TEST as DWORD)) != 0 {
        glsl_fragment_pipe_alpha_test_func(context_gl, state);
    }
}

unsafe extern "C" fn glsl_blitter_args_compare(key: *const core::ffi::c_void, entry: *const rb_entry) -> core::ffi::c_int {
    let a: *const glsl_blitter_args = key as *const glsl_blitter_args;
    let b: *const glsl_blitter_args = core::ptr::addr_of!((*WINE_RB_ENTRY_VALUE!(entry, glsl_blitter_program, entry)).args);
    return memcmp(
        a as *const core::ffi::c_void,
        b as *const core::ffi::c_void,
        core::mem::size_of::<glsl_blitter_args>(),
    );
}

unsafe extern "C" fn glsl_free_blitter_program(entry: *mut rb_entry, ctx: *mut ::core::ffi::c_void) {
    let program: *mut glsl_blitter_program = WINE_RB_ENTRY_VALUE!(entry, glsl_blitter_program, entry);
    let context_gl: *mut wined3d_context_gl = ctx as *mut wined3d_context_gl;
    let gl_info: *const wined3d_gl_info;

    gl_info = (*context_gl).gl_info;
    ((*gl_info).gl_ops.ext.p_glDeleteProgram.unwrap_unchecked())((*program).id);
    checkGLcall!(gl_info, b"glDeleteProgram()\0" as *const u8 as *const ::core::ffi::c_char);
    free(program as *mut ::core::ffi::c_void);
}

unsafe extern "C" fn glsl_blitter_destroy(
    mut blitter: *mut wined3d_blitter,
    mut context: *mut wined3d_context,
) {
    let mut context_gl: *mut wined3d_context_gl = wined3d_context_gl(context);
    let mut gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut glsl_blitter: *mut wined3d_glsl_blitter = core::ptr::null_mut::<wined3d_glsl_blitter>();
    let mut next: *mut wined3d_blitter = core::ptr::null_mut::<wined3d_blitter>();

    next = (*blitter).next;
    if !next.is_null() {
        (*(*next).ops)
            .blitter_destroy
            .unwrap_unchecked()(next, context);
    }

    glsl_blitter = CONTAINING_RECORD!(blitter, wined3d_glsl_blitter, blitter);

    if (*glsl_blitter).palette_texture != 0 {
        (*gl_info)
            .gl_ops
            .gl
            .p_glDeleteTextures
            .unwrap_unchecked()(
            1 as GLsizei,
            core::ptr::addr_of_mut!((*glsl_blitter).palette_texture),
        );
    }

    wine_rb_destroy(
        core::ptr::addr_of_mut!((*glsl_blitter).programs),
        Some(
            glsl_free_blitter_program
                as unsafe extern "C" fn(*mut rb_entry, *mut ::core::ffi::c_void) -> (),
        ),
        context_gl as *mut ::core::ffi::c_void,
    );
    string_buffer_list_cleanup(core::ptr::addr_of_mut!((*glsl_blitter).string_buffers));

    free(glsl_blitter as *mut ::core::ffi::c_void);
}

unsafe extern "C" fn glsl_blitter_generate_p8_shader(
    buffer: *mut wined3d_string_buffer,
    gl_info: *const wined3d_gl_info,
    args: *const glsl_blitter_args,
    output: *const core::ffi::c_char,
    tex_type: *const core::ffi::c_char,
    swizzle: *const core::ffi::c_char,
) {
    shader_addline(
        buffer,
        b"uniform sampler1D sampler_palette;\n\0" as *const u8 as *const core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"\nvoid main()\n{\n\0" as *const u8 as *const core::ffi::c_char,
    );
    /* The alpha-component contains the palette index. */
    shader_addline(
        buffer,
        b"    float index = texture%s(sampler, out_texcoord.%s).%c;\n\0" as *const u8
            as *const core::ffi::c_char,
        if needs_legacy_glsl_syntax(gl_info) != 0 {
            tex_type
        } else {
            b"\0" as *const u8 as *const core::ffi::c_char
        },
        swizzle,
        if (*gl_info).supported[WINED3D_GL_LEGACY_CONTEXT as usize] != 0 {
            'w' as i32
        } else {
            'x' as i32
        },
    );
    /* Scale the index by 255/256 and add a bias of 0.5 in order to sample in
     * the middle. */
    shader_addline(
        buffer,
        b"    index = (index * 255.0 + 0.5) / 256.0;\n\0" as *const u8 as *const core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    %s = texture%s(sampler_palette, index);\n\0" as *const u8
            as *const core::ffi::c_char,
        output,
        if needs_legacy_glsl_syntax(gl_info) != 0 {
            b"1D\0" as *const u8 as *const core::ffi::c_char
        } else {
            b"\0" as *const u8 as *const core::ffi::c_char
        },
    );
    if (*args).use_colour_key != 0 {
        shader_glsl_generate_colour_key_test(
            buffer,
            output,
            b"colour_key.low\0" as *const u8 as *const core::ffi::c_char,
            b"colour_key.high\0" as *const u8 as *const core::ffi::c_char,
        );
    }
    shader_addline(buffer, b"}\n\0" as *const u8 as *const core::ffi::c_char);
}

unsafe extern "C" fn gen_packed_yuv_read(
    mut buffer: *mut wined3d_string_buffer,
    mut gl_info: *const wined3d_gl_info,
    mut args: *const glsl_blitter_args,
    mut tex_type: *const ::core::ffi::c_char,
) {
    let mut complex_fixup: complex_fixup = get_complex_fixup((*args).fixup);
    let mut chroma: ::core::ffi::c_char = 0;
    let mut luminance: ::core::ffi::c_char = 0;
    let mut tex: *const ::core::ffi::c_char = ::core::ptr::null::<::core::ffi::c_char>();
    if complex_fixup as ::core::ffi::c_uint == COMPLEX_FIXUP_UYVY as ::core::ffi::c_uint {
        chroma = 'x' as i32 as ::core::ffi::c_char;
        luminance = (if (*gl_info).supported[WINED3D_GL_LEGACY_CONTEXT as usize] != 0 {
            'w' as i32
        } else {
            'y' as i32
        }) as ::core::ffi::c_char;
    } else {
        chroma = (if (*gl_info).supported[WINED3D_GL_LEGACY_CONTEXT as usize] != 0 {
            'w' as i32
        } else {
            'y' as i32
        }) as ::core::ffi::c_char;
        luminance = 'x' as i32 as ::core::ffi::c_char;
    }
    tex = if needs_legacy_glsl_syntax(gl_info) != 0 {
        tex_type
    } else {
        b"\0" as *const u8 as *const ::core::ffi::c_char
    };
    shader_addline(
        buffer,
        b"    texcoord.xy = out_texcoord.xy;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    texcoord.x = (floor(texcoord.x * size.x) + 0.5) / size.x;\n\0" as *const u8
            as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    luminance = texture%s(sampler, texcoord.xy).%c;\n\0" as *const u8
            as *const ::core::ffi::c_char,
        tex,
        chroma as ::core::ffi::c_int,
    );
    shader_addline(
        buffer,
        b"    bool even = fract(texcoord.x * size.x * 0.5) < 0.5;\n\0" as *const u8
            as *const ::core::ffi::c_char,
    );
    shader_addline(buffer, b"    if (even)\n\0" as *const u8 as *const ::core::ffi::c_char);
    shader_addline(
        buffer,
        b"        chroma.y = luminance;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(buffer, b"    else\n\0" as *const u8 as *const ::core::ffi::c_char);
    shader_addline(
        buffer,
        b"        chroma.x = luminance;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    texcoord.x += even ? 1.0 / size.x : -1.0 / size.x;\n\0" as *const u8
            as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    luminance = texture%s(sampler, texcoord.xy).%c;\n\0" as *const u8
            as *const ::core::ffi::c_char,
        tex,
        chroma as ::core::ffi::c_int,
    );
    shader_addline(buffer, b"    if (even)\n\0" as *const u8 as *const ::core::ffi::c_char);
    shader_addline(
        buffer,
        b"        chroma.x = luminance;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(buffer, b"    else\n\0" as *const u8 as *const ::core::ffi::c_char);
    shader_addline(
        buffer,
        b"        chroma.y = luminance;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    luminance = texture%s(sampler, out_texcoord.xy).%c;\n\0" as *const u8
            as *const ::core::ffi::c_char,
        tex,
        luminance as ::core::ffi::c_int,
    );
}

unsafe extern "C" fn gen_yv12_read(
    mut buffer: *mut wined3d_string_buffer,
    mut gl_info: *const wined3d_gl_info,
    mut tex_type: *const ::core::ffi::c_char,
) {
    let mut component: ::core::ffi::c_char =
        (if (*gl_info).supported[WINED3D_GL_LEGACY_CONTEXT as usize] != 0 {
            'w' as i32
        } else {
            'x' as i32
        }) as ::core::ffi::c_char;
    let mut tex: *const ::core::ffi::c_char = if needs_legacy_glsl_syntax(gl_info) != 0 {
        tex_type
    } else {
        b"\0".as_ptr() as *const ::core::ffi::c_char
    };

    /* First sample the chroma values. */
    shader_addline(
        buffer,
        b"    texcoord.xy = out_texcoord.xy;\n\0".as_ptr() as *const ::core::ffi::c_char,
    );
    /* The chroma planes have only half the width. */
    shader_addline(
        buffer,
        b"    texcoord.x *= 0.5;\n\0".as_ptr() as *const ::core::ffi::c_char,
    );

    /* Read odd lines from the right side (add 0.5 to the x coordinate). */
    shader_addline(
        buffer,
        b"    if (fract(texcoord.y * size.y * 0.25) >= 0.5)\n\0".as_ptr()
            as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"        texcoord.x += 0.5;\n\0".as_ptr() as *const ::core::ffi::c_char,
    );

    /* Clamp, keep the half pixel origin in mind. */
    shader_addline(
        buffer,
        b"    texcoord.y = clamp(2.0 / 3.0 + texcoord.y / 6.0, 2.0 / 3.0 + 0.5 / size.y, 5.0 / 6.0 - 0.5 / size.y);\n\0"
            .as_ptr() as *const ::core::ffi::c_char,
    );

    shader_addline(
        buffer,
        b"    chroma.x = texture%s(sampler, texcoord.xy).%c;\n\0".as_ptr()
            as *const ::core::ffi::c_char,
        tex,
        component as ::core::ffi::c_int,
    );

    /* The other chroma value is 1/6th of the texture lower. */
    shader_addline(
        buffer,
        b"    texcoord.y += 1.0 / 6.0;\n\0".as_ptr() as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    chroma.y = texture%s(sampler, texcoord.xy).%c;\n\0".as_ptr()
            as *const ::core::ffi::c_char,
        tex,
        component as ::core::ffi::c_int,
    );

    /* Sample the luminance value. */
    shader_addline(
        buffer,
        b"    texcoord.xy = out_texcoord.xy;\n\0".as_ptr() as *const ::core::ffi::c_char,
    );
    /* Multiply the y coordinate by 2/3 and clamp it. */
    shader_addline(
        buffer,
        b"    texcoord.y = min(texcoord.y * 2.0 / 3.0, 2.0 / 3.0 - 0.5 / size.y);\n\0".as_ptr()
            as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    luminance = texture%s(sampler, texcoord.xy).%c;\n\0".as_ptr()
            as *const ::core::ffi::c_char,
        tex,
        component as ::core::ffi::c_int,
    );
}

unsafe extern "C" fn gen_nv12_read(buffer: *mut wined3d_string_buffer, gl_info: *const wined3d_gl_info, tex_type: *const ::core::ffi::c_char) {
    let mut component: ::core::ffi::c_char = (if (*gl_info).supported[WINED3D_GL_LEGACY_CONTEXT as usize] != 0 {
        'w' as i32
    } else {
        'x' as i32
    }) as ::core::ffi::c_char;
    let mut tex: *const ::core::ffi::c_char = if needs_legacy_glsl_syntax(gl_info) != 0 {
        tex_type
    } else {
        b"\0" as *const u8 as *const ::core::ffi::c_char
    };
    shader_addline(
        buffer,
        b"    texcoord.xy = out_texcoord.xy;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    texcoord.x *= 0.5;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    texcoord.y = (texcoord.y + 2.0) / 3.0;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    texcoord.x = floor(texcoord.x * size.x);\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    texcoord.x = (texcoord.x * 2.0 + 0.5) / size.x;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    texcoord.y = max(texcoord.y, 2.0 / 3.0 + 0.5 / size.y);\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    chroma.y = texture%s(sampler, texcoord.xy).%c;\n\0" as *const u8 as *const ::core::ffi::c_char,
        tex,
        component as ::core::ffi::c_int,
    );
    shader_addline(
        buffer,
        b"    texcoord.x += 1.0 / size.x;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    chroma.x = texture%s(sampler, texcoord.xy).%c;\n\0" as *const u8 as *const ::core::ffi::c_char,
        tex,
        component as ::core::ffi::c_int,
    );
    shader_addline(
        buffer,
        b"    texcoord.xy = out_texcoord.xy;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    texcoord.y = min(texcoord.y * 2.0 / 3.0, 2.0 / 3.0 - 0.5 / size.y);\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    luminance = texture%s(sampler, texcoord.xy).%c;\n\0" as *const u8 as *const ::core::ffi::c_char,
        tex,
        component as ::core::ffi::c_int,
    );
}

unsafe extern "C" fn glsl_blitter_generate_yuv_shader(
    buffer: *mut wined3d_string_buffer,
    gl_info: *const wined3d_gl_info,
    args: *const glsl_blitter_args,
    output: *const ::core::ffi::c_char,
    tex_type: *const ::core::ffi::c_char,
    swizzle: *const ::core::ffi::c_char,
) {
    let complex_fixup: complex_fixup = get_complex_fixup((*args).fixup);

    shader_addline(
        buffer,
        b"const vec4 yuv_coef = vec4(1.403, -0.344, -0.714, 1.770);\n\0" as *const u8
            as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"float luminance;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"vec2 texcoord;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"vec2 chroma;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"uniform vec2 size;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );

    shader_addline(
        buffer,
        b"\nvoid main()\n{\n\0" as *const u8 as *const ::core::ffi::c_char,
    );

    match complex_fixup as ::core::ffi::c_uint {
        COMPLEX_FIXUP_UYVY | COMPLEX_FIXUP_YUY2 => {
            gen_packed_yuv_read(buffer, gl_info, args, tex_type);
        }
        COMPLEX_FIXUP_YV12 => {
            gen_yv12_read(buffer, gl_info, tex_type);
        }
        COMPLEX_FIXUP_NV12 => {
            gen_nv12_read(buffer, gl_info, tex_type);
        }
        COMPLEX_FIXUP_YUV => {
            /* With APPLE_rgb_422, things are much simpler. The only thing we
             * have to do here is Y'CbCr to RGB conversion. */
            shader_addline(
                buffer,
                b"    vec3 yuv = vec3(texture%s(sampler, out_texcoord.xy));\n\0" as *const u8
                    as *const ::core::ffi::c_char,
                if needs_legacy_glsl_syntax(gl_info) != 0 {
                    tex_type
                } else {
                    b"\0" as *const u8 as *const ::core::ffi::c_char
                },
            );
            shader_addline(
                buffer,
                b"    luminance = yuv.y;\n\0" as *const u8 as *const ::core::ffi::c_char,
            );
            shader_addline(
                buffer,
                b"    chroma = yuv.xz;\n\0" as *const u8 as *const ::core::ffi::c_char,
            );
        }
        _ => {
            FIXME!("Unsupported fixup %#x.\n", complex_fixup as ::core::ffi::c_uint);
            string_buffer_free(buffer);
            return;
        }
    }

    /* Calculate the final result. Formula is taken from
     * http://www.fourcc.org/fccyvrgb.php. Note that the chroma
     * ranges from -0.5 to 0.5. */
    shader_addline(
        buffer,
        b"\n    chroma.xy -= 0.5;\n\0" as *const u8 as *const ::core::ffi::c_char,
    );

    shader_addline(
        buffer,
        b"    %s.x = luminance + chroma.x * yuv_coef.x;\n\0" as *const u8
            as *const ::core::ffi::c_char,
        output,
    );
    shader_addline(
        buffer,
        b"    %s.y = luminance + chroma.y * yuv_coef.y + chroma.x * yuv_coef.z;\n\0" as *const u8
            as *const ::core::ffi::c_char,
        output,
    );
    shader_addline(
        buffer,
        b"    %s.z = luminance + chroma.y * yuv_coef.w;\n\0" as *const u8
            as *const ::core::ffi::c_char,
        output,
    );
    if (*args).use_colour_key != 0 {
        shader_glsl_generate_colour_key_test(
            buffer,
            output,
            b"colour_key.low\0" as *const u8 as *const ::core::ffi::c_char,
            b"colour_key.high\0" as *const u8 as *const ::core::ffi::c_char,
        );
    }

    shader_addline(buffer, b"}\n\0" as *const u8 as *const ::core::ffi::c_char);
}

unsafe extern "C" fn glsl_blitter_generate_plain_shader(
    buffer: *mut wined3d_string_buffer,
    gl_info: *const wined3d_gl_info,
    args: *const glsl_blitter_args,
    output: *const ::core::ffi::c_char,
    tex_type: *const ::core::ffi::c_char,
    swizzle: *const ::core::ffi::c_char,
) {
    shader_addline(
        buffer,
        b"\nvoid main()\n{\n\0".as_ptr() as *const ::core::ffi::c_char,
    );
    shader_addline(
        buffer,
        b"    %s = texture%s(sampler, out_texcoord.%s);\n\0".as_ptr() as *const ::core::ffi::c_char,
        output,
        if needs_legacy_glsl_syntax(gl_info) != 0 {
            tex_type
        } else {
            b"\0".as_ptr() as *const ::core::ffi::c_char
        },
        swizzle,
    );
    shader_glsl_color_correction_ext(buffer, output, WINED3DSP_WRITEMASK_ALL, (*args).fixup);
    if (*args).use_colour_key != 0 {
        shader_glsl_generate_colour_key_test(
            buffer,
            output,
            b"colour_key.low\0".as_ptr() as *const ::core::ffi::c_char,
            b"colour_key.high\0".as_ptr() as *const ::core::ffi::c_char,
        );
    }
    shader_addline(buffer, b"}\n\0".as_ptr() as *const ::core::ffi::c_char);
}

unsafe extern "C" fn glsl_blitter_generate_program(
    blitter: *mut wined3d_glsl_blitter,
    gl_info: *const wined3d_gl_info,
    args: *const glsl_blitter_args,
) -> GLuint {
    #[repr(C)]
    struct TextureData {
        texture_target: GLenum,
        texture_type: [u8; 7],
        texcoord_swizzle: [u8; 4],
    }
    static texture_data: [TextureData; 2] = [
        TextureData {
            texture_target: GL_TEXTURE_2D as GLenum,
            texture_type: *b"2D\0\0\0\0\0",
            texcoord_swizzle: *b"xy\0\0",
        },
        TextureData {
            texture_target: GL_TEXTURE_CUBE_MAP as GLenum,
            texture_type: *b"Cube\0\0\0",
            texcoord_swizzle: *b"xyz\0",
        },
    ];
    static vshader_main: [u8; 86] = *b"\nvoid main()\n{\n    gl_Position = vec4(pos, 0.0, 1.0);\n    out_texcoord = texcoord;\n}\n\0";
    let mut complex_fixup: complex_fixup = get_complex_fixup((*args).fixup);
    let mut buffer: *mut wined3d_string_buffer = core::ptr::null_mut();
    let mut output: *mut wined3d_string_buffer = core::ptr::null_mut();
    let mut program: GLuint = 0;
    let mut vshader_id: GLuint = 0;
    let mut fshader_id: GLuint = 0;
    let mut tex_type: *const ::core::ffi::c_char = core::ptr::null();
    let mut swizzle: *const ::core::ffi::c_char = core::ptr::null();
    let mut ptr: *const ::core::ffi::c_char = core::ptr::null();
    let mut i: ::core::ffi::c_uint = 0;
    let mut loc: GLint = 0;

    i = 0 as ::core::ffi::c_uint;
    while (i as usize) < ARRAY_SIZE!(texture_data) as usize {
        if (*args).texture_type == texture_data[i as usize].texture_target {
            tex_type = core::ptr::addr_of!(texture_data[i as usize].texture_type) as *const ::core::ffi::c_char;
            swizzle = core::ptr::addr_of!(texture_data[i as usize].texcoord_swizzle) as *const ::core::ffi::c_char;
            break;
        }
        i += 1;
    }
    if i as usize == ARRAY_SIZE!(texture_data) as usize {
        return 0;
    }

    program = ((*gl_info).gl_ops.ext.p_glCreateProgram.unwrap_unchecked())();

    vshader_id = ((*gl_info).gl_ops.ext.p_glCreateShader.unwrap_unchecked())(GL_VERTEX_SHADER as GLenum);

    buffer = string_buffer_get(core::ptr::addr_of_mut!((*blitter).string_buffers));
    shader_glsl_add_version_declaration(buffer, gl_info);
    shader_addline(buffer, b"%s vec2 pos;\n\0".as_ptr() as *const ::core::ffi::c_char, get_attribute_keyword(gl_info));
    shader_addline(buffer, b"%s vec3 texcoord;\n\0".as_ptr() as *const ::core::ffi::c_char, get_attribute_keyword(gl_info));
    declare_out_varying(gl_info, buffer, (FALSE) as BOOL, b"vec3 out_texcoord;\n\0".as_ptr() as *const ::core::ffi::c_char);
    shader_addline(buffer, vshader_main.as_ptr() as *const ::core::ffi::c_char);

    ptr = (*buffer).buffer as *const ::core::ffi::c_char;
    ((*gl_info).gl_ops.ext.p_glShaderSource.unwrap_unchecked())(vshader_id, 1 as GLsizei, core::ptr::addr_of_mut!(ptr) as *const *const GLchar, core::ptr::null::<GLint>());
    ((*gl_info).gl_ops.ext.p_glAttachShader.unwrap_unchecked())(program, vshader_id);
    ((*gl_info).gl_ops.ext.p_glDeleteShader.unwrap_unchecked())(vshader_id);

    fshader_id = ((*gl_info).gl_ops.ext.p_glCreateShader.unwrap_unchecked())(GL_FRAGMENT_SHADER as GLenum);

    string_buffer_clear(buffer);
    shader_glsl_add_version_declaration(buffer, gl_info);
    shader_addline(buffer, b"uniform sampler%s sampler;\n\0".as_ptr() as *const ::core::ffi::c_char, tex_type);
    if (*args).use_colour_key != 0 {
        shader_addline(buffer, b"uniform struct\n{\n\0".as_ptr() as *const ::core::ffi::c_char);
        shader_addline(buffer, b"    vec4 low, high;\n\0".as_ptr() as *const ::core::ffi::c_char);
        shader_addline(buffer, b"} colour_key;\n\0".as_ptr() as *const ::core::ffi::c_char);
    }
    declare_in_varying(gl_info, buffer, (FALSE) as BOOL, b"vec3 out_texcoord;\n\0".as_ptr() as *const ::core::ffi::c_char);
    /* TODO: Declare the out variable with the correct type (and put it in the
     * blitter args). */
    if use_legacy_fragment_output(gl_info) == 0 {
        shader_addline(buffer, b"out vec4 ps_out[1];\n\0".as_ptr() as *const ::core::ffi::c_char);
    }

    output = string_buffer_get(core::ptr::addr_of_mut!((*blitter).string_buffers));
    string_buffer_sprintf(output, b"%s[0]\0".as_ptr() as *const ::core::ffi::c_char, get_fragment_output(gl_info));

    match complex_fixup as ::core::ffi::c_uint {
        COMPLEX_FIXUP_P8 => {
            glsl_blitter_generate_p8_shader(buffer, gl_info, args, (*output).buffer, tex_type, swizzle);
        }
        COMPLEX_FIXUP_YUY2 | COMPLEX_FIXUP_UYVY | COMPLEX_FIXUP_YV12 | COMPLEX_FIXUP_NV12 | COMPLEX_FIXUP_YUV => {
            glsl_blitter_generate_yuv_shader(buffer, gl_info, args, (*output).buffer, tex_type, swizzle);
        }
        COMPLEX_FIXUP_NONE => {
            glsl_blitter_generate_plain_shader(buffer, gl_info, args, (*output).buffer, tex_type, swizzle);
        }
        _ => {}
    }

    string_buffer_release(core::ptr::addr_of_mut!((*blitter).string_buffers), output);

    ptr = (*buffer).buffer as *const ::core::ffi::c_char;
    ((*gl_info).gl_ops.ext.p_glShaderSource.unwrap_unchecked())(fshader_id, 1 as GLsizei, core::ptr::addr_of_mut!(ptr) as *const *const GLchar, core::ptr::null::<GLint>());
    string_buffer_release(core::ptr::addr_of_mut!((*blitter).string_buffers), buffer);
    ((*gl_info).gl_ops.ext.p_glAttachShader.unwrap_unchecked())(program, fshader_id);
    ((*gl_info).gl_ops.ext.p_glDeleteShader.unwrap_unchecked())(fshader_id);

    ((*gl_info).gl_ops.ext.p_glBindAttribLocation.unwrap_unchecked())(program, 0 as GLuint, b"pos\0".as_ptr() as *const GLchar);
    ((*gl_info).gl_ops.ext.p_glBindAttribLocation.unwrap_unchecked())(program, 1 as GLuint, b"texcoord\0".as_ptr() as *const GLchar);

    if use_legacy_fragment_output(gl_info) == 0 {
        ((*gl_info).gl_ops.ext.p_glBindFragDataLocation.unwrap_unchecked())(program, 0 as GLuint, b"ps_out\0".as_ptr() as *const GLchar);
    }

    ((*gl_info).gl_ops.ext.p_glCompileShader.unwrap_unchecked())(vshader_id);
    print_glsl_info_log(gl_info, vshader_id, (FALSE) as BOOL);
    ((*gl_info).gl_ops.ext.p_glCompileShader.unwrap_unchecked())(fshader_id);
    print_glsl_info_log(gl_info, fshader_id, (FALSE) as BOOL);
    ((*gl_info).gl_ops.ext.p_glLinkProgram.unwrap_unchecked())(program);
    shader_glsl_validate_link(gl_info, program);

    ((*gl_info).gl_ops.ext.p_glUseProgram.unwrap_unchecked())(program);
    loc = ((*gl_info).gl_ops.ext.p_glGetUniformLocation.unwrap_unchecked())(program, b"sampler\0".as_ptr() as *const GLchar);
    ((*gl_info).gl_ops.ext.p_glUniform1i.unwrap_unchecked())(loc, 0 as GLint);
    if complex_fixup as ::core::ffi::c_uint == COMPLEX_FIXUP_P8 as ::core::ffi::c_uint {
        loc = ((*gl_info).gl_ops.ext.p_glGetUniformLocation.unwrap_unchecked())(program, b"sampler_palette\0".as_ptr() as *const GLchar);
        ((*gl_info).gl_ops.ext.p_glUniform1i.unwrap_unchecked())(loc, 1 as GLint);
    }

    return program;
}

unsafe extern "C" fn glsl_blitter_upload_palette(
    mut blitter: *mut wined3d_glsl_blitter,
    mut context_gl: *mut wined3d_context_gl,
    mut texture_gl: *const wined3d_texture_gl,
) {
    let mut gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut palette: *const wined3d_palette = ::core::ptr::null::<wined3d_palette>();
    palette = if !(*texture_gl).t.swapchain.is_null() {
        (*(*texture_gl).t.swapchain).palette
    } else {
        ::core::ptr::null_mut::<wined3d_palette>()
    };
    if (*blitter).palette_texture == 0 {
        (*gl_info)
            .gl_ops
            .gl
            .p_glGenTextures
            .unwrap_unchecked()(
            1 as GLsizei,
            &raw mut (*blitter).palette_texture,
        );
    }
    wined3d_context_gl_active_texture(context_gl, gl_info, 1 as ::core::ffi::c_uint);
    (*gl_info)
        .gl_ops
        .gl
        .p_glBindTexture
        .unwrap_unchecked()(
        GL_TEXTURE_1D as GLenum,
        (*blitter).palette_texture,
    );
    (*gl_info)
        .gl_ops
        .gl
        .p_glTexParameteri
        .unwrap_unchecked()(
        GL_TEXTURE_1D as GLenum,
        GL_TEXTURE_MIN_FILTER as GLenum,
        GL_NEAREST as GLint,
    );
    (*gl_info)
        .gl_ops
        .gl
        .p_glTexParameteri
        .unwrap_unchecked()(
        GL_TEXTURE_1D as GLenum,
        GL_TEXTURE_MAG_FILTER as GLenum,
        GL_NEAREST as GLint,
    );
    (*gl_info)
        .gl_ops
        .gl
        .p_glTexParameteri
        .unwrap_unchecked()(
        GL_TEXTURE_1D as GLenum,
        GL_TEXTURE_WRAP_S as GLenum,
        GL_CLAMP_TO_EDGE as GLint,
    );

    ((*gl_info).gl_ops.ext.p_glBindBuffer.unwrap_unchecked())(
        GL_PIXEL_UNPACK_BUFFER,
        0,
    );
    checkGLcall!(gl_info, "glBindBuffer");

    if !palette.is_null() {
        (*gl_info)
            .gl_ops
            .gl
            .p_glTexImage1D
            .unwrap_unchecked()(
            GL_TEXTURE_1D as GLenum,
            0 as GLint,
            GL_RGB as GLint,
            256 as GLsizei,
            0 as GLint,
            GL_BGRA as GLenum,
            GL_UNSIGNED_INT_8_8_8_8_REV as GLenum,
            &raw const (*palette).colors as *const RGBQUAD as *const ::core::ffi::c_void,
        );
    } else {
        static mut black: DWORD = 0;
        WINE_FIXME!("P8 texture loaded without a palette.\n");
        (*gl_info)
            .gl_ops
            .gl
            .p_glTexImage1D
            .unwrap_unchecked()(
            GL_TEXTURE_1D as GLenum,
            0 as GLint,
            GL_RGB as GLint,
            1 as GLsizei,
            0 as GLint,
            GL_BGRA as GLenum,
            GL_UNSIGNED_INT_8_8_8_8_REV as GLenum,
            &raw const black as *const ::core::ffi::c_void,
        );
    }
    wined3d_context_gl_active_texture(context_gl, gl_info, 0 as ::core::ffi::c_uint);
}

unsafe extern "C" fn glsl_blitter_get_program(
    blitter: *mut wined3d_glsl_blitter,
    context_gl: *mut wined3d_context_gl,
    texture_gl: *const wined3d_texture_gl,
    use_colour_key: BOOL,
) -> *mut glsl_blitter_program {
    let gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut program: *mut glsl_blitter_program = core::ptr::null_mut();
    let mut args: glsl_blitter_args = core::mem::zeroed();
    let mut entry: *mut wine_rb_entry;

    memset(
        core::ptr::addr_of_mut!(args) as *mut core::ffi::c_void,
        0,
        core::mem::size_of::<glsl_blitter_args>(),
    );
    args.texture_type = (*texture_gl).target;
    args.fixup = (*(*texture_gl).t.resource.format).color_fixup;
    args.use_colour_key = use_colour_key as u16;

    entry = wine_rb_get(
        core::ptr::addr_of_mut!((*blitter).programs),
        core::ptr::addr_of!(args) as *const core::ffi::c_void,
    );
    if !entry.is_null() {
        return (entry as *mut core::ffi::c_char).offset(-(0 as isize))
            as *mut glsl_blitter_program;
    }

    program = malloc(core::mem::size_of::<glsl_blitter_program>())
        as *mut glsl_blitter_program;
    if program.is_null() {
        ERR!("Failed to allocate blitter program memory.\n");
        return core::ptr::null_mut();
    }

    core::ptr::copy_nonoverlapping(
        core::ptr::addr_of!(args),
        core::ptr::addr_of_mut!((*program).args),
        1,
    );
    (*program).id = glsl_blitter_generate_program(blitter, gl_info, core::ptr::addr_of_mut!(args));
    if (*program).id == 0 {
        WARN!("Failed to generate blitter program.\n");
        free(program as *mut core::ffi::c_void);
        return core::ptr::null_mut();
    }

    if wine_rb_put(
        core::ptr::addr_of_mut!((*blitter).programs),
        core::ptr::addr_of!((*program).args) as *const core::ffi::c_void,
        core::ptr::addr_of_mut!((*program).entry),
    ) == -1
    {
        ERR!("Failed to store blitter program.\n");
        ((*gl_info).gl_ops.ext.p_glDeleteProgram.unwrap_unchecked())((*program).id);
        free(program as *mut core::ffi::c_void);
        return core::ptr::null_mut();
    }

    return program;
}

unsafe extern "C" fn glsl_blitter_supported(
    mut blit_op: wined3d_blit_op,
    context: *const wined3d_context,
    src_texture: *const wined3d_texture_gl,
    src_location: DWORD,
    dst_texture: *const wined3d_texture_gl,
    dst_location: DWORD,
) -> BOOL {
    let src_resource: *const wined3d_resource = core::ptr::addr_of!((*src_texture).t.resource);
    let dst_resource: *const wined3d_resource = core::ptr::addr_of!((*dst_texture).t.resource);
    let src_format: *const wined3d_format = (*src_resource).format;
    let dst_format: *const wined3d_format = (*dst_resource).format;
    let mut src_ds: bool;
    let mut dst_ds: bool;
    let mut decompress: BOOL;

    if blit_op == WINED3D_BLIT_OP_RAW_BLIT && (*dst_format).id == (*src_format).id {
        src_ds = (*src_format).depth_size != 0 || (*src_format).stencil_size != 0;
        dst_ds = (*dst_format).depth_size != 0 || (*dst_format).stencil_size != 0;
        /* We could in principle support raw depth/stencil <-> colour blits as
         * well in some cases, but note that typeless formats like e.g.
         * R16_TYPELESS may use a normalised GL format for depth/stencil
         * resources, and a floating-point format for colour resources, */
        if src_ds && dst_ds {
            blit_op = WINED3D_BLIT_OP_DEPTH_BLIT;
        } else if !src_ds && !dst_ds {
            blit_op = WINED3D_BLIT_OP_COLOR_BLIT;
        }
    }

    if blit_op != WINED3D_BLIT_OP_COLOR_BLIT
        && blit_op != WINED3D_BLIT_OP_COLOR_BLIT_CKEY
        && blit_op != WINED3D_BLIT_OP_COLOR_BLIT_ALPHATEST
    {
        TRACE!("Unsupported blit_op %#x.\n", blit_op as u32);
        return (FALSE) as BOOL;
    }

    if (*src_resource).type_ != WINED3D_RTYPE_TEXTURE_2D {
        return (FALSE) as BOOL;
    }

    if (*src_texture).target == GL_TEXTURE_2D_MULTISAMPLE
        || (*src_texture).target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY
    {
        TRACE!("Multi-sample source textures not supported.\n");
        return (FALSE) as BOOL;
    }

    if (*dst_resource).access & WINED3D_RESOURCE_ACCESS_GPU == 0 {
        TRACE!("Destination resource does not have GPU access.\n");
        return (FALSE) as BOOL;
    }

    /* We don't necessarily want to blit from resources without
     * WINED3D_RESOURCE_ACCESS_GPU, but that may be the only way to decompress
     * compressed textures. */
    decompress = (((*src_format).attrs & WINED3D_FORMAT_ATTR_COMPRESSED) != 0
        && ((*dst_format).attrs & WINED3D_FORMAT_ATTR_COMPRESSED) == 0) as BOOL;
    if decompress == 0 && (*src_resource).access & WINED3D_RESOURCE_ACCESS_GPU == 0 {
        TRACE!("Source resource does not have GPU access.\n");
        return (FALSE) as BOOL;
    }

    if is_identity_fixup((*dst_format).color_fixup) == 0
        && ((*dst_format).id != (*src_format).id || dst_location != WINED3D_LOCATION_DRAWABLE)
    {
        TRACE!("Destination fixups are not supported.\n");
        return (FALSE) as BOOL;
    }

    if !(((*dst_format).caps[WINED3D_GL_RES_TYPE_TEX_2D as usize] & WINED3D_FORMAT_CAP_FBO_ATTACHABLE) != 0
        || ((*dst_resource).bind_flags & WINED3D_BIND_RENDER_TARGET) != 0)
    {
        TRACE!("Destination texture is not FBO attachable.\n");
        return (FALSE) as BOOL;
    }

    TRACE!("Returning supported.\n");
    return (TRUE) as BOOL;
}

unsafe extern "C" fn glsl_blitter_blit(
    blitter: *mut wined3d_blitter,
    op: wined3d_blit_op,
    context: *mut wined3d_context,
    src_texture: *mut wined3d_texture,
    src_sub_resource_idx: ::core::ffi::c_uint,
    src_location: DWORD,
    src_rect: *const RECT,
    dst_texture: *mut wined3d_texture,
    dst_sub_resource_idx: ::core::ffi::c_uint,
    dst_location: DWORD,
    dst_rect: *const RECT,
    colour_key: *const wined3d_color_key,
    filter: wined3d_texture_filter_type,
    resolve_format: *const wined3d_format,
) -> DWORD {
    let mut src_texture = src_texture;
    let mut src_sub_resource_idx = src_sub_resource_idx;
    let mut dst_rect = dst_rect;
    let mut colour_key = colour_key;
    let mut src_texture_gl: *mut wined3d_texture_gl = wined3d_texture_gl(src_texture);
    let mut dst_texture_gl: *mut wined3d_texture_gl = wined3d_texture_gl(dst_texture);
    let mut context_gl: *mut wined3d_context_gl = wined3d_context_gl(context);
    let mut device: *mut wined3d_device = (*dst_texture).resource.device;
    let mut gl_info: *const wined3d_gl_info = (*context_gl).gl_info;
    let mut staging_texture: *mut wined3d_texture = core::ptr::null_mut();
    let mut glsl_blitter: *mut wined3d_glsl_blitter = core::ptr::null_mut();
    let mut alpha_test_key: wined3d_color_key = core::mem::zeroed();
    let mut program: *mut glsl_blitter_program = core::ptr::null_mut();
    let mut next: *mut wined3d_blitter = core::ptr::null_mut();
    let mut src_level: ::core::ffi::c_uint = 0;
    let mut location: GLint = 0;
    let mut d: RECT = core::mem::zeroed();

    TRACE!("blitter %p, op %#x, context %p, src_texture %p, src_sub_resource_idx %u, src_location %s, src_rect %s, dst_texture %p, dst_sub_resource_idx %u, dst_location %s, dst_rect %s, colour_key %p, filter %s, resolve format %p.\n",
        blitter, op, context, src_texture, src_sub_resource_idx,
        wined3d_debug_location(src_location), wine_dbgstr_rect(src_rect),
        dst_texture, dst_sub_resource_idx,
        wined3d_debug_location(dst_location), wine_dbgstr_rect(dst_rect),
        colour_key, debug_d3dtexturefiltertype(filter), resolve_format);

    if glsl_blitter_supported(op, context, src_texture_gl, src_location, dst_texture_gl, dst_location) == 0 {
        next = (*blitter).next;
        if next.is_null() {
            ERR!("No blitter to handle blit op %#x.\n", op);
            return dst_location;
        }
        TRACE!("Forwarding to blitter %p.\n", next);
        return (*(*next).ops).blitter_blit.unwrap_unchecked()(
            next,
            op,
            context,
            src_texture,
            src_sub_resource_idx,
            src_location,
            src_rect,
            dst_texture,
            dst_sub_resource_idx,
            dst_location,
            dst_rect,
            colour_key,
            filter,
            resolve_format,
        );
    }

    glsl_blitter = (blitter as ULONG_PTR)
        .wrapping_sub(core::mem::offset_of!(wined3d_glsl_blitter, blitter) as ULONG_PTR)
        as *mut wined3d_glsl_blitter;

    if ((*src_texture).resource.access & WINED3D_RESOURCE_ACCESS_GPU) == 0 {
        let mut desc: wined3d_resource_desc = core::mem::zeroed();
        let mut upload_box: wined3d_box = core::mem::zeroed();
        let mut hr: HRESULT = 0;

        TRACE!("Source texture is not GPU accessible, creating a staging texture.\n");

        src_level = src_sub_resource_idx % (*src_texture).level_count;
        desc.resource_type = WINED3D_RTYPE_TEXTURE_2D;
        desc.format = (*(*src_texture).resource.format).id;
        desc.multisample_type = (*src_texture).resource.multisample_type;
        desc.multisample_quality = (*src_texture).resource.multisample_quality as ::core::ffi::c_uint;
        desc.usage = WINED3DUSAGE_CS;
        desc.bind_flags = 0;
        desc.access = WINED3D_RESOURCE_ACCESS_GPU;
        desc.width = wined3d_texture_get_level_width(src_texture, src_level);
        desc.height = wined3d_texture_get_level_height(src_texture, src_level);
        desc.depth = 1;
        desc.size = 0;

        hr = wined3d_texture_create(
            device,
            core::ptr::addr_of_mut!(desc),
            1,
            1,
            0,
            core::ptr::null(),
            core::ptr::null_mut(),
            core::ptr::addr_of!(wined3d_null_parent_ops),
            core::ptr::addr_of_mut!(staging_texture),
        );
        if hr < 0 {
            ERR!("Failed to create staging texture, hr %#lx.\n", hr);
            return dst_location;
        }

        wined3d_box_set(
            core::ptr::addr_of_mut!(upload_box),
            0,
            0,
            desc.width,
            desc.height,
            0,
            desc.depth,
        );
        wined3d_texture_upload_from_texture(
            staging_texture,
            0,
            0,
            0,
            0,
            src_texture,
            src_sub_resource_idx,
            core::ptr::addr_of_mut!(upload_box),
        );

        src_texture = staging_texture;
        src_texture_gl = wined3d_texture_gl(src_texture);
        src_sub_resource_idx = 0;
    } else {
        wined3d_texture_load(src_texture, context, (FALSE) as BOOL);
    }

    if wined3d_texture_is_full_rect(
        dst_texture,
        dst_sub_resource_idx % (*dst_texture).level_count,
        dst_rect,
    ) != false
    {
        wined3d_texture_prepare_location(dst_texture, dst_sub_resource_idx, context, dst_location);
    } else {
        wined3d_texture_load_location(dst_texture, dst_sub_resource_idx, context, dst_location);
    }

    context_gl_apply_texture_draw_state(context_gl, dst_texture, dst_sub_resource_idx, dst_location);
    wined3d_context_gl_apply_blit_state(context_gl, device);

    if dst_location == WINED3D_LOCATION_DRAWABLE {
        d = *dst_rect;
        wined3d_texture_translate_drawable_coords(dst_texture, (*context_gl).window, core::ptr::addr_of_mut!(d));
        dst_rect = core::ptr::addr_of!(d);
    }

    if op == WINED3D_BLIT_OP_COLOR_BLIT_ALPHATEST {
        let f: *const wined3d_format = (*src_texture).resource.format;

        alpha_test_key.color_space_low_value = 0;
        alpha_test_key.color_space_high_value =
            !(wined3d_mask_from_size((*f).alpha_size as ::core::ffi::c_uint) << (*f).alpha_offset)
                as ::core::ffi::c_uint;
        colour_key = core::ptr::addr_of!(alpha_test_key);
    } else if op != WINED3D_BLIT_OP_COLOR_BLIT_CKEY {
        colour_key = core::ptr::null();
    }

    program = glsl_blitter_get_program(
        glsl_blitter,
        context_gl,
        src_texture_gl,
        (!colour_key.is_null()) as ::core::ffi::c_int,
    );
    if program.is_null() {
        ERR!("Failed to get blitter program.\n");
        return dst_location;
    }

    ((*gl_info).gl_ops.ext.p_glUseProgram.unwrap_unchecked())((*program).id);

    match get_complex_fixup((*program).args.fixup) as ::core::ffi::c_uint {
        COMPLEX_FIXUP_P8 => {
            glsl_blitter_upload_palette(glsl_blitter, context_gl, src_texture_gl);
        }
        COMPLEX_FIXUP_YUY2
        | COMPLEX_FIXUP_UYVY
        | COMPLEX_FIXUP_YV12
        | COMPLEX_FIXUP_NV12
        | COMPLEX_FIXUP_YUV => {
            src_level = src_sub_resource_idx % (*src_texture).level_count;
            location = ((*gl_info).gl_ops.ext.p_glGetUniformLocation.unwrap_unchecked())(
                (*program).id,
                b"size\0".as_ptr() as *const GLchar,
            );
            ((*gl_info).gl_ops.ext.p_glUniform2f.unwrap_unchecked())(
                location,
                wined3d_texture_get_level_width(src_texture, src_level) as GLfloat,
                wined3d_texture_get_level_height(src_texture, src_level) as GLfloat,
            );
        }
        _ => {}
    }

    if !colour_key.is_null() {
        let mut float_key: [wined3d_color; 2] = core::mem::zeroed();

        wined3d_format_get_float_color_key(
            (*src_texture).resource.format,
            colour_key,
            core::ptr::addr_of_mut!(float_key) as *mut wined3d_color,
        );
        location = ((*gl_info).gl_ops.ext.p_glGetUniformLocation.unwrap_unchecked())(
            (*program).id,
            b"colour_key.low\0".as_ptr() as *const GLchar,
        );
        ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
            location,
            1,
            core::ptr::addr_of_mut!(float_key[0].r),
        );
        location = ((*gl_info).gl_ops.ext.p_glGetUniformLocation.unwrap_unchecked())(
            (*program).id,
            b"colour_key.high\0".as_ptr() as *const GLchar,
        );
        ((*gl_info).gl_ops.ext.p_glUniform4fv.unwrap_unchecked())(
            location,
            1,
            core::ptr::addr_of_mut!(float_key[1].r),
        );
    }

    wined3d_context_gl_draw_shaded_quad(context_gl, src_texture_gl, src_sub_resource_idx, src_rect, dst_rect, filter);
    ((*gl_info).gl_ops.ext.p_glUseProgram.unwrap_unchecked())(0);

    if !(*dst_texture).swapchain.is_null()
        && (*(*dst_texture).swapchain).front_buffer == dst_texture
    {
        (*gl_info).gl_ops.gl.p_glFlush.unwrap_unchecked()();
    }

    if !staging_texture.is_null() {
        wined3d_texture_decref(staging_texture);
    }

    return dst_location;
}

unsafe extern "C" fn glsl_blitter_clear(
    blitter: *mut wined3d_blitter,
    device: *mut wined3d_device,
    rt_count: ::core::ffi::c_uint,
    fb: *const wined3d_fb_state,
    rect_count: ::core::ffi::c_uint,
    clear_rects: *const RECT,
    draw_rect: *const RECT,
    flags: uint32_t,
    color: *const wined3d_color,
    depth: ::core::ffi::c_float,
    stencil: ::core::ffi::c_uint,
) {
    let mut next: *mut wined3d_blitter = core::ptr::null_mut();
    next = (*blitter).next;
    if !next.is_null() {
        (*(*next).ops)
            .blitter_clear
            .unwrap_unchecked()(
            next,
            device,
            rt_count,
            fb,
            rect_count,
            clear_rects,
            draw_rect,
            flags,
            color,
            depth,
            stencil,
        );
    }
}
#[no_mangle]
pub unsafe extern "C" fn wined3d_glsl_blitter_create(
    next: *mut *mut wined3d_blitter,
    device: *const wined3d_device,
) -> *mut wined3d_blitter {
    let gl_info: *const wined3d_gl_info = &raw const (*wined3d_adapter_gl((*device).adapter)).gl_info;
    let mut blitter: *mut wined3d_glsl_blitter = core::ptr::null_mut();

    if (*device).shader_backend != &raw const glsl_shader_backend {
        return core::ptr::null_mut();
    }

    if (*gl_info).supported[ARB_VERTEX_SHADER as usize] == 0
        || (*gl_info).supported[ARB_FRAGMENT_SHADER as usize] == 0
    {
        return core::ptr::null_mut();
    }

    blitter = malloc(core::mem::size_of::<wined3d_glsl_blitter>() as size_t)
        as *mut wined3d_glsl_blitter;
    if blitter.is_null() {
        ERR!("Failed to allocate blitter.\n");
        return core::ptr::null_mut();
    }

    (*blitter).blitter.ops = &raw const glsl_blitter_ops as *const wined3d_blitter_ops;
    (*blitter).blitter.next = *next;
    string_buffer_list_init(&raw mut (*blitter).string_buffers);
    wine_rb_init(
        &raw mut (*blitter).programs,
        Some(
            glsl_blitter_args_compare
                as unsafe extern "C" fn(*const core::ffi::c_void, *const rb_entry) -> core::ffi::c_int,
        ),
    );
    (*blitter).palette_texture = 0 as GLuint;
    *next = &raw mut (*blitter).blitter;

    return *next;
}
